DAY_CLOSE_QUIET_HOURS = 6
DAY_CLOSE_GRACE_TIME = datetime.time(12, 0)   # next-day noon floor (local)


def _apply_pragmas(conn):
    """Uniform hardening PRAGMAs for every kit_life connection (F1).
    journal_mode=WAL serializes cross-process writers; busy_timeout gives the
    C layer a backstop; foreign_keys stays ON (legacy contract)."""
    conn.execute("PRAGMA foreign_keys = ON;")
    conn.execute("PRAGMA journal_mode = WAL;")
    conn.execute("PRAGMA busy_timeout = %d;" % BUSY_TIMEOUT_MS)


def get_conn():
    """kit_life.db 연결(단일 진입점). WAL + busy_timeout=5000 + foreign_keys ON.

    시그니처/반환은 기존과 동일(무인자, sqlite3.Connection 반환, 파일 없으면
    stderr 후 exit(1)) -- 기존 호출부 무변경. 하드닝 PRAGMA 만 추가된다."""
    if not os.path.isfile(DB_PATH):
        print(f"kit_life.db 없음 ({DB_PATH})", file=sys.stderr)
        sys.exit(1)
    conn = sqlite3.connect(DB_PATH)
    _apply_pragmas(conn)
    return conn


def is_busy(err):
    s = str(err).lower()
    return ("database is locked" in s) or ("database is busy" in s)


def with_retry(fn, budget=RETRY_BUDGET):
    """Bounded SQLITE_BUSY retry wrapper. On budget exhaustion, re-raises the
    original sqlite3.OperationalError verbatim (M6: preserve caller exception
    semantics -- callers that catch OperationalError keep working)."""
    retries = 0
    while True:
        try:
            return fn()
        except sqlite3.OperationalError as e:
            if is_busy(e) and retries < budget:
                retries += 1
                time.sleep(RETRY_BASE_SLEEP * (1 + (os.getpid() % 7)) * retries * 0.1
                           + RETRY_BASE_SLEEP)
                continue
            raise


def area_id(conn, name):
    """영역명 → id (없으면 None)."""
    row = conn.execute(
        "SELECT id FROM areas WHERE name=? LIMIT 1;", (name,)).fetchone()
    return row[0] if row else None


# ── 숫자 정규화 (kit_life.sh num() 재현: 비었거나 숫자 아니면 기본값) ──
def _num(v, default=0.0):
    if v is None:
        return default
    s = str(v).strip()
    if s == '':
        return default
    try:
        return float(s)
    except ValueError:
        return default


def _opt_num(v):
    """빈 값이면 None(=SQL NULL), 아니면 숫자. kit_life.sh의 grams NULL 처리 재현."""
    if v is None:
        return None
    s = str(v).strip()
    if s == '':
        return None
    try:
        return float(s)
    except ValueError:
        return 0.0


def _txt(v):
    """빈 문자열이면 None(=NULL). kit_life.sh txt() 재현."""
    if v is None:
        return None
    s = str(v)
    return None if s == '' else s


def _f0(x):
    """SQLite/C printf('%.0f') 재현: 0.5 단위는 0에서 멀어지게 반올림(half-away-from-zero).
    Python의 %.0f(half-to-even)와 다르므로 Decimal ROUND_HALF_UP로 맞춘다."""
    q = Decimal(str(float(x))).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    return f"{q}"


def _f0n(x):
    """_f0 for a value that may be absent: None -> '' (064: a not-entered
    workouts.kcal prints as an empty field, never as a fabricated 0)."""
    return '' if x is None else _f0(x)


def _fp0(x):
    """printf('%+.0f') 재현: 부호 강제 + half-away-from-zero. 0은 +0."""
    q = Decimal(str(float(x))).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    return f"+{q}" if q >= 0 else f"{q}"


