def _health_agent_crew(conn=None):
    """The crew-level health-domain OVERRIDE from the shared DB's config table,
    or None. Never raises and never exits: a missing DB, a missing table or a
    malformed value all mean "not set" so the caller falls through. Uses `conn`
    when given (same transaction, no second lock)."""
    own = None
    try:
        if conn is None:
            if not os.path.isfile(DB_PATH):
                return None
            own = sqlite3.connect(DB_PATH, timeout=5)
            conn = own
        row = conn.execute("SELECT value FROM config WHERE key=? LIMIT 1;",
                           (HEALTH_DOMAIN_AGENT_KEY,)).fetchone()
    except sqlite3.Error:
        return None
    finally:
        if own is not None:
            own.close()
    val = (row[0] if row else None) or ""
    val = str(val).strip()
    return val if _AGENT_SLUG_RE.match(val) else None


def _instance_conf_read(root):
    """KEY -> VALUE from <root>/.instance.conf. First line per key wins (the
    framework's _conf_get convention); comments and blank lines skipped. {} on
    any read error -- never raises."""
    out = {}
    try:
        with open(os.path.join(root, ".instance.conf"), encoding="utf-8",
                  errors="replace") as fh:
            for line in fh:
                line = line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                k, v = line.split("=", 1)
                k = k.strip()
                if k and k not in out:
                    out[k] = v.strip().strip('"').strip("'")
    except (OSError, ValueError):
        return {}
    return out


def _health_pack_installed():
    """True when a member of this kit's crew (solo: this instance) lists
    pack_health in DOGANY_PACKS -- the same read _health_agent_derive does."""
    _reg, roots = _health_crew_members()
    for root in roots:
        packs = _instance_conf_read(root).get("DOGANY_PACKS", "")
        if any(p.strip().split("@", 1)[0] == HEALTH_DOMAIN_PACK
               for p in packs.split(",") if p.strip()):
            return True
    return False


def _health_crew_members():
    """(registry, [instance roots]). The kit already knows its crew through its
    DB: a crew member's database/kit_life.db links to
    <crews>/<kit>/kit_life.db and crew.conf sits beside it, one member=<root>
    line per member. A DB that is not in a crew dir is a solo instance whose
    only member is this instance (the parent of the database dir, the same root
    routine_roller reads .instance.conf from). Never raises."""
    try:
        conf = os.path.join(os.path.dirname(os.path.realpath(DB_PATH)),
                            "crew.conf")
        if os.path.isfile(conf):
            roots = []
            with open(conf, encoding="utf-8", errors="replace") as fh:
                for line in fh:
                    line = line.strip()
                    if line.startswith("member="):
                        r = line[len("member="):].strip()
                        if r and r not in roots:
                            roots.append(r)
            return conf, roots
    except (OSError, ValueError):
        return "unreadable", []
    root = os.path.dirname(SCRIPT_DIR)
    return "solo:" + root, [root]


def _health_agent_derive(roots):
    """(slug, fact) or (None, why-not). Pure over the members' .instance.conf.
    Rule (owner ruling 2026-09-24): exactly one member carries a pack_health@
    entry in DOGANY_PACKS -> that member; else exactly one member is
    DOGANY_AGENT_CLASS=main (missing class = main, the framework convention:
    mint writes 'domain' only for domain agents) -> that member; else none."""
    health, main = [], []
    for root in roots:
        conf = _instance_conf_read(root)
        name = conf.get("DOGANY_AGENT_NAME", "").strip().lower()
        if not _AGENT_SLUG_RE.match(name):
            continue
        packs = [p.strip() for p in conf.get("DOGANY_PACKS", "").split(",")]
        if any(p.split("@", 1)[0] == HEALTH_DOMAIN_PACK for p in packs if p):
            if name not in health:
                health.append(name)
        klass = (conf.get("DOGANY_AGENT_CLASS", "") or "main").strip().lower()
        if klass == "main" and name not in main:
            main.append(name)
    notes = []
    if len(health) == 1:
        return health[0], "%s member %s" % (HEALTH_DOMAIN_PACK, health[0])
    if health:
        notes.append("%s ambiguous (%s)" % (HEALTH_DOMAIN_PACK,
                                             ",".join(health)))
    else:
        notes.append("no %s member" % HEALTH_DOMAIN_PACK)
    if len(main) == 1:
        notes.append("sole main member %s" % main[0])
        return main[0], "; ".join(notes)
    notes.append("main ambiguous (%s)" % ",".join(main) if main
                 else "no main member")
    return None, "; ".join(notes)


def _health_agent_derived():
    """(slug, fact) or (None, why-not) from machine facts; read-only, cheap,
    never raises. Cached per process per registry (a process never outlives a
    mint, and a stale answer here only delays a handover to the next write)."""
    try:
        registry, roots = _health_crew_members()
        hit = _HEALTH_DERIVED_CACHE.get(registry)
        if hit is None:
            hit = _health_agent_derive(roots)
            _HEALTH_DERIVED_CACHE[registry] = hit
        return hit
    except Exception as exc:   # a fact we cannot read decides nothing
        return None, "derive failed (%s)" % type(exc).__name__


def _health_agent_resolve_full(conn=None):
    """(slug, source, fact). source = 'env' | 'crew' | 'derived' | 'default';
    fact = the machine fact that won (derived) or why derivation fell through
    (default), '' otherwise."""
    env = os.environ.get(HEALTH_DOMAIN_AGENT_ENV)
    if env and env.strip():
        return env.strip(), "env", ""
    crew = _health_agent_crew(conn)
    if crew:
        return crew, "crew", ""
    slug, fact = _health_agent_derived()
    if slug:
        return slug, "derived", fact
    return _HEALTH_DOMAIN_AGENT_DEFAULT, "default", fact


def _health_agent_resolve(conn=None):
    """(slug, source) where source is 'env' | 'crew' | 'derived' | 'default'."""
    return _health_agent_resolve_full(conn)[:2]


def _health_agent(conn=None):
    """The slug a HEALTH-DOMAIN row carries (meal / workout / metric / health
    routine_def), for READ paths. Write paths use _health_agent_write. See
    HEALTH_DOMAIN_AGENT_ENV above."""
    return _health_agent_resolve(conn)[0]


def _health_owner_recorded(conn):
    """The last crew-wide owner a health write recorded, '' when never recorded,
    or None when the config table cannot be read (no handover then)."""
    try:
        row = conn.execute("SELECT value FROM config WHERE key=? LIMIT 1;",
                           (HEALTH_DOMAIN_OWNER_RECORD_KEY,)).fetchone()
    except sqlite3.Error:
        return None
    return str((row[0] if row else "") or "").strip()


def _health_domain_handover(conn, new):
    """Move the health domain to `new` on `conn`, INSIDE the caller's
    transaction (the caller commits; a crash before that commit leaves the old
    state whole). No-op when `new` is already the recorded owner. On the FIRST
    record (nothing recorded yet) the rows moved are the retired 'warg' ones.
    Returns {label: rows relabeled} or None for a no-op."""
    old = _health_owner_recorded(conn)
    if old is None or old == new:
        return None
    old = old or _HEALTH_DOMAIN_AGENT_RETIRED
    moved = {}
    if old != new:
        for label, table, sql in _HEALTH_DOMAIN_RELABEL:
            if conn.execute("SELECT 1 FROM sqlite_master WHERE type='table' "
                            "AND name=?;", (table,)).fetchone():
                moved[label] = conn.execute(sql, (new, old)).rowcount
    conn.execute(
        "INSERT INTO config (key, value) VALUES (?, ?) "
        "ON CONFLICT(key) DO UPDATE SET value=excluded.value, "
        "updated_at=datetime('now','localtime');",
        (HEALTH_DOMAIN_OWNER_RECORD_KEY, new))
    return moved


def _health_agent_write(conn):
    """The owner to stamp on a health-domain row about to be written on `conn`,
    with the handover folded into the SAME transaction: call it before the
    write's commit, never after. Only crew-wide sources (crew override,
    derived) move history -- an env override is one process's business and
    the default means "no fact decides"; neither may relabel the crew's rows."""
    slug, source, _fact = _health_agent_resolve_full(conn)
    if source in ("crew", "derived"):
        _health_domain_handover(conn, slug)
    return slug


# InBody segmental keys (health-log vocabulary): lean mass per segment
# and the sheet's own "% of standard" for that segment. Declared here so the
# write echoes what the sheet printed (88.5, not 89); body-segment reads the
# _pct key back as standard_pct.
_SEGMENT_KEYS = ("arm_l", "arm_r", "trunk", "leg_l", "leg_r")
_METRIC_ECHO_DECIMALS = dict(
    [("lean_%s_kg" % sg, 1) for sg in _SEGMENT_KEYS]
    + [("lean_%s_pct" % sg, 1) for sg in _SEGMENT_KEYS])


def _metric_echo(metric, value):
    """log-metric's echo of the value it just STORED.  A guided metric
    declares its display resolution in _CADENCE_GUIDED (a few InBody keys in
    _METRIC_ECHO_DECIMALS); render the stored value on that grid
    (half-away-from-zero, the _f0 idiom).  A metric with no declared
    resolution keeps the legacy %.0f echo byte-identical -- fail-closed to
    the old contract, never an invented precision."""
    guided = _CADENCE_GUIDED.get(metric)
    if guided is None and metric in _METRIC_ECHO_DECIMALS:
        guided = (None, None, None, None, _METRIC_ECHO_DECIMALS[metric])
    if guided is None:
        return _f0(_num(value))
    dec = guided[4]
    q = Decimal(str(_num(value))).quantize(
        Decimal(1).scaleb(-dec), rounding=ROUND_HALF_UP)
    return f"{q}"


def _cadence_declare_fixed(conn, metrics):
    """Module-declared FIXED cadence, written at the module's own touchpoint.

    INSERT OR IGNORE is the whole discipline: an existing row -- above all a
    row the USER declared -- is never trampled.  FK note: OR IGNORE does not
    swallow a foreign-key violation, so tokens are filtered to ones
    metric_def actually holds (the diet cargo is seeded in schema.sql, but a
    stray token must fail closed here, not crash the meal write)."""
    for tok in metrics:
        if tok not in _CADENCE_FIXED:
            continue
        if conn.execute("SELECT 1 FROM metric_def WHERE token=?",
                        (tok,)).fetchone() is None:
            continue
        conn.execute(
            "INSERT OR IGNORE INTO metric_freshness"
            "(metric, stale_after_hours, declared_by, note) VALUES (?,?,?,?)",
            (tok, _CADENCE_FIXED_HOURS, 'module',
             'structurally daily: the recording act itself is daily (diet)'))


def _meal_kcal(vals):
    """구 meals.kcal 의 GENERATED 정의를 그대로 계산한다 -- 순탄수 + 알코올.
    이 식은 schema.sql 의 생성 컬럼과 ** 반드시 같아야 한다 ** ."""
    g = lambda k: float(vals.get(k) or 0)
    return round(g('protein') * 4 + g('fat') * 9
                 + (g('carb') - g('fiber')) * 4 + g('alcohol') * 7, 2)


def _meal_observed_instant(date):
    """measure.observed_at for a meal row: the meal day's LOCAL midnight as a
    canonical UTC-Z instant, resolved through the instance's DECLARED offset
    (AGENT_TZ_OFFSET_HOURS in config/agent.conf, read via agent_conf -- the
    same reader every other kit knob uses, env override included).  The
    judgment layer (037/038) reads observed_at as an INSTANT; writing the
    bare local day made the read side floor it to a UTC day start, which
    between 00:00 and 09:00 local on a UTC+9 estate is a FUTURE instant --
    the 9h/day fail-open 038 closes.  Resolving the offset at WRITE time
    removes the ambiguity for every new row (2026-09-08 06:48 owner rule:
    resolve from the configured value; no fourth clock, no hardcoded +9).
    Fail-CLOSED when the offset is UNDECLARED, absurd (outside -12..+14, a
    typo'd knob) or the date is not a bare YYYY-MM-DD: return the date-only
    grade byte-identical to pre-2.1.2 (agent_conf's zero-delta contract).
    NEVER silently assume 0 -- a 0-offset instant fabricated for a KST day
    is the exact fail-open being closed; the 038 read side treats the honest
    date-only grade's ambiguity as stale, never fresh."""
    off = agent_conf.conf_int("AGENT_TZ_OFFSET_HOURS", None)
    if off is None or not -12 <= off <= 14:
        return date
    try:
        day = datetime.datetime.strptime(str(date), "%Y-%m-%d")
    except (TypeError, ValueError):
        return date
    return (day - datetime.timedelta(hours=off)).strftime(
        "%Y-%m-%dT%H:%M:%SZ")


def _meal_write_v32(conn, date, meal, name, vals, owning_agent=None,
                    notion_id=None, block_id=None):
    """meals 한 건을 v3.2 축에 쓴다. block_id 가 주어지면 그 블록을 갱신한다.
    반환: block.id"""
    now = now_utc()
    if block_id is None:
        cur = conn.execute(
            "INSERT INTO block(ulid, source_module, title, date, kind_token, "
            "settled_at, settled_outcome, settled_by, settled_verdict, created_at) "
            "VALUES (?,?,?,?,?,?,?,?,?,?)",
            (new_ulid(), 'diet', name, date, 'record',
             now, 'done', 'meal-record', 'machine', now))
        block_id = cur.lastrowid
    else:
        conn.execute("UPDATE block SET title=?, date=? WHERE id=?",
                     (name, date, block_id))
        # cut 3: a pointing record's ts is a cached copy of this block's
        # event time -- refresh it in the SAME tx so a date fix (meal-upd)
        # never leaves a drifted pointer.
        conn.execute(
            "UPDATE record SET ts=? WHERE source_table='block' AND source_id=?;",
            (date, block_id))
        conn.execute("DELETE FROM measure WHERE block_id=?", (block_id,))
        conn.execute("DELETE FROM block_delta WHERE block_id=?", (block_id,))
    for tok, unit in (('meal_slot', meal), ('notion_id', notion_id),
                      ('owning_agent', owning_agent)):
        if unit is not None and unit != '':
            conn.execute(
                "INSERT OR REPLACE INTO block_attr(block_id, attr_token, value, source) "
                "VALUES (?,?,?,'user')", (block_id, tok, str(unit)))
    # 038: the judgment layer reads observed_at as an INSTANT -- resolve the
    # owner's local day through the declared offset (fail-closed to the
    # date-only grade when undeclared; see _meal_observed_instant).
    observed = _meal_observed_instant(date)
    for m, u in _MEAL_MEASURES:
        v = vals.get(m)
        if v is None:
            continue
        conn.execute(
            "INSERT INTO measure(metric, value, unit, block_id, observed_at, "
            "source, value_origin) VALUES (?,?,?,?,?,?,?)",
            (m, float(v), u, block_id, observed, 'module:diet', 'measured'))
    # kcal 0.0 은 ** 측정된 0 ** 이다(사이리움/크레아틴/제로콜라). 없음이 아니다 --
    # truthiness 로 거르면 측정된 0 이 부재로 바뀐다(이관기 주석과 같은 판정).
    kcal = _meal_kcal(vals)
    if kcal is not None:
        conn.execute(
            "INSERT INTO block_delta(block_id, resource, amount, unit, component, "
            "value_origin) VALUES (?,?,?,?,?,?)",
            (block_id, 'nutrition', kcal, 'kcal', 'intake', 'measured'))
        # 2.15.0 -- the SAME value, also in measure, for the same reason
        # 2.13.0 gave the workouts lane: measure is the home the JUDGEMENT
        # layer reads (037 S1), and block_delta is the resource-flow axis
        # (039).  Without this row the diet domain could never be judged --
        # v_criterion_verdict saw no kcal at all, which is why the calorie
        # criterion had nothing to be judged against even once its period
        # was corrected.  block_delta stays the flow store of record and
        # every existing reader keeps reading it; this is a SHADOW written
        # in the SAME tx, and the UPDATE path above already deleted the
        # block's measure rows, so an edit refreshes it with no drift.
        # value_origin 'computed', not 'measured': kcal is DERIVED from the
        # macro rows by _meal_kcal (provenance.recomputable=1 says exactly
        # that), while the macros themselves are what was measured.
        # NO metric_freshness row is declared for kcal_intake (unlike the
        # macros below): since 045 the accrued PERIOD arm does not read
        # cadence at all, so a row here would govern nothing -- the dead-knob
        # shape 044 refused for week_start.  A future POINT criterion on
        # kcal_intake would stay silent until a cadence is declared, which
        # is the fail-CLOSED answer, not a defect.
        _criterion_metric_ensure(conn, 'kcal_intake')
        conn.execute(
            "INSERT INTO measure(metric, value, unit, basis, block_id, "
            "observed_at, source, value_origin) "
            "VALUES ('kcal_intake', ?, 'kcal', 'actual', ?, ?, "
            "'module:diet', 'computed')",
            (float(kcal), block_id, observed))
    # Fixed-class cadence: diet is structurally daily, so the module declares
    # the interval HERE, at its own write, silently -- never asked, never
    # seeded by a migration (cut-1 freshness hooks; see _CADENCE_FIXED).
    _cadence_declare_fixed(conn, [m for m, _u in _MEAL_MEASURES
                                  if vals.get(m) is not None])
    return block_id


def meal_add(date, meal, name, carb=0, protein=0, fat=0,
             fiber=0, sugar=0, alt_sugar=0, grams=None, alcohol=0, conn=None,
             allow_unlooked=False, allow_unsated=False):
    """식단 한 건 기록(area=식습관 자동). kcal은 DB generated. 새 행 id 반환.

    alcohol=순수 알코올 그램(선택, 7kcal/g). 술류는 volume_ml×ABV×0.789로 구해 넘긴다.
    미지정이면 0. 탄수는 실제 탄수 그램 그대로(알코올을 탄수에 접지 말 것).

    043 (DGN-928): `name` 에 대해 조회 단계가 실제로 돈 영수증
    (meal_lookup_receipt) 이 없으면 아무것도 쓰지 않고 LookupSkippedError 를
    올린다 -- 순서를 산문이 아니라 실행 지점에 건다. allow_unlooked=True 는
    그 전제를 명시적으로 면제하고(호출부 무변경 보장), 영수증 레인 자체가
    고장 나면(표 없음/DB 오류) 판정을 못 하므로 fail-OPEN 으로 그대로 기록한다
    -- the owner must never be left unable to log a meal.

    048: 그 이름의 영수증이 'estimate' 로 등급된 경우(조회는 돌았고 아무것도
    못 찾아서 뒤따르는 매크로가 추정이라는 뜻)에만, 그 끼니의 포만감 답이
    있는지 본다. 없으면 역시 쓰기 전에 SatietySkippedError. 등급이 'exact'
    이거나 아예 없으면(pre-048 행·레인 고장) 아무 것도 안 묻는다 -- 모르는
    것은 허가로 읽는다. allow_unsated=True 가 명시적 면제다."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        if not allow_unlooked and lookup_receipt_check(conn, name) is False:
            # BEFORE the write: nothing partial survives a refusal.
            raise LookupSkippedError(name)
        # 048: the second precondition, same place and same discipline as the
        # first -- checked before the write, fail-open on anything unknown.
        # Order matters: an unlooked name has no grade to read, so the lookup
        # refusal above must win rather than both firing on one call.
        if (not allow_unsated
                and lookup_receipt_grade(conn, name) == 'estimate'
                and satiety_read(date, _txt(meal)) is None):
            raise SatietySkippedError(date, meal, name)
        # v3.2: meals 표가 아니라 block+measure+delta 로 나간다. area_id 는
        # v3.2 에 자리가 없다(UNMAPPED O-7) -- 도메인 귀속은 block_domain 이 맡는다.
        vals = {'carb': _num(carb), 'protein': _num(protein), 'fat': _num(fat),
                'fiber': _num(fiber), 'sugar': _num(sugar),
                'alt_sugar': _num(alt_sugar), 'alcohol': _num(alcohol),
                'portion_grams': _opt_num(grams)}
        # meal = health domain. The owner is the DOMAIN's owner, always --
        # ag/warg is just a capture surface, and the capturer is provenance,
        # not owner (owner directive 2026-08-20). See _health_agent().
        bid = _meal_write_v32(conn, date, _txt(meal), name, vals,
                              owning_agent=_health_agent_write(conn))
        conn.commit()
        # cut 3 lock 3: capture is COMMITTED above -- containment runs after,
        # additive and non-blocking (a raise in there never breaks the write).
        _meal_autolink_safe(conn, bid)
        return bid
    finally:
        if own:
            conn.close()


def meal_get(conn, mid):
    return conn.execute("SELECT * FROM " + MEALS_V32 + " WHERE id=?;", (mid,)).fetchone()


def meal_find(date, conn=None):
    """그날 식단 목록 (id, name, meal, kcal) 튜플 리스트."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        return conn.execute(
            "SELECT id, name, COALESCE(meal,''), kcal "
            "FROM " + MEALS_V32 + " WHERE date=? ORDER BY id;", (date,)).fetchall()
    finally:
        if own:
            conn.close()


def meal_day(date, conn=None):
    """그날 식단 (사람용 라인 리스트)."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        rows = conn.execute(
            "SELECT id, meal, name, kcal, protein, carb, fat "
            "FROM " + MEALS_V32 + " WHERE date=? ORDER BY id;", (date,)).fetchall()
        out = []
        for mid, meal, name, kcal, protein, carb, fat in rows:
            out.append(
                f"[{mid}] {meal or '?'} · {name}"
                f"  ({_f0(kcal)}kcal 단{_f0(protein)} 탄{_f0(carb)} 지{_f0(fat)})")
        return out
    finally:
        if own:
            conn.close()


def _block_record_del(conn, block_id):
    """026 polymorphic-integrity guard #1 for the 'block' source token: when a
    block row dies, its pointing record row dies in the SAME tx -- no FK backs
    the polymorphic pointer, so a survivor would dangle and a later rowid
    reuse would silently re-bind evidence. record_event links cascade off the
    record row (junction-only, foreign_keys=ON)."""
    conn.execute(
        "DELETE FROM record WHERE source_table='block' AND source_id=?;",
        (int(block_id),))


def meal_del(mid, conn=None):
    own = conn is None
    if own:
        conn = get_conn()
    try:
        # v3.2: block 하나를 지우면 measure/block_delta/block_attr 이
        # ON DELETE CASCADE 로 따라간다 -- 조각을 손으로 지우지 않는다.
        cur = conn.execute(
            "DELETE FROM block WHERE id=? AND settled_by='meal-record';",
            (int(mid),))
        if cur.rowcount:
            _block_record_del(conn, mid)
        conn.commit()
    finally:
        if own:
            conn.close()


# 부분 업데이트 허용 컬럼 → 값 변환기. kcal은 generated라 제외.
_MEAL_UPD_COLS = {
    'date': _txt, 'meal': _txt, 'name': _txt,
    'carb': _num, 'protein': _num, 'fat': _num, 'fiber': _num,
    'sugar': _num, 'alt_sugar': _num, 'alcohol': _num,
    'grams': _opt_num,
}


def meal_upd(mid, fields, conn=None):
    """식단 한 건의 지정 필드만 갱신(부분 업데이트). fields=={컬럼:원본값}.
    kcal은 파생이라 갱신 대상에서 제외(자동 재계산). 갱신 후 행 반환(없으면 None).

    v3.2 (036): meals 표는 없다 -- 현재값을 MEALS_V32 표면에서 읽어 병합한 뒤
    _meal_write_v32 로 그 블록을 통째로 다시 쓴다 (측정 행 전체 교체; 부분
    UPDATE 를 measure 조각마다 흉내내면 갱신 경로가 둘이 된다)."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        merged = {}
        for col, raw in fields.items():
            if col not in _MEAL_UPD_COLS:
                raise ValueError(f"수정 불가 컬럼: {col}")
            merged[col] = _MEAL_UPD_COLS[col](raw)
        if not merged:
            raise ValueError("갱신할 필드가 없음")
        row = conn.execute(
            "SELECT id, date, meal, name, notion_id, owning_agent "
            "FROM " + MEALS_V32 + " WHERE id=?;", (int(mid),)).fetchone()
        if row is None:
            return None
        bid, date, meal, name, notion_id, owning_agent = row
        meas = dict(conn.execute(
            "SELECT metric, value FROM measure WHERE block_id=?;", (bid,)))
        cur = {'date': date, 'meal': meal, 'name': name,
               'carb': meas.get('carb'), 'protein': meas.get('protein'),
               'fat': meas.get('fat'), 'fiber': meas.get('fiber'),
               'sugar': meas.get('sugar'), 'alt_sugar': meas.get('alt_sugar'),
               'alcohol': meas.get('alcohol'),
               'grams': meas.get('portion_grams')}
        cur.update(merged)
        vals = {'carb': _num(cur['carb'] or 0), 'protein': _num(cur['protein'] or 0),
                'fat': _num(cur['fat'] or 0), 'fiber': _num(cur['fiber'] or 0),
                'sugar': _num(cur['sugar'] or 0),
                'alt_sugar': _num(cur['alt_sugar'] or 0),
                'alcohol': _num(cur['alcohol'] or 0),
                'portion_grams': _opt_num(cur['grams'])}
        _meal_write_v32(conn, cur['date'], _txt(cur['meal']), cur['name'], vals,
                        owning_agent=owning_agent or _health_agent_write(conn),
                        notion_id=notion_id, block_id=bid)
        conn.commit()
        # cut 3 lock 3: a date/slot FIX can move the meal into a declared
        # event's span -- same additive post-commit containment as meal_add.
        # (Removal stays the owner's act: a move OUT never auto-detaches.)
        _meal_autolink_safe(conn, bid)
        return conn.execute("SELECT id, name, kcal FROM " + MEALS_V32 + " WHERE id=?;",
                            (int(mid),)).fetchone()
    finally:
        if own:
            conn.close()


# ── 예정(planned) 식단 마커 ────────────────────────────────
# meals 에는 planned/status 컬럼이 없다. 소유자 결정(2026-08-25): 스키마를 건드리는
# 대신 "예정 항목도 실제 행으로 넣어두고, 저녁 회고에서 실제로 먹었는지 확인한다".
# 그 확정 전 상태를 나타내는 마커가 name 의 이 '끝자리' 접미사다.
#
# 부분일치(LIKE '%예정%') 금지 -- 이름 안에 우연히 그 단어가 들어간 음식
# (예: "예정식당 도시락")까지 쓸어담는다. 반드시 끝자리 고정 비교로만 본다.
# 이건 다리(bridge)지 최종형이 아니다. 정식 컬럼은 별도 lockstep 사안.
PLANNED_SUFFIX = ' (예정)'


def meal_planned_list(date, conn=None):
    """그날의 '아직 확인 안 된 예정' 식단 행 목록.

    반환: (id, meal, display_name, kcal, protein) 리스트. display_name 은 마커
    접미사를 뗀 이름(사람에게 보여줄 이름). 매칭은 substr(name, -len(suffix)) 로
    끝자리만 본다 -- LIKE 와이드카드 부분일치가 아니다."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        suf = PLANNED_SUFFIX
        return conn.execute(
            "SELECT id, COALESCE(meal,''), "
            "       substr(name, 1, length(name)-length(?)), kcal, protein "
            "FROM " + MEALS_V32 + " "
            "WHERE date=? "
            "  AND length(name) > length(?) "
            "  AND substr(name, -length(?)) = ? "
            "ORDER BY id;",
            (suf, date, suf, suf, suf)).fetchall()
    finally:
        if own:
            conn.close()


# ── v3.2 축: meals 읽기 표면 (2026-09-05) ──────────────────────────────────
# 구 스키마의 meals 한 행이 v3.2 에서 넷으로 흩어진다:
#   block 1행 (source_module='diet', settled_by='meal-record')
#   measure 11행 (carb / protein / fat / fiber / sugar / sodium / caffeine ...)
#   block_delta 1행 (nutrition) + block_attr 3행 (meal_slot / notion_id / owning_agent)
#
# ** 이 상수가 그 역조립의 유일한 사본이다. ** 읽기 함수 13개가 각자 피벗 SQL 을
# 들면 같은 공식이 13벌 생긴다 -- B2 에서 EFF_END 를 v_block_span 하나로 모은 것과
# 같은 이유로 여기서도 하나만 둔다.
#
# 뷰가 아니라 코드 상수인 이유: 스키마가 'carb'/'protein' 같은 도메인 어휘를 들면
# 규칙 B 위반이다(기계는 어휘를 모르고 플래그만 읽는다). 그리고 kit_life.py 밖에서
# 이 표를 SQL 로 직접 읽는 소비자는 실측 0건이라, 코드에 두는 비용이 없다.
#
# kcal 공식은 ** 지어내지 않고 원천 정의를 그대로 옮긴다. ** 구 meals.kcal 은
# GENERATED ALWAYS AS (protein*4 + fat*9 + (carb-fiber)*4 + alcohol*7) 이다 --
# 총탄수가 아니라 ** 순탄수(carb-fiber) ** 이고 알코올 7kcal 이 들어간다.
# 내가 처음에 carb*4+protein*4+fat*9 로 짰다가 545행 중 298행이 어긋났다.
# transform-v3.2.py:1004 가 같은 실수를 이미 기록해 두었다("the stored generated
# value IS the fact -- do not re-derive a fact that the source already computes").
_MEAL_KCAL = ("ROUND(COALESCE({protein},0)*4 + COALESCE({fat},0)*9 "
              "+ (COALESCE({carb},0) - COALESCE({fiber},0))*4 "
              "+ COALESCE({alcohol},0)*7, 2)")
_MEAL_M = ("(SELECT m.value FROM measure m WHERE m.block_id = b.id "
           "AND m.metric = '%s' LIMIT 1)")
_MEAL_A = ("(SELECT a.value FROM block_attr a WHERE a.block_id = b.id "
           "AND a.attr_token = '%s' LIMIT 1)")

MEALS_V32 = """(
  SELECT b.id                            AS id,
         b.date                          AS date,
         COALESCE({slot}, '')            AS meal,
         b.title                         AS name,
         {carb}                          AS carb,
         {protein}                       AS protein,
         {fat}                           AS fat,
         {sugar}                         AS sugar,
         {kcal}                          AS kcal,
         {notion}                        AS notion_id,
         {owner}                         AS owning_agent,
         b.created_at                    AS created_at
  FROM block b
  WHERE b.settled_by = 'meal-record'
)""".format(slot=_MEAL_A % 'meal_slot', notion=_MEAL_A % 'notion_id',
            owner=_MEAL_A % 'owning_agent',
            carb=_MEAL_M % 'carb', protein=_MEAL_M % 'protein',
            fat=_MEAL_M % 'fat', sugar=_MEAL_M % 'sugar',
            kcal=_MEAL_KCAL.format(protein=_MEAL_M % 'protein',
                                   fat=_MEAL_M % 'fat',
                                   carb=_MEAL_M % 'carb',
                                   fiber=_MEAL_M % 'fiber',
                                   alcohol=_MEAL_M % 'alcohol'))


def _meal_row_full(conn, mid):
    """(id, date, meal, name, kcal, protein, notion_id) 또는 None."""
    return conn.execute(
        "SELECT id, date, COALESCE(meal,''), name, kcal, protein, notion_id "
        "FROM " + MEALS_V32 + " WHERE id=?;", (int(mid),)).fetchone()


def _meal_day_census(conn, date):
    """(행 수, kcal 합) -- 삭제 전/후 대조용."""
    row = conn.execute(
        "SELECT COUNT(*), COALESCE(SUM(kcal),0) FROM " + MEALS_V32 + " WHERE date=?;",
        (date,)).fetchone()
    return int(row[0]), float(row[1])


# ── 음식 캐시 (029 meal_food / meal_alias / meal_portion) ──────────
# GLOBAL shared knowledge (NO owning_agent). Was per-instance food_cache.json;
# 029 moved items/aliases/portions into the shared DB so a food registered on one
# instance is instantly visible to the other (crew SHARE-state, §4a/§4b of the
# 2026-08-20 crew-skill-topology SPEC). provenance via updated_by only.

# food-key normalization: lowercase + strip brackets/symbols + collapse spaces.
# Byte-matches meal-log/lookup.py normalize_key so JSON-era keys resolve
# unchanged after the DB move (same key on lookup and store).
_FOOD_KEY_STRIP = re.compile(r"[^0-9a-z가-힣ㄱ-ㅎㅏ-ㅣ\s]")
_FOOD_KEY_WS = re.compile(r"\s+")


def normalize_food_key(name):
    """Normalize a food name into a cache key. Same rule on lookup and store."""
    s = (name or "").lower().strip()
    s = _FOOD_KEY_STRIP.sub(" ", s)
    s = _FOOD_KEY_WS.sub(" ", s).strip()
    return s


# scaled-macro column map: DB col -> display key (mirrors meal-log CACHE_NUTR_MAP).
_FOOD_NUTR_COLS = ("kcal", "carb", "protein", "fat", "fiber", "sugar", "sodium_mg")


def alias_resolve(name, conn=None):
    """Resolve an alias to its canonical food name. Miss -> the input unchanged.
    Alias match is on the raw name AND on the normalized key (either registered)."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        row = conn.execute(
            "SELECT canonical FROM meal_alias WHERE alias=? OR alias=? LIMIT 1;",
            (name, normalize_food_key(name))).fetchone()
        return row[0] if row else name
    finally:
        if own:
            conn.close()


def _food_row(conn, key):
    """One meal_food row by exact normalized key, or None."""
    return conn.execute(
        "SELECT key, name, grams, kcal, carb, protein, fat, fiber, sugar, "
        "sodium_mg, source, estimated, updated_by, updated_at "
        "FROM meal_food WHERE key=?;", (key,)).fetchone()


def foodcache_lookup(name, grams=None, conn=None):
    """Fetch meal_food by normalized key (alias as fallback) -> scale to grams.

    Returns a dict {found, name, key, source, estimated, updated, grams, base_grams,
    kcal, carb, protein, fat, fiber, sugar, sodium_mg} or {found: False}. macros
    scaled proportionally to `grams` (None -> the row's own base grams, no scaling).

    Resolution order: EXACT meal_food key first, alias only as a FALLBACK on miss.
    Alias-first would silently shadow a real food that shares a name with an alias
    -- e.g. '굽네 오리지널 순살' is both its own 588g/한마리 row AND an alias for the
    per-100g '굽네치킨 오리지널 순살', so alias-first answered the wrong serving
    basis. Exact-key-first also reproduces the pre-029 JSON-cache semantics."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        key = normalize_food_key(name)
        row = _food_row(conn, key)
        if row is None:
            alias_key = normalize_food_key(alias_resolve(name, conn=conn))
            if alias_key != key:
                row = _food_row(conn, alias_key)
                if row is not None:
                    key = alias_key
        if row is None:
            return {"found": False, "name": name, "key": key}
        (r_key, r_name, base_grams, kcal, carb, protein, fat, fiber, sugar,
         sodium_mg, source, estimated, updated_by, updated_at) = row
        vals = {"kcal": kcal, "carb": carb, "protein": protein, "fat": fat,
                "fiber": fiber, "sugar": sugar, "sodium_mg": sodium_mg}
        # scale only when both a target grams and a nonzero base grams exist.
        if grams is not None and base_grams:
            factor = float(grams) / float(base_grams)
            for c in _FOOD_NUTR_COLS:
                if vals[c] is not None:
                    vals[c] = round(float(vals[c]) * factor, 2)
            out_grams = float(grams)
        else:
            out_grams = base_grams
        res = {"found": True, "name": r_name, "key": r_key,
               "source": source, "estimated": int(estimated or 0),
               "updated_by": updated_by, "updated": updated_at,
               "grams": out_grams, "base_grams": base_grams}
        res.update(vals)
        return res
    finally:
        if own:
            conn.close()


# meal_food upsert columns -> value transformers (key/name handled separately).
_FOOD_UPSERT_COLS = {
    'grams': _opt_num, 'kcal': _opt_num,
    'carb': _num, 'protein': _num, 'fat': _num,
    'fiber': _num, 'sugar': _num, 'sodium_mg': _num,
    'source': _txt,
}


def foodcache_upsert(payload, updated_by=None, conn=None):
    """Upsert one meal_food row (PK = normalized key). payload = food fields +
    'key_name' (raw name) + optional 'name' (display). estimated -> 0/1. carbs is
    accepted as an alias for carb (JSON-era field). Returns (key, name)."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        raw = payload.get("key_name") or payload.get("name")
        if not raw:
            raise ValueError("key_name(or name) 필수")
        key = normalize_food_key(raw)
        name = payload.get("name", raw)
        # JSON-era field name compatibility: carbs -> carb.
        if "carb" not in payload and "carbs" in payload:
            payload = dict(payload, carb=payload["carbs"])
        vals = {c: fn(payload.get(c)) for c, fn in _FOOD_UPSERT_COLS.items()}
        # estimated: accept JSON bool (True/False), 0/1, or "true"/"false".
        est = payload.get("estimated")
        if isinstance(est, bool):
            vals["estimated"] = 1 if est else 0
        elif isinstance(est, str):
            vals["estimated"] = 1 if est.strip().lower() in ("1", "true", "yes") else 0
        else:
            vals["estimated"] = 1 if _num(est) else 0
        by = (updated_by or _facade_agent())
        conn.execute(
            "INSERT INTO meal_food (key, name, grams, kcal, carb, protein, fat, "
            "fiber, sugar, sodium_mg, source, estimated, updated_by, updated_at) "
            "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?, datetime('now','localtime')) "
            "ON CONFLICT(key) DO UPDATE SET "
            "name=excluded.name, grams=excluded.grams, kcal=excluded.kcal, "
            "carb=excluded.carb, protein=excluded.protein, fat=excluded.fat, "
            "fiber=excluded.fiber, sugar=excluded.sugar, "
            "sodium_mg=excluded.sodium_mg, source=excluded.source, "
            "estimated=excluded.estimated, updated_by=excluded.updated_by, "
            "updated_at=datetime('now','localtime');",
            (key, name, vals["grams"], vals["kcal"], vals["carb"], vals["protein"],
             vals["fat"], vals["fiber"], vals["sugar"], vals["sodium_mg"],
             vals["source"], vals["estimated"], by))
        conn.commit()
        return key, name
    finally:
        if own:
            conn.close()


def foodcache_near(name, new_confirmed=False, conn=None):
    """2026-09-28 near-match for the shared food cache. None when `name` is
    already a cache key (exact or via alias) or nothing on file is near.
    Otherwise {'near_match': [{ref, name, signal, matched}], 'ask': question}
    -- ref is the meal_food key. new_confirmed=True: the owner said
    'different food' -- every current candidate is remembered (060) and None
    comes back, so the caller goes on to create."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        if foodcache_lookup(name, conn=conn).get("found"):
            return None
        cands = near_candidates(conn, "food", name)
        if not cands:
            return None
        if new_confirmed:
            near_refuse(conn, "food", name, [c["ref"] for c in cands],
                        said="--new-confirmed")
            return None
        return {"near_match": cands, "ask": near_question("food", cands)}
    finally:
        if own:
            conn.close()


def alias_upsert(alias, canonical, updated_by=None, conn=None):
    """Upsert one meal_alias (PK = alias). Returns (alias, canonical)."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        by = (updated_by or _facade_agent())
        conn.execute(
            "INSERT INTO meal_alias (alias, canonical, updated_by, updated_at) "
            "VALUES (?,?,?, datetime('now','localtime')) "
            "ON CONFLICT(alias) DO UPDATE SET canonical=excluded.canonical, "
            "updated_by=excluded.updated_by, "
            "updated_at=datetime('now','localtime');",
            (alias, canonical, by))
        conn.commit()
        return alias, canonical
    finally:
        if own:
            conn.close()


def portion_lookup(name, conn=None):
    """Default serving grams for a food (meal_portion, PK = normalized key).
    Same resolution order as foodcache_lookup: EXACT key first, alias only as a
    fallback, so an alias never shadows a portion registered under its own name.
    Returns {found, key, grams, n} or {found: False}."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        q = "SELECT key, grams, n FROM meal_portion WHERE key=?;"
        key = normalize_food_key(name)
        row = conn.execute(q, (key,)).fetchone()
        if row is None:
            alias_key = normalize_food_key(alias_resolve(name, conn=conn))
            if alias_key != key:
                row = conn.execute(q, (alias_key,)).fetchone()
                if row is not None:
                    key = alias_key
        if row is None:
            return {"found": False, "key": key}
        return {"found": True, "key": row[0], "grams": row[1], "n": row[2]}
    finally:
        if own:
            conn.close()


def portion_upsert(name, grams, n=1, updated_by=None, conn=None):
    """Upsert one meal_portion (PK = normalized key). Returns (key, grams, n)."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        key = normalize_food_key(name)
        by = (updated_by or _facade_agent())
        conn.execute(
            "INSERT INTO meal_portion (key, grams, n, updated_by, updated_at) "
            "VALUES (?,?,?,?, datetime('now','localtime')) "
            "ON CONFLICT(key) DO UPDATE SET grams=excluded.grams, n=excluded.n, "
            "updated_by=excluded.updated_by, "
            "updated_at=datetime('now','localtime');",
            (key, _num(grams), _num(n, default=1.0), by))
        conn.commit()
        return key, _num(grams), _num(n, default=1.0)
    finally:
        if own:
            conn.close()


# ── lookup receipt (043) -- the ordered-step precondition for meal_add ─────
#
# DGN-928.  The diet skill's SKILL.md states the order in prose: resolve the
# food against the shared cache FIRST, estimate only on a miss.  Prose carries
# no execution order, so the model ran by associative fit and wrote an LLM
# estimate over an already-measured cache value.  The order is enforced HERE
# instead: lookup.py writes a receipt, meal_add reads it, and a name with no
# receipt cannot be recorded without the explicit escape.
#
# The receipt stores the caller's string VERBATIM.  The tempting cheaper gate
# -- "the food is in meal_food, so the lookup must have run" -- was measured
# and refuted: meal_food's key is normalize_food_key(...) of the ORIGINAL
# input, and the stored display name is a different string, so 101 of the 200
# live rows do not round-trip (2026-09-09).  That gate would refuse half the
# correctly cached foods, and a gate with false refusals teaches the caller to
# pass the escape flag reflexively -- it survives in name only.  Verbatim in,
# verbatim out, matched by construction.
#
# RECEIPT_TTL_HOURS = 24.  A receipt is evidence that the lookup ran for THIS
# logging act, not a permanent licence for the name.  A meal is logged the day
# it is looked up, so one day covers every honest sequence including a late
# supper crossing local midnight (the window is 24 rolling hours, not a
# calendar day).  The two alternatives were both worse: no TTL turns the gate
# into a one-time initiation -- look a food up once in September and every
# November estimate for it is authorised forever, which is the exact failure
# this exists to stop, since the cache row may have been corrected in between;
# session scope is not expressible here, because the skill reaches this SDK
# through short-lived one-shot processes that share nothing but the database,
# so "the session" has no representation to key on.
RECEIPT_TTL_HOURS = 24

# The three doors in meal-log/lookup.py that resolve a food name.
RECEIPT_MODES = ('name', 'barcode', 'cache-add')


class LookupSkippedError(Exception):
    """meal_add refused: the ordered lookup step never ran for this name.

    Raised BEFORE any write -- no block, no measure, no delta.  Carries the
    offending name so the caller can put it straight into the retry."""

    def __init__(self, name):
        self.name = name
        super().__init__(
            f"'{name}' 은(는) 조회 단계를 거치지 않았습니다. 먼저 "
            f"meal-log/lookup.py name '{name}' <grams> 로 조회한 뒤 같은 이름으로 "
            f"다시 기록하세요. 조회가 miss 여도 영수증은 남으므로 그대로 진행됩니다. "
            f"조회 없이 기록해야 한다면 --no-lookup (SDK: allow_unlooked=True) 입니다.")


def _receipt_cutoff():
    """The oldest ts that still counts, as a canonical UTC-Z string.

    Both sides are the same format, so the freshness test is a lexicographic
    string compare -- no parsing, no timezone, no second clock (036/038)."""
    return (datetime.datetime.now(datetime.timezone.utc)
            - timedelta(hours=RECEIPT_TTL_HOURS)).strftime("%Y-%m-%dT%H:%M:%SZ")


# 048: which branch the lookup took.  'exact' = the numbers are pinned by a
# real match (shared cache / barcode product / nutrition label / public-DB
# item).  'estimate' = the step ran and found nothing, so whatever macros
# follow are a guess.  Anything else -- including None -- means the question
# was never put to this receipt, and that reads as permission (fail-open).
RESOLVED_GRADES = ('exact', 'estimate')


def lookup_receipt_write(name, mode, conn=None):
    """Record that the ordered lookup step ran for `name`. Returns (name, ts).

    `name` is stored EXACTLY as given -- never normalized, never trimmed.  The
    PK is that verbatim string, so a re-lookup refreshes ts in place instead of
    appending a row.  Written on a MISS too: a miss still means the ordered
    step ran, and refusing after an honest miss is the false refusal this whole
    design exists to remove.

    048: this does NOT stamp `resolved`.  The caller cannot know the branch
    yet -- lookup.py writes the receipt BEFORE consulting the cache precisely
    so that every exit path leaves one.  A re-lookup clears the old grade back
    to NULL on purpose: the previous answer belonged to the previous lookup,
    and carrying it forward would let a stale 'exact' wave through a name that
    just missed.  lookup_receipt_resolve stamps the grade once it is known.

    Infrastructure faults are NOT the caller's problem -- a missing table or an
    unreadable database returns None with a stderr note rather than raising,
    because a broken receipt lane must never be able to stop a meal from being
    logged (the reader fails open on the same fault)."""
    own = conn is None
    if own:
        try:
            conn = get_conn()
        except SystemExit:
            print("kit_life: lookup receipt unavailable (no database); "
                  "meal-add will fall back to allowing the write",
                  file=sys.stderr)
            return None
    try:
        ts = _utc_now_str()
        conn.execute(
            "INSERT INTO meal_lookup_receipt "
            "(name_given, norm_key, mode, ts, resolved) "
            "VALUES (?,?,?,?,NULL) "
            "ON CONFLICT(name_given) DO UPDATE SET "
            "norm_key=excluded.norm_key, mode=excluded.mode, ts=excluded.ts, "
            "resolved=NULL;",
            (name, normalize_food_key(name), mode, ts))
        conn.commit()
        return name, ts
    except sqlite3.Error as e:
        # Deliberately does NOT promise a refusal: if the lane itself is what
        # broke, the reader fails open and the meal records anyway.  Say only
        # what is true in both branches.
        print(f"kit_life: lookup receipt not written ({e}) -- meal-add may "
              f"refuse '{name}'; --no-lookup always records", file=sys.stderr)
        return None
    finally:
        if own:
            conn.close()


def lookup_receipt_check(conn, name):
    """Is there a live receipt for this exact name? True / False / None.

    None means the question could not be asked at all (no receipt table, DB
    error) -- the caller MUST treat that as permission, never as a refusal.

    Matching is verbatim-to-verbatim.  The fallback comparison folds case and
    edge whitespace ONLY: '닭가슴살 ' and '닭가슴살' are the same string a human
    typed twice, and refusing there would be a false refusal.  It deliberately
    does NOT strip brackets or symbols -- that is normalize_food_key, and
    matching on it is exactly the attempt-1 defect readmitted through the back
    door; 'looked up A, recorded B' must stay a refusal."""
    try:
        cutoff = _receipt_cutoff()
        row = conn.execute(
            "SELECT 1 FROM meal_lookup_receipt "
            "WHERE (name_given = ? OR lower(trim(name_given)) = lower(trim(?))) "
            "AND ts >= ? LIMIT 1;", (name, name, cutoff)).fetchone()
        return row is not None
    except sqlite3.Error as e:
        print(f"kit_life: lookup receipt lane unavailable ({e}) -- recording "
              f"'{name}' WITHOUT the lookup precondition (fail-open)",
              file=sys.stderr)
        return None


def lookup_receipt_resolve(name, grade, conn=None):
    """Stamp WHICH branch the lookup took for `name` (048). Returns bool.

    Called after the fact, by the same door that wrote the receipt, once the
    branch is actually known.  Updates in place -- never inserts: a grade
    without a receipt would be a claim that the ordered step ran, which is the
    one thing this lane must not be able to fake.  A name with no live receipt
    is therefore a silent no-op, not an error.

    An off-roster grade is refused rather than stored.  The vocabulary lives
    here and not in a CHECK constraint (035's division of labour) because a
    later cut may widen it, and widening a two-token list should not cost a
    table rebuild.

    Infrastructure faults return False with a stderr note, matching the writer:
    a broken grade lane leaves `resolved` NULL, and NULL fails OPEN at the
    gate.  A meal is never blocked by this function failing."""
    if grade not in RESOLVED_GRADES:
        raise ValueError(
            "resolved grade must be one of %s -- got %r"
            % ("|".join(RESOLVED_GRADES), grade))
    own = conn is None
    if own:
        try:
            conn = get_conn()
        except SystemExit:
            return False
    try:
        cutoff = _receipt_cutoff()
        cur = conn.execute(
            "UPDATE meal_lookup_receipt SET resolved=? "
            "WHERE (name_given = ? OR lower(trim(name_given)) = lower(trim(?))) "
            "AND ts >= ?;", (grade, name, name, cutoff))
        conn.commit()
        return cur.rowcount > 0
    except sqlite3.Error as e:
        print(f"kit_life: lookup grade not recorded ({e}) -- '{name}' stays "
              f"ungraded and the satiety gate will fail open", file=sys.stderr)
        return False
    finally:
        if own:
            conn.close()


def lookup_receipt_grade(conn, name):
    """The recorded branch for this name: 'exact' | 'estimate' | None.

    None covers all three ways the answer can be absent -- no live receipt, a
    pre-048 row, or a lane fault -- because the gate treats them identically:
    unknown is permission."""
    try:
        cutoff = _receipt_cutoff()
        row = conn.execute(
            "SELECT resolved FROM meal_lookup_receipt "
            "WHERE (name_given = ? OR lower(trim(name_given)) = lower(trim(?))) "
            "AND ts >= ? LIMIT 1;", (name, name, cutoff)).fetchone()
        return row[0] if row and row[0] in RESOLVED_GRADES else None
    except sqlite3.Error:
        # Silent on purpose: lookup_receipt_check already narrates this exact
        # fault on the same call path, and saying it twice reads as two faults.
        return None


# fb-1787479201-4 (2026-08-24 domain harvest, item 2): a meal was
# recorded with estimated numbers and no reason, and the owner had to ask
# afterwards ("공식 영양성분 없었니 왜 추정했어"). The reason is not a
# judgement -- the lookup lane already recorded it (receipt mode + 048 grade,
# the cache row's own `estimated` flag). meal-add says it AT the write, one
# machine line the reply carries verbatim; nothing for the model to remember.
# The wording is owner-facing (dec-094 gate): change it here only.
ESTIMATE_REASONS = {
    'lookup_miss':     '공식 영양성분 미제공으로 추정값 사용',
    'estimated_entry': '공식 영양성분 미제공으로 추정값 사용',
    'barcode_miss':    '바코드 제품 정보가 없어 추정값 사용',
    'cached_estimate': '예전에 추정해 둔 값 사용',
}


def meal_estimate_reason(conn, name):
    """(code, text) when the numbers recorded under `name` are an estimate,
    else None. From recorded facts only:
      receipt graded 'estimate'  -> lookup_miss (name lookup found nothing),
                                    barcode_miss, or estimated_entry (the
                                    cache-add that supplied them was an estimate)
      graded 'exact' by a cache hit on a row itself stored estimated
                                 -> cached_estimate
    No live receipt (--no-lookup, pre-043 name) or a lane fault -> None: an
    unknown reason is not spoken, never guessed."""
    try:
        row = conn.execute(
            "SELECT resolved, mode FROM meal_lookup_receipt "
            "WHERE (name_given = ? OR lower(trim(name_given)) = lower(trim(?))) "
            "AND ts >= ? LIMIT 1;", (name, name, _receipt_cutoff())).fetchone()
    except sqlite3.Error:
        return None
    if row is None:
        return None
    grade, mode = row
    code = None
    if grade == 'estimate':
        code = {'barcode': 'barcode_miss',
                'cache-add': 'estimated_entry'}.get(mode, 'lookup_miss')
    elif grade == 'exact':
        try:
            fc = foodcache_lookup(name, conn=conn)
        except Exception:        # noqa: BLE001 -- a reason is never worth a failed write
            fc = {}
        if fc.get('found') and fc.get('estimated'):
            code = 'cached_estimate'
    return (code, ESTIMATE_REASONS[code]) if code else None


# ── 포만감(satiety) 게이트 ─────────────────────────────────
# The reading itself lives per-instance, NOT in this crew-shared database
# (029 §4c): when the owner ate and how full he felt are behaviour, not the
# domain-agnostic nutrition facts that migration moved into the shared DB.
# This module only READS it, through the same relative-path idiom agent_conf
# uses for config/agent.conf -- one file, one owner (mealstate.py writes).
_SATIETY_STATE = os.path.join(SCRIPT_DIR, "food_cache.json")


def satiety_read(date, meal, path=None):
    """The stored fullness token for one meal slot, or None.

    Key shape is mealstate.py's, verbatim: "2026-09-12_점심".  A missing or
    unreadable file reads as None, never as an error -- the store is additive
    behaviour data and a first run must not be a fault."""
    p = path or _SATIETY_STATE
    try:
        with open(p, "r", encoding="utf-8") as fh:
            data = json.load(fh)
    except (IOError, OSError, ValueError):
        return None
    if not isinstance(data, dict):
        return None
    entry = (data.get("meal_times") or {}).get("%s_%s" % (date, meal))
    if not isinstance(entry, dict):
        return None
    tok = entry.get("fullness")
    return tok if isinstance(tok, str) and tok else None


class SatietySkippedError(Exception):
    """meal_add refused: an ESTIMATED meal with no satiety answer on record.

    Raised BEFORE any write -- no block, no measure, no delta.  Carries the
    slot so the caller can put it straight into the retry."""

    def __init__(self, date, meal, name):
        self.date, self.meal, self.name = date, meal, name
        super().__init__(
            f"'{name}' 은(는) 추정으로 잡은 값인데 {date} {meal} 의 포만감 답이 "
            f"없습니다. 먼저 사용자에게 그 끼니가 어땠는지 묻고 "
            f"meal-log/mealstate.py fullness-set {date} {meal} <token> 으로 "
            f"남긴 뒤 다시 기록하세요. 토큰은 snack|too_little|slightly_light|"
            f"just_right|slightly_heavy|too_full|stuffed 입니다(한글 라벨이 아니라 "
            f"토큰). 포만감 없이 기록해야 한다면 --no-satiety "
            f"(SDK: allow_unsated=True) 입니다.")


# ── 운동 CRUD ──────────────────────────────────────────────
def workout_type_id(conn, category, subtype):
    """(대분류, 세부) → workout_types.id. 사전에 없으면 None.

    빈 category/subtype이면 매핑 시도 안 하고 None(예: 세부만 모르는 경우)."""
    cat = (category or '').strip()
    sub = (subtype or '').strip()
    if not cat or not sub:
        return None
    row = conn.execute(
        "SELECT id FROM workout_types WHERE category=? AND subtype=? LIMIT 1;",
        (cat, sub)).fetchone()
    return row[0] if row else None


def workout_type_get_or_create(conn, category, subtype):
    """(대분류, 세부) → workout_types.id. 사전에 없으면 자동 등록 후 그 id 반환.

    type/name 캐시 컬럼 제거 후 라벨이 빈칸 되는 걸 막는 핵심 보완책:
    미등록 분류가 들어오면 workout_types에 (category, subtype, active=1) 신규 등록.
    빈 category/subtype이면 등록하지 않고 None(라벨 없는 운동은 type_id=NULL 허용)."""
    cat = (category or '').strip()
    sub = (subtype or '').strip()
    if not cat or not sub:
        return None
    tid = workout_type_id(conn, cat, sub)
    if tid is not None:
        return tid
    # 미등록 분류 → 사전에 자동 추가(sort는 0 기본, active=1).
    conn.execute(
        "INSERT INTO workout_types (category, subtype, active) VALUES (?,?,1);",
        (cat, sub))
    return workout_type_id(conn, cat, sub)


# fb-1790289002-1 (2026-09-25): "one body part per workout". The junction was
# N:M all along; the write was not -- one workout-add = one part, the rest
# needed a follow-up workout-classify per part that the model had to remember,
# and a joined string ("하체+가슴+어깨", "어깨, 쿼드") was minted as ONE new
# subtype (056 then reports it unmapped). Split at the write, top level only:
# a separator inside parentheses ("어깨 펌핑 (D-1·예정)") is part of the name.
_PART_SEPS = '+,，、·'


def split_parts(subtype):
    """'하체+가슴, 어깨' -> ['하체', '가슴', '어깨'] (order kept, deduped).
    A subtype with no top-level separator comes back as [subtype]."""
    s = (subtype or '').strip()
    out, cur, depth = [], [], 0
    for ch in s:
        if ch in '([':
            depth += 1
        elif ch in ')]':
            depth = max(0, depth - 1)
        if depth == 0 and ch in _PART_SEPS:
            out.append(''.join(cur).strip())
            cur = []
        else:
            cur.append(ch)
    out.append(''.join(cur).strip())
    seen = []
    for p in out:
        if p and p not in seen:
            seen.append(p)
    return seen


def workout_add_classification(conn, workout_id, category, subtype):
    """운동 한 건에 분류 1개를 연결(N:M junction에 1행).

    (category, subtype)를 workout_type_get_or_create로 type_id 확보 후
    workout_classifications에 (workout_id, type_id)를 INSERT OR IGNORE.
    빈 category/subtype이면 아무것도 안 넣고 None 반환(라벨 없는 분류 허용).
    반환: 연결된 type_id(없으면 None)."""
    tid = workout_type_get_or_create(conn, category, subtype)
    if tid is None:
        return None
    conn.execute(
        "INSERT OR IGNORE INTO workout_classifications (workout_id, type_id) "
        "VALUES (?,?);", (workout_id, tid))
    return tid


# DGN-724: 활동/총 소모칼로리 혼동 가드. 규칙(kcal=활동값, 총값은 note에만)은
# 이미 SKILL.md에 문서화돼 있었는데도 실제 기록 시점(2026-08-06 session 53)에
# 총값(802)이 kcal에 들어가는 사고가 재발했다 -- "규칙을 다시 적어두는 것"으로는
# 안 막힌다는 게 이미 증명된 사례라, 규칙을 실제 쓰기 경로(workout_add/
# workout_upd)에 강제 지점으로 박아 넣는다(RULES.md forcing-point 원칙).
# note에 "활동N"과 "총M" 두 값이 함께 있는데 kcal이 총값(M) 쪽과 같으면 즉시
# 거부 -- BMR과 이중계산되는 걸 DB에 넣기 전에 막는다.
_ACTIVE_TOTAL_RE = re.compile(r'활동\s*[:\s]?\s*(\d+(?:\.\d+)?)')
_TOTAL_KCAL_RE = re.compile(r'총\s*[:\s]?\s*(\d+(?:\.\d+)?)')


def _check_active_vs_total_kcal(kcal, note):
    """note에 '활동N/총M kcal' 두 값이 같이 있는데 kcal이 총값과 같으면 예외.
    둘 중 하나만 있거나 없으면 통과(정상 케이스 방해 안 함)."""
    if not note or kcal is None or str(kcal).strip() == '':
        return
    am = _ACTIVE_TOTAL_RE.search(note)
    tm = _TOTAL_KCAL_RE.search(note)
    if not am or not tm:
        return
    active_v, total_v, k = float(am.group(1)), float(tm.group(1)), _num(kcal)
    if active_v == total_v:
        return
    # kcal이 총값과 (반올림 오차 이내로) 같으면 -> 활동값 대신 총값이 들어간 것.
    if abs(k - total_v) < 0.5 and abs(k - active_v) >= 0.5:
        raise ValueError(
            f"kcal={k}가 note의 '총{total_v:g}'값과 같음 -- kcal 컬럼은 활동"
            f"(active) 칼로리여야 함(BMR과 이중계산 방지, workout-log SKILL.md 규칙). "
            f"kcal={active_v:g}(활동값)로 다시 넣으세요.")


# ── cut 4 slab 2: the workouts lane writes the value home (measure) ─────────
# 037 S1: the ONE home for a value the judgement layer reads is `measure`.
# weekly_sessions was declared (commitment, 2.12.0) and registered
# (metric_def accrual='accrued'), but the workouts lane had never written
# there, so v_criterion_verdict produced NOTHING for it.  The shape follows
# the accrual semantics 044 already judges by: each session IS an increment,
# so ONE measure row per workouts row with value 1.0 -- the weekly total is
# the period SUM, no stored aggregate, no second clock.  workouts stays the
# lane's store of record (every workout_* reader keeps reading it); the
# measure row is a SHADOW maintained in the SAME tx by every write verb,
# exactly the 039 spend_entry idiom.  The anchor is the 036/039 incumbent:
# a deterministic 'x-workout-<id>' date-only record block ('x-%' rows are
# already filtered out of the timeblock compat view).  NOT the '몸' entity:
# a session is a recorded act, not a body level -- scope_kind='block' per
# the 2.12.0 cargo.  source_module='training' continues the stored pattern
# (diet/ledger/life all name their domain token; 'health' is not a domain
# token and would map to no door).

def _workout_write_v32(conn, wid, date, note):
    """workouts 한 건의 v3.2 그림자(record 블록 + weekly_sessions measure
    1행)를 (재)작성한다.  반환: block.id.  갱신 시 블록은 제자리
    (created_at/settled_at 보존), measure 만 지우고 다시 쓴다
    (_spend_write_v32 와 같은 관용구).  observed_at 은 그 세션 날의 현지
    자정을 선언된 오프셋으로 정규 UTC-Z 환산 (_meal_observed_instant --
    미선언이면 date-only 급으로 fail-CLOSED, +9 하드코드 금지, 0 가정 금지,
    오너 2026-09-08 06:48)."""
    ulid = 'x-workout-%d' % int(wid)
    row = conn.execute("SELECT id FROM block WHERE ulid=?;", (ulid,)).fetchone()
    if row:
        bid = row[0]
        conn.execute("UPDATE block SET title=?, date=? WHERE id=?;",
                     (_txt(note), date, bid))
        conn.execute("DELETE FROM measure WHERE block_id=?;", (bid,))
    else:
        now = now_utc()
        cur = conn.execute(
            "INSERT INTO block(ulid, source_module, title, date, kind_token, "
            "settled_at, settled_outcome, settled_by, settled_verdict, "
            "created_at) VALUES (?,?,?,?,?,?,?,?,?,?);",
            (ulid, 'training', _txt(note), date, 'record',
             now, 'done', 'workout-record', 'machine', now))
        bid = cur.lastrowid
    # measure.metric is an FK: register weekly_sessions from module cargo at
    # the point of need (freshness-set's defensive-registration discipline)
    # so a fresh estate's FIRST workout-add does not die on the constraint.
    _criterion_metric_ensure(conn, 'weekly_sessions')
    conn.execute(
        "INSERT INTO measure(metric, value, unit, basis, block_id, "
        "observed_at, source, value_origin) "
        "VALUES('weekly_sessions', 1.0, 'count', 'actual', ?, ?, "
        "'module:training', 'declared');",
        (bid, _meal_observed_instant(date)))
    return bid


def _workout_shadow_del(conn, wid):
    """workouts 한 건의 그림자 블록 삭제 (measure/attr 은 CASCADE) + 그
    블록을 가리키는 record 행 정리 (_spend_shadow_del 과 같은 관용구).
    같은 tx 에서 불려야 한다 -- 살아남은 그림자 measure 는 그 주의 세션
    수를 부풀리는 고아다."""
    row = conn.execute(
        "SELECT id FROM block WHERE ulid=? AND settled_by='workout-record';",
        ('x-workout-%d' % int(wid),)).fetchone()
    if row is None:
        return
    conn.execute("DELETE FROM block WHERE id=?;", (row[0],))
    _block_record_del(conn, row[0])


KCAL_ORIGINS = ('measured', 'computed', 'default', 'declared', 'unknown')


def _kcal_origin_arg(kcal_v, origin):
    """064: the origin to store beside a kcal value.  No number -> no origin
    (the CHECK refuses one); a number with no stated origin -> NULL here and
    the trigger stamps 'unknown' (never guessed as 'measured')."""
    if kcal_v is None:
        return None
    if origin is None or str(origin).strip() == '':
        return None
    origin = str(origin).strip()
    if origin not in KCAL_ORIGINS:
        raise ValueError("kcal_origin 은 %s 중 하나: %r"
                         % ('|'.join(KCAL_ORIGINS), origin))
    return origin


def _workouts_has_kcal_origin(conn):
    return any(r[1] == 'kcal_origin' for r in
               conn.execute('PRAGMA table_info(workouts);').fetchall())


def workout_add(date, wtype, name='', minutes=0, kcal=None, note='',
                avg_hr=None, conn=None, types=None, kcal_origin=None):
    """운동 한 건 기록(area=신체건강 자동). 새 행 id 반환.

    운동 분류는 N:M junction(workout_classifications)으로 모델링한다 —
    한 운동이 분류(workout_types) 여러 개를 가질 수 있다(예: "근력+유산소").
      - workouts 행은 분류 없이 INSERT(date, minutes, kcal, note, area_id, avg_hr).
      - 단일 쌍(하위호환): wtype=대분류(category), name=세부(subtype)를
        workout_type_get_or_create로 확보해 junction에 1행 추가.
      - 복수 분류: types=[(category, subtype), ...]로 추가 분류를 넘기면
        junction에 여러 행으로 들어간다(중복은 INSERT OR IGNORE로 무시).
      - (category, subtype)가 사전에 없으면 에러로 막지 않고 stderr 경고 후
        workout_types에 자동 등록(active=1)한다.
        → 라벨은 항상 junction→workout_types 조인으로 복원된다.
      - category/subtype이 모두 비면 junction에 아무 행도 안 만든다(라벨 없는 운동 허용).
    avg_hr=평균 심박수(bpm). 미지정/빈값이면 NULL로 들어감(_opt_num).
    kcal=미지정/빈값이면 NULL(064: 미기록 -- 0 이 아니다). kcal_origin=
    KCAL_ORIGINS 중 하나, 안 주면 트리거가 'unknown'."""
    _check_active_vs_total_kcal(kcal, note)     # DGN-724 forcing point
    own = conn is None
    if own:
        conn = get_conn()
    try:
        aid = area_id(conn, AREA_WORKOUT)
        kcal_v = _opt_num(kcal)
        if _workouts_has_kcal_origin(conn):
            cur = conn.execute(
                "INSERT INTO workouts (date, minutes, kcal, kcal_origin, note, "
                "area_id, avg_hr, owning_agent) "
                "VALUES (?,?,?,?,?,?,?,?);",
                (date, _num(minutes), kcal_v, _kcal_origin_arg(kcal_v,
                                                              kcal_origin),
                 _txt(note), aid, _opt_num(avg_hr),
                 _health_agent_write(conn)))  # v19 one-writer: health domain
        else:
            # pre-064 DB: kcal is NOT NULL DEFAULT 0 and has no origin column
            cur = conn.execute(
                "INSERT INTO workouts (date, minutes, kcal, note, area_id, "
                "avg_hr, owning_agent) "
                "VALUES (?,?,?,?,?,?,?);",
                (date, _num(minutes), _num(kcal),
                 _txt(note), aid, _opt_num(avg_hr),
                 _health_agent_write(conn)))
        wid = cur.lastrowid

        # 연결할 분류 쌍 모으기: 기본 단일 쌍(wtype/name) + 추가 types.
        pairs = [(wtype, name)]
        if types:
            pairs.extend(types)
        # one classification per part: a joined subtype is N parts, never a
        # new composite dictionary word (fb-1790289002-1).
        pairs = [(cat, part) for cat, sub in pairs
                 for part in (split_parts(sub) or [sub])]
        for cat, sub in pairs:
            existing = workout_type_id(conn, cat, sub)
            tid = workout_add_classification(conn, wid, cat, sub)
            if tid is not None and existing is None:
                print(f"[workout_add] 미등록 분류 자동 등록: '{cat}/{sub}' "
                      f"→ workout_types.id={tid}", file=sys.stderr)
        # cut 4 slab 2: same-tx value shadow (record block + measure 1.0).
        _workout_write_v32(conn, wid, date, _txt(note))
        conn.commit()
        return wid
    finally:
        if own:
            conn.close()


# DGN: partial-update column allowlist + coercers for workout-upd.
_WORKOUT_UPD_COLS = {
    'date': _txt, 'minutes': _num, 'kcal': _opt_num,
    'note': _txt, 'avg_hr': _opt_num, 'kcal_origin': _txt,
}


def workout_upd(wid, fields, conn=None):
    """운동 한 건의 지정 필드만 갱신(부분 업데이트). fields=={컬럼:원본값}.
    갱신 후 (id, minutes, kcal) 반환(없으면 None)."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        if 'kcal' in fields:
            # DGN-724 가드: note를 같이 안 바꾸면 기존 note로 검사.
            note_for_check = fields.get('note')
            if note_for_check is None:
                row = conn.execute(
                    "SELECT note FROM workouts WHERE id=?;",
                    (int(wid),)).fetchone()
                note_for_check = row[0] if row else ''
            _check_active_vs_total_kcal(fields['kcal'], note_for_check)
        sets, vals = [], []
        has_origin = _workouts_has_kcal_origin(conn)
        if 'kcal_origin' in fields and not has_origin:
            raise ValueError("수정 불가 컬럼: kcal_origin (064 이전 DB)")
        for col, raw in fields.items():
            if col not in _WORKOUT_UPD_COLS:
                raise ValueError(f"수정 불가 컬럼: {col}")
            if col == 'kcal_origin':
                continue                    # folded in with kcal below
            val = _WORKOUT_UPD_COLS[col](raw)
            if col == 'kcal' and not has_origin and val is None:
                val = 0.0                   # pre-064: NOT NULL DEFAULT 0
            sets.append(f"{col}=?")
            vals.append(val)
        if has_origin and ('kcal' in fields or 'kcal_origin' in fields):
            # 064: a new number carries the origin stated WITH it, or none
            # (the trigger then says 'unknown') -- never the previous number's
            # origin; no number -> no origin.
            if 'kcal' in fields:
                kv = _opt_num(fields['kcal'])
            else:
                row = conn.execute("SELECT kcal FROM workouts WHERE id=?;",
                                   (int(wid),)).fetchone()
                kv = row[0] if row else None
            if kv is None and _txt(fields.get('kcal_origin')):
                raise ValueError("kcal 이 미기록인 운동에 kcal_origin 만 줄 수 "
                                 "없음 -- kcal 과 함께 주세요")
            sets.append("kcal_origin=?")
            vals.append(_kcal_origin_arg(kv, fields.get('kcal_origin')))
        if not sets:
            raise ValueError("갱신할 필드가 없음")
        vals.append(int(wid))
        cur = conn.execute(
            f"UPDATE workouts SET {', '.join(sets)} WHERE id=?;", vals)
        if cur.rowcount:
            # cut 4 slab 2: rewrite the value shadow in the SAME tx -- a date
            # fix moves the session's measure row into the right week, and
            # rewriting from the row (not the args) keeps one source of truth.
            row = conn.execute("SELECT date, note FROM workouts WHERE id=?;",
                               (int(wid),)).fetchone()
            _workout_write_v32(conn, int(wid), row[0], row[1])
        conn.commit()
        if cur.rowcount == 0:
            return None
        return conn.execute(
            "SELECT id, minutes, kcal FROM workouts WHERE id=?;",
            (int(wid),)).fetchone()
    finally:
        if own:
            conn.close()


def workout_find(date, conn=None):
    """그날 운동 목록 (id, type, name, minutes, kcal) 튜플 리스트.

    ★기존 5컬럼 반환 계약 유지★ (card.py/retro/weekly가 의존). 운동 한 건당 정확히 1행.
    분류는 N:M(workout_classifications)이라 한 운동이 분류 여러 개를 가질 수 있으므로:
      - junction을 LEFT JOIN하고 workout_id로 GROUP BY해 운동당 1행으로 접는다.
      - type 자리 = group_concat(DISTINCT wt.category) (여러 개면 콤마로 합쳐짐, 예 "근력,유산소").
      - name 자리 = group_concat(wt.subtype, ', ') (정렬은 type_id 순으로 안정화).
      - 분류 없으면 type/name은 빈문자열(COALESCE로 NULL→'').
    탭 구분 파싱(retro-2100.sh)이 안 깨지게 group_concat 구분자는 콤마/쉼표만 쓴다."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        return conn.execute(
            "SELECT w.id, "
            "COALESCE(group_concat(DISTINCT wt.category), ''), "
            "COALESCE(group_concat(wt.subtype, ', '), ''), "
            "w.minutes, w.kcal "
            "FROM workouts w "
            "LEFT JOIN workout_classifications wc ON wc.workout_id = w.id "
            "LEFT JOIN workout_types wt ON wt.id = wc.type_id "
            "WHERE w.date=? "
            "GROUP BY w.id ORDER BY w.id;", (date,)).fetchall()
    finally:
        if own:
            conn.close()


def workout_find_full(date, conn=None):
    """그날 운동 목록 (정규화 분류 포함). 운동 한 건당 1행.

    분류는 N:M(workout_classifications)이므로 운동당 1행으로 접고 분류는 group_concat한다.
    반환: (id, type, name, minutes, kcal, type_ids, categories, subtypes) 튜플 리스트.
      - type      = group_concat(DISTINCT wt.category)  (워크아웃당 모든 대분류, 콤마 합침)
      - name      = group_concat(wt.subtype, ', ')       (모든 세부, 쉼표 합침)
      - type_ids  = group_concat(wc.type_id)             (연결된 type_id들, 콤마 합침)
      - categories/subtypes = group_concat 원본(미연결이면 NULL→'')
    분류 없으면 모든 분류 칼럼은 빈문자열. (실호출자 없음 → workout_find와 동일 1:1 형태로 통일.)"""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        return conn.execute(
            "SELECT w.id, "
            "COALESCE(group_concat(DISTINCT wt.category), ''), "
            "COALESCE(group_concat(wt.subtype, ', '), ''), "
            "w.minutes, w.kcal, "
            "COALESCE(group_concat(wc.type_id), ''), "
            "COALESCE(group_concat(DISTINCT wt.category), ''), "
            "COALESCE(group_concat(wt.subtype, ', '), '') "
            "FROM workouts w "
            "LEFT JOIN workout_classifications wc ON wc.workout_id = w.id "
            "LEFT JOIN workout_types wt ON wt.id = wc.type_id "
            "WHERE w.date=? "
            "GROUP BY w.id ORDER BY w.id;", (date,)).fetchall()
    finally:
        if own:
            conn.close()


def workout_dependents(wid, conn=None):
    """Census of everything a `DELETE FROM workouts WHERE id=?` would destroy.

    workout_sets.session_id and workout_classifications.workout_id are BOTH
    `ON DELETE CASCADE` and this process opens the DB with `PRAGMA
    foreign_keys = ON`, so deleting the parent row silently takes the children
    with it. Nothing in the CLI ever counted or named them: `workout-del 10092`
    printed `deleted workout 10092` after destroying 32 logged sets. This
    function is the census the guard refuses on -- read-only, no writes.

    Returns a dict:
      exists        bool         -- is there a workouts row at all
      date/note     str|None     -- how the owner would RECOGNISE this session
      session_type  str|None     -- session_type.code if tagged (a tagged row is
                                    a CLOSED session, not a mistaken one)
      sets          int          -- workout_sets rows that would cascade
      exercises     [(name, n, seqs)] -- named, so the refusal can say WHAT dies
      classes       int          -- workout_classifications rows that cascade
      records       int          -- record rows pointing at this source (these do
                                    NOT cascade -- FK-less polymorphic pointer --
                                    so they would DANGLE; see GUARD #3b)
    """
    own = conn is None
    if own:
        conn = get_conn()
    try:
        wid = int(wid)
        row = conn.execute(
            "SELECT w.date, w.note, st.code FROM workouts w "
            "LEFT JOIN session_type st ON st.id = w.session_type_id "
            "WHERE w.id=?;", (wid,)).fetchone()
        out = {'id': wid, 'exists': row is not None, 'date': None,
               'note': None, 'session_type': None, 'sets': 0,
               'exercises': [], 'classes': 0, 'records': 0}
        if row is None:
            return out
        out['date'], out['note'], out['session_type'] = row[0], row[1], row[2]
        try:
            out['sets'] = int(conn.execute(
                "SELECT COUNT(*) FROM workout_sets WHERE session_id=?;",
                (wid,)).fetchone()[0])
            out['exercises'] = [
                (r[0], int(r[1]), r[2]) for r in conn.execute(
                    "SELECT exercise_name, COUNT(*), "
                    "group_concat(set_seq) FROM workout_sets "
                    "WHERE session_id=? GROUP BY exercise_name "
                    "ORDER BY MIN(slot_num), exercise_name;", (wid,)).fetchall()]
        except sqlite3.OperationalError:
            pass  # workout_sets absent (pre-018 DB) -> nothing to cascade
        try:
            out['classes'] = int(conn.execute(
                "SELECT COUNT(*) FROM workout_classifications WHERE workout_id=?;",
                (wid,)).fetchone()[0])
        except sqlite3.OperationalError:
            pass
        try:
            out['records'] = int(conn.execute(
                "SELECT COUNT(*) FROM record WHERE source_table='workouts' "
                "AND source_id=?;", (wid,)).fetchone()[0])
        except sqlite3.OperationalError:
            pass
        return out
    finally:
        if own:
            conn.close()


# Runtime markers the workout pipeline drops per session. kit_life.py is SHARED
# kit code (Ag runs it too) and does not own these -- files/program/* does -- so
# the guard REPORTS them by real path and never deletes them. Reporting is the
# whole point: `workout-del` used to leave .active-session / .session-closed /
# .idrill-arm / .set-table-published / .exercise-entered (+ .arm-gen /
# .set-arm-override / .plate-cue) and a running rest countdown all pointing at a
# session id that no longer exists. The domain-side verb that DOES clean them is
# files/program/session-abort -- which is what a caller should reach for instead.
_WORKOUT_MARKER_FILES = (".active-session", ".session-closed")
_WORKOUT_MARKER_DIRS = (".idrill-arm", ".set-table-published",
                        ".exercise-entered", ".arm-gen", ".set-arm-override",
                        ".plate-cue")


def _workout_state_dir():
    """The domain runtime-state dir (files/program), or None when this install
    has none (Ag). Honours LIFEKIT_HEALTH_STATE_DIR exactly like the health
    pack's program CLIs do (pack 0.17.0 renamed it from WARG_STATE_DIR in
    lockstep with kit 2.27.0), so a test never reads the owner's live surface."""
    d = os.environ.get("LIFEKIT_HEALTH_STATE_DIR")
    if not d:
        d = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                         "..", "files", "program")
    d = os.path.abspath(d)
    return d if os.path.isdir(d) else None


def workout_stale_markers(wid, state_dir=None):
    """Filesystem markers that would be left pointing at a dead session id.

    Returns a list of (kind, path) -- read-only, best-effort, never raises.
    `.idrill-arm` files are named by a sha256 of (sid|exercise|seq) so they can
    only be attributed by READING the JSON payload's session_id, which is what
    this does. A running rest countdown (.telegram_bot/countdown/rest-*.json) is
    not session-keyed at all, so any live one is reported as `countdown`.
    """
    out = []
    try:
        sd = state_dir or _workout_state_dir()
        if not sd:
            return out
        sid = str(int(wid))
        for name in _WORKOUT_MARKER_FILES:
            p = os.path.join(sd, name)
            try:
                with open(p) as fh:
                    if fh.read().strip() == sid:
                        out.append((name, p))
            except (OSError, ValueError):
                pass
        for name in _WORKOUT_MARKER_DIRS:
            d = os.path.join(sd, name)
            if not os.path.isdir(d):
                continue
            for entry in sorted(os.listdir(d)):
                p = os.path.join(d, entry)
                if entry.split(".")[0] == sid:
                    out.append((name, p))
                elif name == ".idrill-arm":
                    try:
                        with open(p) as fh:
                            if str(json.load(fh).get("session_id")) == sid:
                                out.append((name, p))
                    except (OSError, ValueError, AttributeError):
                        pass
        cd = os.path.abspath(os.path.join(sd, "..", "..", ".telegram_bot",
                                          "countdown"))
        if os.path.isdir(cd):
            for entry in sorted(os.listdir(cd)):
                if entry.startswith("rest-") and entry.endswith(".json"):
                    out.append(("countdown", os.path.join(cd, entry)))
    except Exception:  # noqa: BLE001 -- a marker scan must never block a report
        pass
    return out


class WorkoutDeleteRefused(Exception):
    """workout_del refused: dependents exist and the caller did not confirm the
    exact count. Carries the census so every caller renders the same facts."""

    def __init__(self, census):
        self.census = census
        super().__init__("workout-del refused: %s dependent set row(s)"
                         % census.get('sets', 0))


def workout_del(wid, conn=None, confirm_sets=None):
    """DESTRUCTIVE + CASCADING. Guarded since 2026-08-25.

    `DELETE FROM workouts WHERE id=?` cascades to EVERY workout_sets row of that
    session (workout_sets.session_id ... ON DELETE CASCADE, foreign_keys=ON) and
    to its workout_classifications rows. Before this guard it did that silently:
    no count, no names, no question, and the only output was
    `deleted workout {id}`.

    confirm_sets is a COUNT-MATCHED confirmation token, not a boolean: the caller
    must pass the exact number of workout_sets rows that will be destroyed. That
    number is only obtainable by first running the call WITHOUT it and reading
    the refusal, so a model firing the verb casually cannot satisfy it -- it has
    to have seen the census. A 0-set session needs `confirm_sets=0`, which IS
    guessable, and that is fine: 0 sets means the cascade destroys nothing.

    Raises WorkoutDeleteRefused when the token is absent or mismatched. Raises
    nothing and deletes nothing when the row does not exist (returns the census).
    Returns the census dict of what WAS destroyed.
    """
    own = conn is None
    if own:
        conn = get_conn()
    try:
        census = workout_dependents(wid, conn)
        if not census['exists']:
            return census
        if confirm_sets is None or int(confirm_sets) != census['sets']:
            raise WorkoutDeleteRefused(census)
        conn.execute("DELETE FROM workouts WHERE id=?;", (int(wid),))
        # cut 4 slab 2: the value shadow dies in the SAME tx -- a surviving
        # measure row would keep counting a deleted session into the week.
        _workout_shadow_del(conn, int(wid))
        conn.commit()
        return census
    finally:
        if own:
            conn.close()


# ── 집계 ───────────────────────────────────────────────────
def _entry_instant_local(ts):
    """Stored entry instant -> NAIVE LOCAL datetime. Both idioms accepted.

    036 moved meals onto the block axis, whose created_at defaults to
    strftime('%Y-%m-%dT%H:%M:%SZ','now') -- canonical UTC. workouts did NOT
    move; its created_at still defaults to datetime('now','localtime')
    ('YYYY-MM-DD HH:MM:SS'). One day's entries therefore arrive in two
    idioms, and a reader that knows only the pre-036 one dies on the first
    meal of the day (measured 2026-09-07: agg-day raised ValueError the
    moment TODAY had a meal row; latent 21h because the branch only runs
    when today has data).

    A 'Z' value is converted to the HOST's local zone BEFORE the tzinfo is
    dropped (the .replace(tzinfo=utc).astimezone() idiom this file already
    uses, host-local rather than a named zone because the comparand is
    datetime.now()). Parsing 'Z' naively would silently place the entry 9
    hours early on a KST host -- a wrong close time, not a loud failure.

    Empty/NULL -> None. An unknown shape raises ValueError: only these two
    writers exist, so a third shape is a defect, not a case to absorb."""
    if not ts:
        return None
    if ts.endswith('Z'):
        return (datetime.datetime.strptime(ts, '%Y-%m-%dT%H:%M:%SZ')
                .replace(tzinfo=timezone.utc)
                .astimezone()
                .replace(tzinfo=None))
    return datetime.datetime.strptime(ts, '%Y-%m-%d %H:%M:%S')


def _day_last_entry_at(date, conn):
    """Latest created_at over meals+workouts rows with date=D, as STORED
    text (either idiom -- see _entry_instant_local); None if no rows.

    The max is taken in python on the NORMALIZED instant, not by SQL MAX():
    since 036 the union mixes 'YYYY-MM-DDTHH:MM:SSZ' (meals, through block)
    with 'YYYY-MM-DD HH:MM:SS' (workouts), and lexicographically 'T' (0x54)
    beats ' ' (0x20) -- SQL MAX would hand back the day's last MEAL even
    when a workout was logged hours later, closing the day early.

    Known limitation (DGN-669 MAJOR1, spun-out ticket): only inserts and
    date-move-ins are detected. meal_del / workout_del and meal_upd
    date-move-out mutate a day's numbers WITHOUT advancing the max
    (a delete can even move it backward), so those mutations to an
    already-closed day are undetected -- the day stays closed with changed
    numbers. Full coverage needs a touch-log/tombstone (separate ticket);
    migration 012 (updated_at) would cover updates only."""
    rows = conn.execute(
        "SELECT created_at FROM ("
        "SELECT created_at FROM " + MEALS_V32 + " WHERE date=? "
        "UNION ALL SELECT created_at FROM workouts WHERE date=?);",
        (date, date)).fetchall()
    stamps = [r[0] for r in rows if r and r[0]]
    if not stamps:
        return None
    return max(stamps, key=_entry_instant_local)


def _day_close_time(date, last_entry_at):
    """Local datetime at which day D closes (DGN-669 hybrid rule):
    max(last_entry_at + DAY_CLOSE_QUIET_HOURS, D+1 DAY_CLOSE_GRACE_TIME).
    No entries -> the noon floor alone governs.

    last_entry_at is stored text in either idiom; it is normalized to naive
    local (_entry_instant_local) so the comparison against the naive-local
    floor -- and against datetime.now() in the callers -- stays same-frame."""
    floor = datetime.datetime.combine(
        datetime.date.fromisoformat(date) + datetime.timedelta(days=1),
        DAY_CLOSE_GRACE_TIME)
    if not last_entry_at:
        return floor
    quiet = (_entry_instant_local(last_entry_at)
             + datetime.timedelta(hours=DAY_CLOSE_QUIET_HOURS))
    return max(floor, quiet)


def agg_day(date, conn=None, now=None):
    """그날 섭취/매크로/소모/밸런스 dict (v_daily_energy 기반).

    DGN-669: additive finality keys as_of / last_entry_at / closed appended;
    all pre-existing keys unchanged (consumers parse ^key=). now is an
    internal-only injectable kwarg for tests."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        row = conn.execute(
            "SELECT intake_kcal, protein_g, carb_g, fat_g, burn_kcal, workout_min "
            "FROM v_daily_energy WHERE date=?;", (date,)).fetchone()
        intake, protein, carb, fat, burn, wmin = row if row else (0, 0, 0, 0, 0, 0)
        meal_cnt = conn.execute(
            "SELECT COUNT(*) FROM " + MEALS_V32 + " WHERE date=?;", (date,)).fetchone()[0]
        wo_cnt = conn.execute(
            "SELECT COUNT(*) FROM workouts WHERE date=?;", (date,)).fetchone()[0]
        if now is None:
            now = datetime.datetime.now()
        last = _day_last_entry_at(date, conn)
        _burn, burn_missing = day_burn_kcal(date, conn=conn)
        return {
            'burn_missing': burn_missing,
            'burn_known': _burn is not None,
            'date': date,
            'meal_cnt': meal_cnt,
            'intake_kcal': intake or 0,
            'protein_g': protein or 0,
            'carb_g': carb or 0,
            'fat_g': fat or 0,
            'workout_cnt': wo_cnt,
            'workout_min': wmin or 0,
            'burn_kcal': burn or 0,
            'balance': (intake or 0) - (burn or 0),
            'as_of': now.strftime('%Y-%m-%d %H:%M:%S'),
            'last_entry_at': last,
            'closed': now >= _day_close_time(date, last),
        }
    finally:
        if own:
            conn.close()


def _shift_date(iso, days):
    d = datetime.date.fromisoformat(iso) + datetime.timedelta(days=days)
    return d.isoformat()


def agg_week(monday, conn=None, now=None):
    """그 주(월~일) 집계 + 직전주 대비 dict. monday=월요일 YYYY-MM-DD.

    DGN-669: additive top-level 'as_of' + per-day 'closed' flag on daily rows
    (per-day only, no top-level closed). now injectable for tests."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        if now is None:
            now = datetime.datetime.now()
        nxt = _shift_date(monday, 7)     # 다음주 월(배타)
        prev = _shift_date(monday, -7)   # 직전주 월(포함)
        sun = _shift_date(monday, 6)     # 이번주 일

        cur = conn.execute(
            "SELECT COALESCE(SUM(kcal),0), COALESCE(SUM(protein),0), "
            "COALESCE(SUM(carb),0), COALESCE(SUM(fat),0), COUNT(*), "
            "COUNT(DISTINCT date) FROM " + MEALS_V32 + " WHERE date >= ? AND date < ?;",
            (monday, nxt)).fetchone()
        c_ik, c_pr, c_cb, c_ft, c_mc, c_md = cur

        pv = conn.execute(
            "SELECT COALESCE(SUM(kcal),0), COUNT(DISTINCT date) "
            "FROM " + MEALS_V32 + " WHERE date >= ? AND date < ?;",
            (prev, monday)).fetchone()
        p_ik, p_md = pv

        cw = conn.execute(
            "SELECT COALESCE(SUM(kcal),0), COALESCE(SUM(minutes),0), COUNT(*) "
            "FROM workouts WHERE date >= ? AND date < ?;",
            (monday, nxt)).fetchone()
        cw_bk, cw_wm, cw_wc = cw

        pw = conn.execute(
            "SELECT COALESCE(SUM(kcal),0), COUNT(*) "
            "FROM workouts WHERE date >= ? AND date < ?;",
            (prev, monday)).fetchone()
        pw_bk, pw_wc = pw

        cur_avg = c_ik / c_md if c_md > 0 else 0
        prev_avg = p_ik / p_md if p_md > 0 else 0

        # 일별 추이
        daily = []
        for i in range(7):
            d = _shift_date(monday, i)
            dow = _WDAY_EN[datetime.date.fromisoformat(d).weekday()]
            row = conn.execute(
                "SELECT intake_kcal, burn_kcal FROM v_daily_energy WHERE date=?;",
                (d,)).fetchone()
            ik = row[0] if row else 0
            bk = row[1] if row else 0
            mc = conn.execute(
                "SELECT COUNT(*) FROM " + MEALS_V32 + " WHERE date=?;", (d,)).fetchone()[0]
            wc = conn.execute(
                "SELECT COUNT(*) FROM workouts WHERE date=?;", (d,)).fetchone()[0]
            daily.append({'date': d, 'dow': dow, 'intake': ik or 0,
                          'burn': bk or 0, 'meal_cnt': mc, 'workout_cnt': wc,
                          'closed': now >= _day_close_time(
                              d, _day_last_entry_at(d, conn))})

        return {
            'as_of': now.strftime('%Y-%m-%d %H:%M:%S'),
            'monday': monday, 'sunday': sun,
            'meal_cnt': c_mc, 'meal_days': c_md,
            'intake_total': c_ik, 'intake_avg_day': cur_avg,
            'protein_total': c_pr, 'carb_total': c_cb, 'fat_total': c_ft,
            'workout_cnt': cw_wc, 'workout_min': cw_wm, 'burn_total': cw_bk,
            'prev_intake_total': p_ik, 'prev_intake_avg_day': prev_avg,
            'prev_workout_cnt': pw_wc, 'prev_burn_total': pw_bk,
            'diff_intake_avg': cur_avg - prev_avg,
            'diff_workout_cnt': cw_wc - pw_wc,
            'diff_burn_total': cw_bk - pw_bk,
            'daily': daily,
        }
    finally:
        if own:
            conn.close()


def _kst_monday(now=None):
    """This week's Monday (YYYY-MM-DD) for the KST-local 'now'.

    kit_life runs single-tz (Asia/Seoul); created_at/date are localtime text, so
    the process-local date IS the KST date -- no tz conversion needed. Returns
    the Monday (weekday()==0) of the week containing 'now' (or today)."""
    if now is None:
        now = datetime.datetime.now()
    today = now.date() if isinstance(now, datetime.datetime) else now
    return (today - datetime.timedelta(days=today.weekday())).isoformat()


def rotation_current(monday=None, conn=None, now=None):
    """Deterministic workout-rotation / week-summary for one Mon..Sun week.

    Reads workouts JOIN session_type (never guesses). The rotation cycle is the
    session_type rows with sort<99, ORDER BY sort (wrap-around). Strength =
    workouts.session_type_id NOT NULL; cardio = session_type_id NULL. A split
    counts as completed_this_week only when its row has >=1 real workout_sets
    set -- a birth-tagged but empty 0-set row is NOT complete. last_split (and
    therefore next_split) honors the SAME guard: the tag is written at session
    BIRTH, so a tag-only test would make a just-opened empty session its own
    predecessor and push next_split one slot past the split being trained.

    monday: the week's Monday YYYY-MM-DD; default = this KST week's Monday.
    Returns a dict (week_monday / completed_this_week / cardio_this_week /
    last_split / next_split / remaining_this_week). Read-only; no writes."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        mon = monday or _kst_monday(now)
        nxt = _shift_date(mon, 7)   # next Monday (exclusive upper bound)

        # rotation cycle: sort<99 codes on the ACTIVE routine, in sort
        # order (the wrap sequence). No active routine -> empty cycle,
        # never a raise.
        cycle = [r[0] for r in conn.execute(
            "SELECT st.code FROM session_type st "
            "JOIN routine r ON r.id = st.routine_id "
            "WHERE r.status='active' AND st.sort < 99 "
            "ORDER BY st.sort, st.id;"
        ).fetchall()]

        # strength splits done THIS week, in date/created_at order, deduped
        # (first occurrence kept).
        completed = []
        seen = set()
        for code in (r[0] for r in conn.execute(
                "SELECT st.code FROM workouts w "
                "JOIN session_type st ON st.id = w.session_type_id "
                "WHERE w.session_type_id IS NOT NULL "
                "AND EXISTS (SELECT 1 FROM workout_sets ws "
                "WHERE ws.session_id = w.id) "
                "AND w.date >= ? AND w.date < ? "
                "ORDER BY w.date, w.created_at, w.id;",
                (mon, nxt)).fetchall()):
            if code not in seen:
                seen.add(code)
                completed.append(code)

        # cardio (session_type_id NULL) count this week.
        cardio = conn.execute(
            "SELECT COUNT(*) FROM workouts "
            "WHERE session_type_id IS NULL AND date >= ? AND date < ?;",
            (mon, nxt)).fetchone()[0]

        # last strength split overall (could be a prior week). date desc,
        # created_at desc, id desc = most recent single row.
        # G1: the same >=1-set guard completed_this_week uses. Instances may
        # share one DB, so a tag-only test here would have two copies of this
        # function answering different splits for identical data -- and would
        # make a freshly OPENED (0-set) session its own predecessor, skipping
        # the split actually being trained. Anchored to the set fact, every
        # reader agrees.
        lrow = conn.execute(
            "SELECT st.code FROM workouts w "
            "JOIN session_type st ON st.id = w.session_type_id "
            "WHERE w.session_type_id IS NOT NULL "
            "AND EXISTS (SELECT 1 FROM workout_sets ws "
            "WHERE ws.session_id = w.id) "
            "ORDER BY w.date DESC, w.created_at DESC, w.id DESC LIMIT 1;"
        ).fetchone()
        last_split = lrow[0] if lrow else ''

        # next_split anchors on the latest CYCLE split, not on the latest
        # strength row: an off-cycle session (free / makeup, sort >= 99 or
        # another routine) must not reset the rotation to the cycle head.
        # last_split above stays the literal latest strength session.
        anchor = ''
        if cycle:
            for (code,) in conn.execute(
                    "SELECT st.code FROM workouts w "
                    "JOIN session_type st ON st.id = w.session_type_id "
                    "WHERE w.session_type_id IS NOT NULL "
                    "AND EXISTS (SELECT 1 FROM workout_sets ws "
                    "WHERE ws.session_id = w.id) "
                    "ORDER BY w.date DESC, w.created_at DESC, w.id DESC;"):
                if code in cycle:
                    anchor = code
                    break

        # next_split: next code in cycle after the anchor (wrap). No cycle
        # split ever -> start at cycle head.
        if not cycle:
            next_split = ''
        elif anchor:
            next_split = cycle[(cycle.index(anchor) + 1) % len(cycle)]
        else:
            next_split = cycle[0]

        # remaining: cycle codes not yet done this week (informational).
        remaining = [c for c in cycle if c not in seen]

        return {
            'week_monday': mon,
            'completed_this_week': completed,
            'cardio_this_week': cardio,
            'last_split': last_split,
            'next_split': next_split,
            'remaining_this_week': remaining,
        }
    finally:
        if own:
            conn.close()


# ── 소비 CRUD (DGN-553 J1) ────────────────────────────────
# spend_category: 카테고리 사전 (workout_types 패턴 -- 미지 카테고리 자동 등록).
# spend_entry:    지출 한 건 (scope='personal'|'business'|'unknown').
# source: 'chat' (C1 대화 즉시 기록) | 'batch' (C2 세션 보충 입력).
# SDK enforces source value set -- no CHECK on the column by design (grill r1 m3).

def _spend_category_key(conn, label):
    """Derive a stable ASCII key for spend_category.name from a display label.

    032: name is the machine key, display_name carries the label. An ASCII
    label slugs directly ("Netflix" -> "netflix"); a non-ASCII label has no
    meaningful transliteration here and falls back to the generic "cat" stem.
    The stem is then probed against the existing keys, so the returned key can
    never collide with name's UNIQUE index.
    """
    stem = re.sub(r'[^a-z0-9]+', '_', label.lower()).strip('_')
    if not stem:
        stem = 'cat'
    key, n = stem, 1
    while conn.execute("SELECT 1 FROM spend_category WHERE name=? LIMIT 1;",
                       (key,)).fetchone():
        n += 1
        key = "%s_%d" % (stem, n)
    return key


def spend_category_id(conn, name):
    """Category label -> spend_category.id. None when unknown.

    032: accepts EITHER the ASCII key (name) or the display label
    (display_name). Callers and the skills still pass the ko label, so the
    display_name lookup is what keeps them resolving after tokenization.
    """
    row = conn.execute(
        "SELECT id FROM spend_category WHERE name=? LIMIT 1;",
        (name,)).fetchone()
    if row:
        return row[0]
    row = conn.execute(
        "SELECT id FROM spend_category WHERE display_name=? LIMIT 1;",
        (name,)).fetchone()
    return row[0] if row else None


def spend_category_get_or_create(conn, name):
    """Category label -> id; auto-registers an unknown label (is_fixed_default=0).

    032: a new row is stored as (name = ASCII key, display_name = the label as
    the caller wrote it), so an unknown ko category can never write a
    non-ASCII value back into name and unwind the migration.
    Empty label -> None (a spend row may carry no category).
    """
    nm = (name or '').strip()
    if not nm:
        return None
    cid = spend_category_id(conn, nm)
    if cid is not None:
        return cid
    key = _spend_category_key(conn, nm)
    cur = conn.execute(
        "INSERT INTO spend_category (name, display_name, is_fixed_default, sort) "
        "VALUES (?,?,0,0);",
        (key, nm))
    print("[spend] auto-registered unknown category: %r -> name=%s id=%s"
          % (nm, key, cur.lastrowid), file=sys.stderr)
    return cur.lastrowid


# ── 039: the resource x entity crossing for the ledger lane ────────────────
# spend_entry stays the ledger lane's store of record (every spend_* reader
# keeps reading it).  Each row additionally carries a SHADOW on the v3.2
# axis: one date-only 'record' block (deterministic ulid 'x-spend-<id>' --
# the 036 manufactured-identity idiom, filtered out of the timeblock compat
# view) plus ONE money delta.  Sign per canon (inflow + / outflow -):
# expense -> -amount (a negative expense amount is a refund and correctly
# flips to inflow), income -> +amount.  The delta's entity is the payment
# instrument the row's own method string names.

def _spend_entity_id(conn, method):
    """method 문자열 -> entity.id.  fail-CLOSED: 라벨(namespace='entity')이
    정확히 한 active entity 를 가리킬 때만 붙는다.  없거나(미등록 수단)
    모호하면(같은 표시가 두 entity) None -- 무귀속은 v_c2_coverage 가 세는
    상태이지, 아무 데나 담는 catch-all 이 아니다 (039 규율)."""
    m = (method or '').strip()
    if not m:
        return None
    row = conn.execute(
        "SELECT MIN(e.id), COUNT(DISTINCT e.id) FROM entity e "
        "JOIN label l ON l.namespace='entity' AND l.token=e.token "
        "WHERE e.status='active' AND l.display=?;", (m,)).fetchone()
    return row[0] if row and row[1] == 1 else None


def _spend_write_v32(conn, sid, date, name, amount, kind, method):
    """spend_entry 한 건의 v3.2 그림자(블록+머니 델타)를 (재)작성한다.
    반환: block.id.  갱신 시 블록은 제자리(created_at/settled_at 보존),
    델타만 지우고 다시 쓴다 (_meal_write_v32 와 같은 관용구)."""
    ulid = 'x-spend-%d' % int(sid)
    row = conn.execute("SELECT id FROM block WHERE ulid=?;", (ulid,)).fetchone()
    if row:
        bid = row[0]
        conn.execute("UPDATE block SET title=?, date=? WHERE id=?;",
                     (name, date, bid))
        # 059 (intake): rewrite the single money delta IN PLACE -- value_origin (an
        # intake provenance, say) survives an edit, and the intake triggers
        # see a real before/after instead of a delete+insert.
        old = conn.execute("SELECT id FROM block_delta WHERE block_id=?;",
                           (bid,)).fetchall()
        if len(old) == 1 and conn.execute(
                "SELECT resource FROM block_delta WHERE id=?;",
                (old[0][0],)).fetchone()[0] == 'money':
            signed = int(amount) if kind == 'income' else -int(amount)
            conn.execute(
                "UPDATE block_delta SET entity_id=?, amount=?, unit='krw', "
                "component='' WHERE id=?;",
                (_spend_entity_id(conn, method), signed, old[0][0]))
            return bid
        conn.execute("DELETE FROM block_delta WHERE block_id=?;", (bid,))
    else:
        now = now_utc()
        cur = conn.execute(
            "INSERT INTO block(ulid, source_module, title, date, kind_token, "
            "settled_at, settled_outcome, settled_by, settled_verdict, "
            "created_at) VALUES (?,?,?,?,?,?,?,?,?,?);",
            (ulid, 'ledger', name, date, 'record',
             now, 'done', 'spend-record', 'machine', now))
        bid = cur.lastrowid
    signed = int(amount) if kind == 'income' else -int(amount)
    conn.execute(
        "INSERT INTO block_delta(block_id, resource, entity_id, amount, unit, "
        "component, value_origin) VALUES (?,?,?,?,?,?,?);",
        (bid, 'money', _spend_entity_id(conn, method), signed, 'krw', '',
         'declared'))
    return bid


def _spend_shadow_del(conn, sid):
    """spend_entry 한 건의 그림자 블록 삭제 (델타/attr 은 CASCADE)."""
    row = conn.execute(
        "SELECT id FROM block WHERE ulid=? AND settled_by='spend-record';",
        ('x-spend-%d' % int(sid),)).fetchone()
    if row is None:
        return
    conn.execute("DELETE FROM block WHERE id=?;", (row[0],))
    _block_record_del(conn, row[0])


def spend_add(date, amount, name, category=None, method=None, scope='personal',
              note=None, is_fixed=None, source='chat', kind='expense',
              conn=None, commit=True):
    """지출/수입 한 건 기록. 새 행 id 반환.

    is_fixed 미지정(None) 시 spend_category.is_fixed_default 상속.
    카테고리 미등록이면 auto-register (+ stderr 경고). scope는 verb 계층에서 검증.
    kind='expense'|'income' (DGN-564; verb 계층에서 검증). 수입은 amount 양수."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        if not conn.in_transaction:
            conn.execute('BEGIN IMMEDIATE')
        cid = spend_category_get_or_create(conn, category) if category else None
        if is_fixed is None:
            if cid is not None:
                row = conn.execute(
                    "SELECT is_fixed_default FROM spend_category WHERE id=?;",
                    (cid,)).fetchone()
                is_fixed = row[0] if row else 0
            else:
                is_fixed = 0
        # 059 (intake): ids are never reused (archive reset / spend-del of the last
        # row). spend_id_floor holds the highest id ever deleted; allocate
        # above it explicitly. Pre-059 databases have no floor row -> 0.
        floor = conn.execute(
            "SELECT value FROM ledger_guard WHERE guard_key='spend_id_floor' "
            "AND scope='global';").fetchone()
        new_id = max(conn.execute(
            "SELECT COALESCE(MAX(id),0) FROM spend_entry;").fetchone()[0],
            int(floor[0] or 0) if floor else 0) + 1
        cur = conn.execute(
            "INSERT INTO spend_entry "
            "(id, date, amount, name, category_id, method, is_fixed, scope, "
            "source, note, kind) "
            "VALUES (?,?,?,?,?,?,?,?,?,?,?);",
            (new_id, date, int(amount), name, cid, _txt(method), int(is_fixed),
             scope, source, _txt(note), kind))
        # 039: same-tx crossing shadow (block + money delta + instrument).
        _spend_write_v32(conn, cur.lastrowid, date, name, int(amount), kind,
                         _txt(method))
        if commit:
            conn.commit()
        return cur.lastrowid
    finally:
        if own:
            conn.close()


def spend_find(date, scope_filter='personal', include_all=False, conn=None):
    """그날 지출 목록. 반환: (id, name, amount, cat_key, cat_display, method, scope).

    cat_key = english category key (machine TSV). cat_display = ko label
    (COALESCE(display_name, name); human render). include_all=True -> scope 무관 전체.
    False -> scope_filter 일치행만."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        # m-3 (grill fix): NULL category_id renders as '(미분류)' to avoid
        # colliding with the real seeded 'etc' category. i18n: english key +
        # ko display projected side by side; caller picks per human/machine.
        if include_all:
            return conn.execute(
                "SELECT e.id, e.name, e.amount, "
                "COALESCE(c.name,'(미분류)'), "
                "COALESCE(c.display_name, c.name, '(미분류)'), "
                "COALESCE(e.method,''), e.scope "
                "FROM spend_entry e "
                "LEFT JOIN spend_category c ON c.id = e.category_id "
                "WHERE e.date=? ORDER BY e.id;", (date,)).fetchall()
        return conn.execute(
            "SELECT e.id, e.name, e.amount, "
            "COALESCE(c.name,'(미분류)'), "
            "COALESCE(c.display_name, c.name, '(미분류)'), "
            "COALESCE(e.method,''), e.scope "
            "FROM spend_entry e "
            "LEFT JOIN spend_category c ON c.id = e.category_id "
            "WHERE e.date=? AND e.scope=? ORDER BY e.id;",
            (date, scope_filter)).fetchall()
    finally:
        if own:
            conn.close()


def spend_del(sid, conn=None):
    """지출 한 건 삭제."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        conn.execute("DELETE FROM spend_entry WHERE id=?;", (int(sid),))
        _spend_shadow_del(conn, sid)   # 039: same-tx crossing shadow
        conn.commit()
    finally:
        if own:
            conn.close()


# Updatable columns for spend-upd (amount is INTEGER, others text/int).
# M-1 (grill fix): amount and is_fixed use strict int(), not _num() fallback.
# Callers that pass a non-integer string (e.g. "abc", "99.9") get ValueError,
# which cli_spend_upd catches and routes to a clean rc=1 error message.
def _strict_amount(v):
    """Strict integer converter for spend amount. Rejects floats and non-numeric strings."""
    try:
        return int(str(v))
    except (ValueError, TypeError):
        raise ValueError(f"amount는 정수(KRW)여야 함: {v}")


def _strict_is_fixed(v):
    """Strict 0/1 converter for is_fixed. Rejects anything outside {0, 1}."""
    try:
        iv = int(str(v))
    except (ValueError, TypeError):
        raise ValueError(f"is_fixed 값 오류: {v} (0 또는 1이어야 함)")
    if iv not in (0, 1):
        raise ValueError(f"is_fixed 값 오류: {v} (0 또는 1이어야 함)")
    return iv


_SPEND_UPD_COLS = {
    'date': _txt, 'name': _txt, 'method': _txt, 'note': _txt,
    'amount': _strict_amount,
    'is_fixed': _strict_is_fixed,
    'scope': _txt, 'source': _txt, 'kind': _txt,
    'category': None,  # handled specially
}
_SPEND_UPD_VALID_SCOPE = {'personal', 'business', 'unknown'}
# m-2 (grill fix): enforce spec 3.1 v1 value set: 'chat' | 'batch' only.
# 'import' and 'receipt' are v2+ adapter values; SDK layer enforces, no DB CHECK.
_SPEND_UPD_VALID_SOURCE = {'chat', 'batch'}
# DGN-564: kind value set; no DB CHECK (source precedent), SDK enforces here.
_SPEND_UPD_VALID_KIND = {'expense', 'income'}


def spend_upd(sid, fields, conn=None):
    """지출 한 건의 지정 필드 부분 갱신. 갱신 후 (id, name, amount, category) 반환 (없으면 None)."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        sets, vals = [], []
        cat_name = None
        for col, raw in fields.items():
            if col == 'category':
                cat_name = raw
                continue
            if col not in _SPEND_UPD_COLS:
                raise ValueError(f"수정 불가 컬럼: {col}")
            if col == 'scope' and raw not in _SPEND_UPD_VALID_SCOPE:
                raise ValueError(f"scope 값 오류: {raw} (personal/business/unknown)")
            if col == 'source' and raw not in _SPEND_UPD_VALID_SOURCE:
                raise ValueError(f"source 값 오류: {raw}")
            if col == 'kind' and raw not in _SPEND_UPD_VALID_KIND:
                raise ValueError(f"kind 값 오류: {raw} (expense/income)")
            conv = _SPEND_UPD_COLS[col]
            sets.append(f"{col}=?")
            vals.append(conv(raw))
        if cat_name is not None:
            cid = spend_category_get_or_create(conn, cat_name)
            sets.append("category_id=?")
            vals.append(cid)
        if not sets:
            raise ValueError("갱신할 필드가 없음")
        vals.append(int(sid))
        cur = conn.execute(
            f"UPDATE spend_entry SET {', '.join(sets)} WHERE id=?;", vals)
        if cur.rowcount:
            # 039: the crossing shadow follows the row -- rewrite it from
            # the post-update truth (date/amount/kind/method all live there).
            r = conn.execute("SELECT date, name, amount, kind, method "
                             "FROM spend_entry WHERE id=?;",
                             (int(sid),)).fetchone()
            if r:
                _spend_write_v32(conn, sid, r[0], r[1], r[2], r[3], r[4])
        conn.commit()
        if cur.rowcount == 0:
            return None
        return conn.execute(
            "SELECT e.id, e.name, e.amount, COALESCE(c.display_name, c.name,'') "
            "FROM spend_entry e "
            "LEFT JOIN spend_category c ON c.id = e.category_id "
            "WHERE e.id=?;", (int(sid),)).fetchone()
    finally:
        if own:
            conn.close()


def spend_week(monday, scope_filter='personal', include_all=False, conn=None):
    """주간 집계 dict (총액/카테고리별/건수/전주대비). monday=월요일 YYYY-MM-DD.

    scope_filter='personal' (기본). include_all=True -> 전 scope."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        nxt = _shift_date(monday, 7)
        prev = _shift_date(monday, -7)
        sun = _shift_date(monday, 6)

        scope_clause = "" if include_all else f"AND e.scope='{scope_filter}'"

        # DGN-564: expense aggregates mean "spend" -> filter kind='expense'.
        # Income rides separate subtotal + net (income - expense) lines.
        # Current week totals (expense)
        row = conn.execute(
            f"SELECT COALESCE(SUM(e.amount),0), COUNT(*) "
            f"FROM spend_entry e WHERE e.date >= ? AND e.date < ? "
            f"AND e.kind='expense' {scope_clause};",
            (monday, nxt)).fetchone()
        total, count = row

        # Previous week totals (expense)
        prev_row = conn.execute(
            f"SELECT COALESCE(SUM(e.amount),0), COUNT(*) "
            f"FROM spend_entry e WHERE e.date >= ? AND e.date < ? "
            f"AND e.kind='expense' {scope_clause};",
            (prev, monday)).fetchone()
        prev_total, prev_count = prev_row

        # Category breakdown (current week, expense).
        # m-3 (grill fix): NULL category_id renders as '(미분류)', not 'etc'.
        # i18n: human output -> ko display (COALESCE(display_name, name)).
        cat_rows = conn.execute(
            f"SELECT COALESCE(c.display_name, c.name, '(미분류)'), "
            f"COALESCE(SUM(e.amount),0), COUNT(*) "
            f"FROM spend_entry e "
            f"LEFT JOIN spend_category c ON c.id = e.category_id "
            f"WHERE e.date >= ? AND e.date < ? AND e.kind='expense' "
            f"{scope_clause} "
            f"GROUP BY e.category_id ORDER BY SUM(e.amount) DESC;",
            (monday, nxt)).fetchall()

        # Income subtotal (current week)
        inc_row = conn.execute(
            f"SELECT COALESCE(SUM(e.amount),0), COUNT(*) "
            f"FROM spend_entry e WHERE e.date >= ? AND e.date < ? "
            f"AND e.kind='income' {scope_clause};",
            (monday, nxt)).fetchone()
        income_total, income_count = inc_row

        return {
            'monday': monday, 'sunday': sun,
            'total': total, 'count': count,
            'prev_total': prev_total, 'prev_count': prev_count,
            'diff_total': total - prev_total,
            'income_total': income_total, 'income_count': income_count,
            'net': income_total - total,
            'categories': [{'name': r[0], 'amount': r[1], 'count': r[2]}
                           for r in cat_rows],
        }
    finally:
        if own:
            conn.close()


def spend_month(ym, scope_filter='personal', include_all=False, conn=None):
    """월간 집계 dict (총액/고정-변동/카테고리/method별/전월대비). ym='YYYY-MM'."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        import calendar
        year, month = int(ym[:4]), int(ym[5:7])
        _, last_day = calendar.monthrange(year, month)
        start = f"{ym}-01"
        end_excl = f"{ym}-{last_day + 1:02d}"  # exclusive upper bound
        # Compute actual next-month first day for clean half-open
        if month == 12:
            end_excl = f"{year + 1}-01-01"
        else:
            end_excl = f"{year}-{month + 1:02d}-01"

        scope_clause = "" if include_all else f"AND e.scope='{scope_filter}'"

        # Previous month bounds
        if month == 1:
            prev_ym = f"{year - 1}-12"
            prev_start = f"{year - 1}-12-01"
            prev_end_excl = f"{year}-01-01"
        else:
            prev_ym = f"{year}-{month - 1:02d}"
            prev_start = f"{year}-{month - 1:02d}-01"
            prev_end_excl = start

        # DGN-564: expense aggregates mean "spend" -> filter kind='expense'.
        # Income rides separate subtotal + net (income - expense) lines.
        # Total (expense)
        row = conn.execute(
            f"SELECT COALESCE(SUM(e.amount),0), COUNT(*) "
            f"FROM spend_entry e WHERE e.date >= ? AND e.date < ? "
            f"AND e.kind='expense' {scope_clause};",
            (start, end_excl)).fetchone()
        total, count = row

        # Fixed vs variable (expense)
        fv = conn.execute(
            f"SELECT e.is_fixed, COALESCE(SUM(e.amount),0) "
            f"FROM spend_entry e WHERE e.date >= ? AND e.date < ? "
            f"AND e.kind='expense' {scope_clause} "
            f"GROUP BY e.is_fixed;",
            (start, end_excl)).fetchall()
        fixed_total = sum(r[1] for r in fv if r[0] == 1)
        variable_total = sum(r[1] for r in fv if r[0] == 0)

        # Category breakdown (all categories, ordered by amount desc; expense).
        # m-3 (grill fix): NULL category_id renders as '(미분류)', not 'etc'.
        # i18n: human output -> ko display (COALESCE(display_name, name)).
        cat_rows = conn.execute(
            f"SELECT COALESCE(c.display_name, c.name, '(미분류)'), "
            f"COALESCE(SUM(e.amount),0), COUNT(*) "
            f"FROM spend_entry e "
            f"LEFT JOIN spend_category c ON c.id = e.category_id "
            f"WHERE e.date >= ? AND e.date < ? AND e.kind='expense' "
            f"{scope_clause} "
            f"GROUP BY e.category_id ORDER BY SUM(e.amount) DESC;",
            (start, end_excl)).fetchall()

        # Method breakdown (spend-month only, grill r1 m4; expense)
        method_rows = conn.execute(
            f"SELECT COALESCE(e.method,'(없음)'), COALESCE(SUM(e.amount),0), COUNT(*) "
            f"FROM spend_entry e WHERE e.date >= ? AND e.date < ? "
            f"AND e.kind='expense' {scope_clause} "
            f"GROUP BY e.method ORDER BY SUM(e.amount) DESC;",
            (start, end_excl)).fetchall()

        # Previous month total (expense)
        prev_row = conn.execute(
            f"SELECT COALESCE(SUM(e.amount),0), COUNT(*) "
            f"FROM spend_entry e WHERE e.date >= ? AND e.date < ? "
            f"AND e.kind='expense' {scope_clause};",
            (prev_start, prev_end_excl)).fetchone()
        prev_total, prev_count = prev_row

        # Income subtotal (current month)
        inc_row = conn.execute(
            f"SELECT COALESCE(SUM(e.amount),0), COUNT(*) "
            f"FROM spend_entry e WHERE e.date >= ? AND e.date < ? "
            f"AND e.kind='income' {scope_clause};",
            (start, end_excl)).fetchone()
        income_total, income_count = inc_row

        return {
            'ym': ym, 'start': start, 'end_excl': end_excl,
            'total': total, 'count': count,
            'fixed_total': fixed_total, 'variable_total': variable_total,
            'prev_ym': prev_ym, 'prev_total': prev_total, 'prev_count': prev_count,
            'diff_total': total - prev_total,
            'income_total': income_total, 'income_count': income_count,
            'net': income_total - total,
            'categories': [{'name': r[0], 'amount': r[1], 'count': r[2]}
                           for r in cat_rows],
            'methods': [{'method': r[0], 'amount': r[1], 'count': r[2]}
                        for r in method_rows],
        }
    finally:
        if own:
            conn.close()


def spend_unknown(conn=None):
    """M-2 (grill fix): list ALL scope='unknown' entries across all dates.

    Returns list of (id, date, name, amount, category, method) tuples,
    oldest first. This is the C2 sweep surface; reclassify via spend-upd scope=."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        return conn.execute(
            "SELECT e.id, e.date, e.name, e.amount, "
            "COALESCE(c.display_name, c.name,'(미분류)'), COALESCE(e.method,'') "
            "FROM spend_entry e "
            "LEFT JOIN spend_category c ON c.id = e.category_id "
            "WHERE e.scope='unknown' "
            "ORDER BY e.date ASC, e.id ASC;").fetchall()
    finally:
        if own:
            conn.close()


# ── 약속 / 사람 CRUD ───────────────────────────────────────
# 약속(appointments)과 사람(persons)은 appointment_persons로 N:M 연결.
# 사람은 본명(name) 외에 별명(aliases, 콤마조인)으로도 찾는다.
def person_find(query, conn=None):
    """이름 또는 별명에 query가 들어가는 사람 목록. (id, name, relation, aliases) 리스트."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        like = f"%{query}%"
        return conn.execute(
            "SELECT id, name, relation, aliases FROM persons "
            "WHERE name LIKE ? OR (aliases IS NOT NULL AND aliases LIKE ?) "
            "ORDER BY id;", (like, like)).fetchall()
    finally:
        if own:
            conn.close()


def person_add(name, relation=None, aliases=None, conn=None):
    """사람 한 명 신규 등록. 새 id 반환."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        cur = conn.execute(
            "INSERT INTO persons (name, relation, aliases) VALUES (?,?,?);",
            (name, _txt(relation), _txt(aliases)))
        conn.commit()
        return cur.lastrowid
    finally:
        if own:
            conn.close()


def person_alias_add(pid, alias, conn=None):
    """기존 사람의 aliases에 별명 하나 추가(콤마조인, 중복 무시). 갱신 행 반환(없으면 None)."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        row = conn.execute(
            "SELECT aliases FROM persons WHERE id=?;", (int(pid),)).fetchone()
        if row is None:
            return None
        cur_aliases = [a.strip() for a in (row[0] or '').split(',') if a.strip()]
        if alias.strip() and alias.strip() not in cur_aliases:
            cur_aliases.append(alias.strip())
        joined = ','.join(cur_aliases) or None
        conn.execute("UPDATE persons SET aliases=? WHERE id=?;",
                     (joined, int(pid)))
        conn.commit()
        return conn.execute(
            "SELECT id, name, aliases FROM persons WHERE id=?;",
            (int(pid),)).fetchone()
    finally:
        if own:
            conn.close()


# ══════════════════════════════════════════════════════════════════════════
# Person edit verbs (2.37.3). persons already carried birthday / relation /
# gender / residence / job / contact and persons_relations already held the
# group-auto links, but no verb could write any of it: "add a birthday" or
# "C is A and B's daughter" left the agent offering a raw DB edit. These are the writes; the CLI wrappers (person-set /
# person-link / person-unlink / person-show) sit with the other person CLIs.
#
# persons_relations stores a pair once (CHECK person_a < person_b). The row
# reads "person_a is <relation_type> of person_b"; a directed type given in
# the other order is stored flipped with its inverse, so parent/child keeps
# its direction under the CHECK. The 293 group-auto rows are 'acquaintance',
# which reads the same both ways.
# ══════════════════════════════════════════════════════════════════════════

PERSON_SET_FIELDS = ("birthday", "relation", "gender", "residence", "job",
                     "contact")

# persons.relation vocabulary (the live select; schema comment 관계 select).
PERSON_RELATIONS = ("family", "partner", "close_friend", "friend",
                    "acquaintance", "business", "unrelated")
# 'unrelated' (owner 2026-10-02, shown 관계없음 / "no direct tie"): no direct
# tie to the user, known only through someone else (a friend's child).
# Distinct from NULL, which means "not asked yet". How many hops away
# (건너건너) is computed from the persons_relations graph (person_hops),
# never stored.

# persons_relations.relation_type vocabulary: token -> its inverse.
PERSON_LINK_TYPES = {
    "parent": "child", "child": "parent",
    "spouse": "spouse", "sibling": "sibling", "partner": "partner",
    "family": "family", "friend": "friend", "colleague": "colleague",
    "acquaintance": "acquaintance",
}

# Owner words accepted as INPUT for a token. Output always renders through
# the i18n label (person.relation.<t> / person.link.<t>), never these.
_PERSON_RELATION_WORDS = {
    "가족": "family", "친척": "family", "연인": "partner", "애인": "partner",
    "절친": "close_friend", "친한친구": "close_friend", "친한 친구": "close_friend",
    "친구": "friend", "지인": "acquaintance", "아는사람": "acquaintance",
    "아는 사람": "acquaintance", "비즈니스": "business", "업무": "business",
    "일": "business", "관계없음": "unrelated", "관계 없음": "unrelated",
    "건너 아는 사이": "unrelated", "건너아는사이": "unrelated",
}
_PERSON_LINK_WORDS = {
    "부모": "parent", "엄마": "parent", "아빠": "parent", "어머니": "parent",
    "아버지": "parent", "mother": "parent", "father": "parent",
    "자녀": "child", "자식": "child", "딸": "child", "아들": "child",
    "daughter": "child", "son": "child",
    "배우자": "spouse", "남편": "spouse", "아내": "spouse", "부부": "spouse",
    "husband": "spouse", "wife": "spouse",
    "형제": "sibling", "자매": "sibling", "남매": "sibling",
    "형제자매": "sibling", "brother": "sibling", "sister": "sibling",
    "연인": "partner", "애인": "partner", "친척": "family",
    "친구": "friend", "동료": "colleague", "지인": "acquaintance",
}
# "가족" is NOT a link word (owner 2026-10-02: spouse/parent/sibling are
# stored as themselves, never lumped): the family link token is kept only for
# other kin (친척) and a lumped word must be asked as the specific relation.
_PERSON_GENDER_WORDS = {
    "m": "M", "male": "M", "남": "M", "남자": "M", "남성": "M",
    "f": "F", "female": "F", "여": "F", "여자": "F", "여성": "F",
    # 'X' = other (owner 2026-10-02 "기타 추가"); empty = unknown
    "x": "X", "other": "X", "기타": "X",
}

_BDAY_FULL_RE = re.compile(r"^(\d{4})[-./]?(\d{1,2})[-./]?(\d{1,2})$")
_BDAY_FULL8_RE = re.compile(r"^(\d{4})(\d{2})(\d{2})$")
_BDAY_SHORT_RE = re.compile(r"^(\d{2})[-./]?(\d{2})[-./]?(\d{2})$")
_BDAY_SHORT_SEP_RE = re.compile(r"^(\d{2})[-./](\d{1,2})[-./](\d{1,2})$")


def person_today_local():
    """Today in the kit display tz -- the 'now' a 2-digit birth year is
    resolved against. One seam so a test can pin it."""
    return datetime.datetime.now(ZoneInfo(TRAVEL_DISPLAY_TZ)).date()


def parse_birthday(raw, today=None):
    """Owner's birthday string -> 'YYYY-MM-DD'. ValueError on anything else.

    Accepted: YYYY-MM-DD (also . / or no separator, 8 digits) and the
    6-digit YYMMDD people actually type ("961002"), with or without
    separators. A 2-digit year resolves to the MOST RECENT date not after
    today: 20YY when that is today or earlier, else 19YY. So on 2026-10-02
    '961002' -> 1996-10-02 and '261002' -> 2026-10-02 (born today), while
    '261003' -> 1926-10-03. A full date after today is refused -- a birthday
    has already happened. A year-less date is refused: persons.birthday is
    read as a full ISO date (relmod BIRTHDAY_SOON)."""
    s = str(raw or "").strip()
    today = today or person_today_local()
    m = _BDAY_FULL8_RE.match(s) or (
        _BDAY_FULL_RE.match(s) if not s.isdigit() else None)
    if m:
        try:
            d = datetime.date(int(m.group(1)), int(m.group(2)),
                              int(m.group(3)))
        except ValueError:
            raise ValueError("bad birthday date: %s" % s)
        if d > today:
            raise ValueError("birthday in the future: %s" % d.isoformat())
        return d.isoformat()
    m = (_BDAY_SHORT_RE.match(s) if s.isdigit() else None) or \
        _BDAY_SHORT_SEP_RE.match(s)
    if m:
        yy, mo, dd = int(m.group(1)), int(m.group(2)), int(m.group(3))
        for century in (2000, 1900):
            try:
                d = datetime.date(century + yy, mo, dd)
            except ValueError:
                continue
            if d <= today:
                return d.isoformat()
        raise ValueError("bad birthday date: %s" % s)
    raise ValueError("birthday wants YYYY-MM-DD or YYMMDD: %s" % s)


def _person_norm_relation(raw):
    v = str(raw or "").strip()
    if v.lower() in PERSON_RELATIONS:
        return v.lower()
    if v in _PERSON_RELATION_WORDS:
        return _PERSON_RELATION_WORDS[v]
    raise ValueError("relation wants one of %s: %s"
                     % ("|".join(PERSON_RELATIONS), v))


def person_norm_link_type(raw):
    v = str(raw or "").strip()
    if v.lower() in PERSON_LINK_TYPES:
        return v.lower()
    if v in _PERSON_LINK_WORDS:
        return _PERSON_LINK_WORDS[v]
    raise ValueError("relation_type wants one of %s: %s"
                     % ("|".join(PERSON_LINK_TYPES), v))


def person_norm_field(field, value, today=None):
    """(field, raw) -> stored value (None = clear). ValueError when the field
    is not editable or the value does not parse. Nothing is written here."""
    if field not in PERSON_SET_FIELDS:
        raise ValueError("field wants one of %s: %s"
                         % ("|".join(PERSON_SET_FIELDS), field))
    v = str(value if value is not None else "").strip()
    if v == "":
        return None
    if field == "birthday":
        return parse_birthday(v, today=today)
    if field == "relation":
        return _person_norm_relation(v)
    if field == "gender":
        g = _PERSON_GENDER_WORDS.get(v.lower(), v.upper())
        if g not in ("M", "F", "X"):
            raise ValueError("gender wants M|F|X: %s" % v)
        return g
    return v


def person_set(conn, pid, changes, today=None):
    """Apply {field: raw_value} to one person, all-or-nothing: every value is
    parsed before the single UPDATE. Returns [(field, old, new)] in the order
    given, or None when the person does not exist."""
    row = conn.execute("SELECT id FROM persons WHERE id=?;",
                       (int(pid),)).fetchone()
    if row is None:
        return None
    parsed = [(f, person_norm_field(f, v, today=today)) for f, v in changes]
    cols = [f for f, _ in parsed]
    old = conn.execute("SELECT %s FROM persons WHERE id=?;" % ", ".join(cols),
                       (int(pid),)).fetchone()
    conn.execute("UPDATE persons SET %s WHERE id=?;"
                 % ", ".join("%s=?" % c for c in cols),
                 [v for _, v in parsed] + [int(pid)])
    conn.commit()
    return [(f, old[i], v) for i, (f, v) in enumerate(parsed)]


def _person_pair(a, b, rtype):
    """Stored orientation of 'a is <rtype> of b' under person_a < person_b."""
    a, b = int(a), int(b)
    if a < b:
        return a, b, rtype
    return b, a, PERSON_LINK_TYPES[rtype]


def person_link(conn, a, b, rtype, note=None, replace=False):
    """Record 'a is <rtype> of b'. Returns (status, rel_id, prior_rows):
      linked    -- new row
      exists    -- the same link is already on file (nothing written)
      upgraded  -- the pair only had 'acquaintance' rows (group auto-links);
                   that row now carries the specific type
      replaced  -- --replace: the pair's other links were swapped for this one
      conflict  -- the pair already has a different specific link (nothing
                   written; prior_rows lists it)
    ValueError on self-link / unknown type."""
    rtype = person_norm_link_type(rtype)
    if int(a) == int(b):
        raise ValueError("a person cannot be linked to themself")
    pa, pb, ptype = _person_pair(a, b, rtype)
    note = _txt(note)
    rows = conn.execute(
        "SELECT id, relation_type, note FROM persons_relations "
        "WHERE person_a=? AND person_b=? ORDER BY id;", (pa, pb)).fetchall()
    same = [r for r in rows if r[1] == ptype]
    if same:
        if note and same[0][2] != note:
            conn.execute("UPDATE persons_relations SET note=? WHERE id=?;",
                         (note, same[0][0]))
            conn.commit()
        return "exists", same[0][0], rows
    others = [r for r in rows if r[1] != "acquaintance"]
    if others and not replace:
        return "conflict", None, rows
    if rows and (replace or not others):
        keep = rows[0]
        merged = note or keep[2]
        conn.execute("UPDATE persons_relations SET relation_type=?, note=? "
                     "WHERE id=?;", (ptype, merged, keep[0]))
        conn.execute("DELETE FROM persons_relations WHERE person_a=? AND "
                     "person_b=? AND id<>?;", (pa, pb, keep[0]))
        conn.commit()
        return ("replaced" if others else "upgraded"), keep[0], rows
    cur = conn.execute(
        "INSERT INTO persons_relations (person_a, person_b, relation_type, "
        "note) VALUES (?,?,?,?);", (pa, pb, ptype, note))
    conn.commit()
    return "linked", cur.lastrowid, rows


def person_unlink(conn, a, b, rtype=None):
    """Remove the pair's links (only the ones of rtype, read as 'a is <rtype>
    of b', when given). Returns the number of rows removed; 0 is a no-op."""
    a, b = int(a), int(b)
    pa, pb = min(a, b), max(a, b)
    sql = "DELETE FROM persons_relations WHERE person_a=? AND person_b=?"
    params = [pa, pb]
    if rtype is not None:
        _x, _y, ptype = _person_pair(a, b, person_norm_link_type(rtype))
        sql += " AND relation_type=?"
        params.append(ptype)
    n = conn.execute(sql + ";", params).rowcount
    conn.commit()
    return n


def person_relations(conn, pid):
    """[(rel_id, other_id, other_name, role, note)] -- role is what the OTHER
    person is to pid ('child' on a parent's list). Specific links first,
    then group-auto acquaintances, each by other name."""
    pid = int(pid)
    out = []
    for rid, pa, pb, rtype, note, oid, oname in conn.execute(
            "SELECT r.id, r.person_a, r.person_b, r.relation_type, r.note, "
            "o.id, o.name FROM persons_relations r JOIN persons o "
            "ON o.id = CASE WHEN r.person_a=? THEN r.person_b "
            "ELSE r.person_a END "
            "WHERE r.person_a=? OR r.person_b=?;", (pid, pid, pid)):
        # row: person_a is rtype of person_b
        role = rtype if pb == pid else PERSON_LINK_TYPES.get(rtype, rtype)
        out.append((rid, oid, oname, role, note))
    out.sort(key=lambda r: (r[3] == "acquaintance", r[2], r[0]))
    return out


def person_child_relation_hint(conn, child_id, parent_ids):
    """The relation to the user a child inherits from the parents on file:
    any parent 'family' -> family, else (parents known) -> unrelated. A
    friend's child is someone the user knows through the friend, not a
    friend (owner 2026-10-02: 'unrelated', not acquaintance). None when no
    parent carries a relation."""
    rels = [r[0] for r in conn.execute(
        "SELECT relation FROM persons WHERE id IN (%s);"
        % ",".join("?" * len(parent_ids)), [int(p) for p in parent_ids])
        if r[0]]
    if not rels:
        return None
    return "family" if "family" in rels else "unrelated"


def person_hops(conn, pid):
    """How far pid is from the user, read from the link graph -- never
    stored (an Erdos-number style distance, derived on every read).

    distance 1 = a person whose relation is set and is not 'unrelated'
    (NULL = not asked yet, so not a root). distance n+1 = linked through
    persons_relations (undirected) to a distance-n person; shortest path.
    Group-auto 'acquaintance' rows are real co-membership and count as
    edges, but among equally short paths the one with fewer acquaintance
    edges wins (a child link beats a shared group), then the one rooted in
    the closer relation (PERSON_RELATIONS order: a close friend's daughter
    reads through the close friend, not the other parent), then lower ids.

    Returns (n, path) with path = [(id, name), ...] from the root to pid
    (path == [pid] at distance 1), or (None, []) when no path exists."""
    pid = int(pid)
    names, roots = {}, []
    rank = dict((r, k) for k, r in enumerate(PERSON_RELATIONS))
    for i, name, rel in conn.execute(
            "SELECT id, name, relation FROM persons;"):
        names[i] = name
        if rel and rel != "unrelated":
            roots.append((rank.get(rel, len(rank)), i))
    if pid not in names:
        return None, []
    adj = {}
    for a, b, rtype in conn.execute(
            "SELECT person_a, person_b, relation_type "
            "FROM persons_relations;"):
        w = 1 if rtype == "acquaintance" else 0
        for x, y in ((a, b), (b, a)):
            nb = adj.setdefault(x, {})
            nb[y] = min(nb.get(y, 1), w)
    # Dijkstra on (hops, acquaintance edges, root rank, path ids): plain BFS
    # order with a deterministic tie-break; ~200 people, a few hundred edges.
    best = {}
    heap = [(1, 0, k, (r,)) for k, r in roots]
    heapq.heapify(heap)
    while heap:
        hops, weak, k, path = heapq.heappop(heap)
        node = path[-1]
        if node in best:
            continue
        best[node] = (hops, path)
        if node == pid:
            break
        for nb, w in adj.get(node, {}).items():
            if nb not in best:
                heapq.heappush(heap, (hops + 1, weak + w, k, path + (nb,)))
    if pid not in best:
        return None, []
    hops, path = best[pid]
    return hops, [(i, names.get(i, "")) for i in path]


def person_hop_link(conn, pid, via):
    """What pid is to via (the nearest person on its hop path), read from
    via's side: 'child' when pid is via's daughter. The specific link wins
    over a group-auto acquaintance on the same pair."""
    pid, via = int(pid), int(via)
    roles = [r[3] for r in person_relations(conn, via) if r[1] == pid]
    return roles[0] if roles else None


# ══════════════════════════════════════════════════════════════════════════
# DGN-179 verb-delta (spec v2): event-backed appt_find / appt_show render.
# The legacy appointments-table appt_* functions are rewritten over the unified
# event table. Forward references (all_day_instants / ZoneInfo / event_conn /
# MutationResult / event_persons) resolve at call time -- they are defined later
# in the event SDK block at module scope.
# ══════════════════════════════════════════════════════════════════════════

def _render_local_col(start_or_end, schedule_kind, display_tz):
    """M-3/D4 rendering rule for a stored canonical-UTC instant:
      timed   -> local ISO w/ offset  '2026-07-10T07:00:00+09:00'
      all_day -> local bare date      '2026-07-10' (no 'T'; awk omits time)
      NULL    -> '' (caller decides padding).
    The awk consumers (morning-brief / daily-retro) extract HH:MM via
    substr($col, index($col,'T')+1, 5); a 'T'-less all_day value therefore
    prints date-only, byte-identical to the legacy behavior."""
    if start_or_end is None:
        return ""
    local = (datetime.datetime.strptime(start_or_end, "%Y-%m-%dT%H:%M:%SZ")
             .replace(tzinfo=timezone.utc)
             .astimezone(ZoneInfo(display_tz)))
    if schedule_kind == "all_day":
        return local.strftime("%Y-%m-%d")
    return local.isoformat()


def appt_find(date_from, date_to=None, conn=None):
    """D4: appointments and presence rows whose START instant falls in the
    LOCAL date window [date_from, date_to] inclusive (KST scope). Returns
    [(id, col2, title, location, end_col, people, retro_line)]:
      timed   -> col2/end_col = local ISO w/ offset
      all_day -> col2/end_col = local bare date (no 'T')
      people  = comma-and-space-separated participant names ('' if none)
      retro_line = block.retro_line verbatim, or '' if never set
    Bucketing = start-instant in [win_start, win_end) on canonical UTC (legacy
    date(start_at) semantics incl. multi-day showing only on its start day).
    052: kind IN ('appointment','presence') -- the daily-retro/morning-brief
    use case needs the complete schedule surface, not appointments alone; the
    original 4 columns stay in place, end and people are appended.
    settled_outcome='abandoned' excluded (a cancelled meeting must not
    reappear in the brief); done/expired stay visible.
    retro-read-paths: retro_line appended as a further trailing column --
    the only cheap way to answer "기록 안 된 일정 N건" (count rows here whose
    retro_line is '') without a join the caller has to assemble."""
    win_start, win_end = all_day_instants(date_from, date_to or date_from)
    own = conn is None
    if own:
        conn = event_conn()          # asserts user_version==4, actionable error
    try:
        rows = conn.execute(
            "SELECT id, start_at, end_at, schedule_kind, display_tz, "
            "title, location, retro_line "
            "FROM timeblock "
            "WHERE kind IN ('appointment','presence') "
            "AND start_at >= ? AND start_at < ? "
            "AND " + LIVE_BLOCK_SQL + " "
            "ORDER BY start_at;", (win_start, win_end)).fetchall()
        out = []
        for eid, sa, ea, sk, tz, title, loc, retro_line in rows:
            out.append((
                eid, _render_local_col(sa, sk, tz), title, loc,
                _render_local_col(ea, sk, tz), _event_people_names(conn, eid),
                retro_line or ""))
        return out
    finally:
        if own:
            conn.close()


def appt_show_row(conn, eid):
    """M-3: event-backed appt-show. Returns
    (id, title, start_local, end_local, location, purpose, summary,
    retro_line) or None. start_local/end_local rendered per the M-3 rule
    (timed -> local ISO offset, all_day -> local date, NULL -> '').
    retro-read-paths: retro_line appended trailing, '' when never set."""
    row = conn.execute(
        "SELECT id, title, start_at, end_at, schedule_kind, display_tz, "
        "location, purpose, summary, retro_line FROM timeblock "
        "WHERE id=? AND kind='appointment';", (int(eid),)).fetchone()
    if row is None:
        return None
    eid_, title, sa, ea, sk, tz, loc, purpose, summary, retro_line = row
    return (eid_, title,
            _render_local_col(sa, sk, tz), _render_local_col(ea, sk, tz),
            loc, purpose, summary, retro_line or "")


# ══════════════════════════════════════════════════════════════════════════
# DGN-579 B1: event_day -- THE day-view query (D2 determinism). Membership
# is a WHERE clause, never agent discretion: every DATED event touching the
# local date shows, INCLUDING kind='presence'. This is the primitive's
# visibility contract -- the forcing point that keeps reclassified presence
# rows reachable. Rich briefing rendering (cap 5/day, +N more) is kit-owned
# and NOT built here; this returns the raw partitioned rows.
# ══════════════════════════════════════════════════════════════════════════

def event_day(date, tz_name="Asia/Seoul", conn=None):
    """Return every dated event that touches local `date`, partitioned:
      {'band':     [presence rows]  -- background band (kind='presence'),
       'anchored': [anchored rows]  -- bars (movement rows marked block_class),
       'due':      [due rows]}      -- compact markers.
    floating (untimed backlog) is NEVER in the day view (backlog surface).

    Row tuple = (id, ulid, kind, title, start_local, end_local, schedule_kind,
    time_mode, block_class, place_name, status, retro_line). Local columns
    rendered per the M-3 rule. Membership: settled_outcome != 'abandoned' AND
    the event's [start, eff_end) intersects the local day window [ws, we) --
    the same half-open instant math the occupancy predicate uses (uniform,
    exact). retro-read-paths: retro_line appended trailing ('' if never set)."""
    ws, we = all_day_instants(date, tz_name=tz_name)
    own = conn is None
    if own:
        conn = event_conn()
    try:
        rows = conn.execute(
            "SELECT e.id, e.ulid, e.kind, e.title, e.start_at, e.end_at, "
            "e.schedule_kind, e.time_mode, e.block_class, e.display_tz, "
            "e.status, p.name, e.retro_line FROM timeblock e "
            "LEFT JOIN place p ON p.id = e.place_id "
            "WHERE " + LIVE_BLOCK_SQL + " "
            "AND e.start_at IS NOT NULL "
            "AND e.start_at < ? AND " + EFF_END_SQL + " > ? "
            "ORDER BY e.start_at;", (we, ws)).fetchall()
        out = {"band": [], "anchored": [], "due": []}
        for (eid, ulid, kind, title, sa, ea, sk, tm, bc, tz, st,
             pname, retro_line) in rows:
            item = (eid, ulid, kind, title,
                    _render_local_col(sa, sk, tz), _render_local_col(ea, sk, tz),
                    sk, tm, bc, pname, st, retro_line or "")
            if kind == "presence":
                out["band"].append(item)
            elif tm == "anchored":
                out["anchored"].append(item)
            elif tm == "due":
                out["due"].append(item)
            # any other shape (should not occur for a dated row) is dropped
            # from the day view by construction -- floating has no start.
        return out
    finally:
        if own:
            conn.close()


# ── 신체 스탯 / 목표 칼로리 모델 (card.py에서 이전, 공식 동일) ──
# Generic illustrative defaults only (NOT any real person's measurements).
# The owner's actual stats live in kit_life.db (config table) and override these.
DEFAULT_STATS = {
    'weight_kg': 70, 'height_cm': 170, 'fat_mass_kg': 15, 'lean_mass_kg': 55,
    'avg_steps': 8000, 'deficit_kcal': 300, 'other_neat_kcal': 150,
    'protein_g': 120, 'fat_ratio': 0.25,
}

# 2.20.0 -- the merge above is the quietest thing this engine does. On
# 2026-09-11 23:42 a raw-SQL purge deleted 13 body-stat rows from `config`;
# every consumer kept rendering confident numbers off DEFAULT_STATS and the
# owner's recommended intake was 175 kcal wrong for a day. Nothing anywhere
# said a word -- a human noticed the protein figure looked odd.
#
# The load contract keeps its VALUE keys byte-identical (a fresh instance that
# never had measurements must keep working). What it gains is one reserved,
# non-value key naming which DEFAULT_STATS keys were served from CODE rather
# than from storage. Reserved keys are underscore-prefixed so no consumer can
# mistake one for a measurement, and the tuple is EMPTY (not absent) on a
# fully-configured kit, so a caller can read it unconditionally.
BODY_STATS_FALLBACK_KEY = '_defaults_used'


def _merge_body_stats(stored):
    """{**DEFAULT_STATS, **stored} + the fallback marker. THE one merge; every
    store's load()/update() returns through here so the marker cannot exist on
    one backend and not the other."""
    merged = {**DEFAULT_STATS, **stored}
    merged[BODY_STATS_FALLBACK_KEY] = tuple(
        k for k in sorted(DEFAULT_STATS) if k not in stored)
    return merged


def body_stats_defaults_used(stats=None):
    """Which DEFAULT_STATS keys the given (or current) stats dict is serving
    from code instead of from storage. Empty tuple = every number is the
    owner's own."""
    if stats is None:
        stats = load_body_stats()
    return tuple(stats.get(BODY_STATS_FALLBACK_KEY) or ())


def body_stats_fallback_line(stats=None):
    """THE rendering of "these are a stranger's numbers", or None when there
    is nothing to say.

    None -- not an empty string -- on the happy path is deliberate: every
    surface below prints this only when it is non-None, so a fully-configured
    kit's output stays byte-identical to its 2.19.0 self and no consumer's
    parser moves. The keys ride in the line because "which number is fake"
    is the question the owner actually has."""
    keys = body_stats_defaults_used(stats)
    if not keys:
        return None
    return ("BODY_STATS_DEFAULTS %d %s -- 저장된 신체 수치가 없어 코드 기본값"
            "(실존 인물 아님)으로 계산했습니다" % (len(keys), ','.join(keys)))


def load_body_stats():
    """신체 스탯 전체 dict(DEFAULT_STATS 위에 저장값 머지).

    v2: 진실의 원천을 body_stats.json 직접 읽기에서 _CONFIG_STORE(SQL)
    경유로 옮겼다. card.py/compute_targets 등 모든 호출부가 SQL truth를 읽는다.
    _CONFIG_STORE는 이 함수보다 아래에서 정의되지만 파이썬은 전역을 호출 시점에
    해석하므로 순서 문제 없다(모듈 최초 import 후 첫 호출 시 이미 바인딩됨).

    2.20.0: 반환 dict 에 BODY_STATS_FALLBACK_KEY 예약키가 하나 더 붙는다
    (값 키는 무변경). 코드 기본값으로 대체된 키 목록 -- body_stats_defaults_used()
    / body_stats_fallback_line() 경유로 읽는다."""
    return _CONFIG_STORE.load()


# ── 설정 저장소 추상화 ────────────────────────────
# 저장 백엔드(JSON/sqlite)를 호출부로부터 은닉하는 얇은 인터페이스.
# 지금은 JsonConfigStore(body_stats.json 어댑터)가 1차 백엔드.
# 나중에 SqliteConfigStore로 교체해도 set_stats/get_config 호출부는 무변경.
import tempfile  # 원자 쓰기(temp write -> os.replace)용


class ConfigStore:
    """단일 설정값 저장소 인터페이스. body_stats 같은 key/value dict 계약."""

    def load(self):
        """전체 설정 dict 반환(load_body_stats와 같은 계약: DEFAULT_STATS 머지)."""
        raise NotImplementedError

    def get(self, key, default=None):
        """단일 키 조회."""
        raise NotImplementedError

    def update(self, fields):
        """주어진 필드만 원자적으로 병합 갱신. 갱신된 전체 dict 반환."""
        raise NotImplementedError


class JsonConfigStore(ConfigStore):
    """body_stats.json 어댑터. 원자 쓰기(temp write -> os.replace)로 동시쓰기 보호.

    같은 디렉터리에 임시파일을 만들고 os.replace로 교체한다 — 같은 파일시스템
    내 rename은 POSIX에서 원자적이라 부분기록/동시쓰기 깨짐을 막는다.
    load() 계약은 기존 load_body_stats()와 동일(DEFAULT_STATS 위에 파일 머지)."""

    def __init__(self, path=None):
        self.path = path or BODY_STATS_PATH

    def _read_raw(self):
        try:
            with open(self.path, encoding='utf-8') as f:
                return json.load(f)
        except (FileNotFoundError, json.JSONDecodeError):
            return {}

    def load(self):
        return _merge_body_stats(self._read_raw())

    def get(self, key, default=None):
        raw = self._read_raw()
        if key in raw:
            return raw[key]
        return DEFAULT_STATS.get(key, default)

    def update(self, fields):
        """주어진 필드만 병합 후 원자 교체(temp write -> os.replace). 전체 dict 반환.

        Locking: the file SWAP is atomic (os.replace), so no reader ever sees a
        torn file. The read-modify-write is NOT itself locked, so two concurrent
        writers can lost-update (last os.replace wins). This is acceptable here:
        the single agent process is the only writer. If multi-writer access is
        ever needed, move config to SqliteConfigStore (single-writer WAL) instead
        of adding file locks."""
        raw = self._read_raw()
        raw.update(fields)
        raw['updated'] = datetime.date.today().isoformat()
        self._atomic_write(raw)
        return _merge_body_stats(raw)

    def _atomic_write(self, data):
        d = os.path.dirname(os.path.abspath(self.path))
        fd, tmp = tempfile.mkstemp(prefix='.body_stats.', suffix='.tmp', dir=d)
        try:
            with os.fdopen(fd, 'w', encoding='utf-8') as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
                f.write('\n')
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp, self.path)
        except BaseException:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise


class SqliteConfigStore(ConfigStore):
    """config 테이블(key/value TEXT) 백엔드. v2에서 신체 스탯의 canonical.

    config.value 는 TEXT 이므로 load()는 DEFAULT_STATS 의 숫자 키를 명시적으로
    float 캐스팅해 JsonConfigStore(파일 JSON, 숫자는 그대로 int/float)와 값 계약을
    맞춘다. goal_mode/updated 같은 비숫자 키는 문자열 그대로 둔다.
    load() 계약: {**DEFAULT_STATS, **rows} (파일판과 동일하게 DEFAULT 위에 저장값)."""

    # 숫자로 캐스팅할 키 집합(DEFAULT_STATS 숫자 키 + 파일에만 있던 측정 숫자 키).
    # goal_mode/updated 는 여기 없으니 문자열 유지.
    _NUMERIC_KEYS = {
        'weight_kg', 'height_cm', 'skeletal_muscle_kg', 'fat_mass_kg',
        'lean_mass_kg', 'avg_steps', 'deficit_kcal', 'other_neat_kcal',
        'protein_g', 'fat_ratio', 'surplus_kcal',
    }

    def _cast(self, key, raw):
        """저장된 TEXT 값을 계약형으로 복원. 숫자 키면 float, 아니면 원문."""
        if key in self._NUMERIC_KEYS:
            try:
                return float(raw)
            except (TypeError, ValueError):
                return DEFAULT_STATS.get(key, raw)
        return raw

    def _read_rows(self, conn=None):
        own = conn is None
        if own:
            conn = get_conn()
        try:
            rows = conn.execute("SELECT key, value FROM config;").fetchall()
        finally:
            if own:
                conn.close()
        out = {}
        for k, v in rows:
            if k in self._NUMERIC_KEYS and k in DEFAULT_STATS:
                # An UNPARSEABLE stored numeric row is served as the code
                # default by _cast -- so it is the same silence as an absent
                # row, and omitting it here is VALUE-identical (the merge
                # re-supplies exactly what _cast returned). What it buys is an
                # honest fallback marker: "stored but garbage" no longer
                # masquerades as "the owner's own number".
                try:
                    out[k] = float(v)
                except (TypeError, ValueError):
                    continue
                continue
            out[k] = self._cast(k, v)
        return out

    def load(self):
        return _merge_body_stats(self._read_rows())

    def get(self, key, default=None):
        conn = get_conn()
        try:
            row = conn.execute(
                "SELECT value FROM config WHERE key=? LIMIT 1;", (key,)).fetchone()
        finally:
            conn.close()
        if row is not None:
            return self._cast(key, row[0])
        return DEFAULT_STATS.get(key, default)

    def update(self, fields):
        """주어진 필드만 config에 upsert(값은 str로 저장). 'updated' 자동 갱신.
        갱신된 전체 dict 반환(load 계약)."""
        merged = dict(fields)
        merged['updated'] = datetime.date.today().isoformat()
        conn = get_conn()
        try:
            for k, v in merged.items():
                conn.execute(
                    "INSERT INTO config (key, value) VALUES (?, ?) "
                    "ON CONFLICT(key) DO UPDATE SET "
                    "value=excluded.value, "
                    "updated_at=datetime('now','localtime');",
                    (k, str(v)))
            conn.commit()
        finally:
            conn.close()
        return self.load()


# 기본 설정 저장소(현재 백엔드). v2 클린 컷오버: SQL(config 테이블)이 canonical.
# 교체 시 이 한 줄만 바꾸면 호출부 무변경(load_body_stats/get_config/set_stats 모두 경유).
_CONFIG_STORE = SqliteConfigStore()


# ── 설정값 쓰기/읽기 API ──────────────────────────
def set_stats(**fields):
    """body_stats 측정/설정 필드를 원자적으로 갱신. 갱신된 전체 dict 반환.

    load_body_stats()와 같은 dict 계약(DEFAULT_STATS 머지)을 유지한다.
    'updated' 필드는 자동 갱신된다(오늘 날짜). 저장 백엔드는 _CONFIG_STORE 경유."""
    if not fields:
        return _CONFIG_STORE.load()
    return _CONFIG_STORE.update(dict(fields))


def set_config(key, value):
    """단일 설정값 하나를 원자적으로 갱신(set_stats의 단일키 편의 래퍼)."""
    return _CONFIG_STORE.update({key: value})


def get_config(key, default=None):
    """설정값 조회. 현재 백엔드(JSON, body_stats) 경유.

    나중 SqliteConfigStore로 교체하면 config 테이블에서 읽도록 바뀌지만
    호출부는 동일하게 get_config(key)만 부른다."""
    return _CONFIG_STORE.get(key, default)


# ── 측정값 시계열 API ─────────────────────────────
def log_metric(date, metric, value, note=None, conn=None):
    """metric_log에 측정값 1건 upsert(하루 한 측정). (date, metric)이 같으면 갱신.

    weight_kg/skeletal_muscle_kg/fat_mass_kg 같은 측정값의 일별 추세 기록용.
    반환: 해당 행 id."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        # v19 one-writer: metric_log = health domain (owner warg). owning_agent
        # is set on INSERT; on conflict the existing row's owner is kept (always
        # warg here -- health-domain single writer), so it is not in the SET.
        conn.execute(
            "INSERT INTO metric_log (date, metric, value, note, owning_agent) "
            "VALUES (?,?,?,?,?) "
            "ON CONFLICT(date, metric) DO UPDATE SET "
            "value=excluded.value, note=excluded.note, "
            "created_at=datetime('now','localtime');",
            (date, metric, _num(value), _txt(note), _health_agent_write(conn)))
        conn.commit()
        row = conn.execute(
            "SELECT id FROM metric_log WHERE date=? AND metric=?;",
            (date, metric)).fetchone()
        return row[0] if row else None
    finally:
        if own:
            conn.close()


def get_series(metric, date_from=None, date_to=None, conn=None):
    """한 metric의 시계열 조회. [{date, value}] 리스트(날짜 오름차순).

    date_from/date_to(YYYY-MM-DD)로 기간 한정(둘 다 포함). 미지정이면 전체."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        sql = "SELECT date, value FROM metric_log WHERE metric=?"
        params = [metric]
        if date_from is not None:
            sql += " AND date >= ?"
            params.append(date_from)
        if date_to is not None:
            sql += " AND date <= ?"
            params.append(date_to)
        sql += " ORDER BY date;"
        rows = conn.execute(sql, params).fetchall()
        return [{'date': d, 'value': v} for d, v in rows]
    finally:
        if own:
            conn.close()


def latest_metric(metric, conn=None):
    """한 metric의 최신 측정값. {date, value} (없으면 None).

    최신 기준은 date 내림차순(가장 최근 날짜), 동일 날짜는 id 내림차순."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        row = conn.execute(
            "SELECT date, value FROM metric_log WHERE metric=? "
            "ORDER BY date DESC, id DESC LIMIT 1;", (metric,)).fetchone()
        return {'date': row[0], 'value': row[1]} if row else None
    finally:
        if own:
            conn.close()


# ── 추세 표시 primitive (킷 공용) ───────────────────────────────────────
# 오너 한 줄(2026-08-13): "lifekit 시계열 데이터는 기록할 때 추세를 보여줘라.
# 주기는 데이터마다 다름." 핵심 통찰: 보여주는 빈도는 기록 빈도와 반비례한다
# -- 자주 기록하는 지표(운동/식단)를 매번 보여주면 소음이라 집계 시점에만,
# 드물게 기록하는 지표(체중)는 기록 한 번이 곧 추세의 순간이라 매 기록마다.
# Full design: the 2026-08-13 lifekit time-series trend spec.
#
# 2026-09-16 실측: 스펙은 metric_log 하나를 값의 집으로 전제했지만 037/041/
# 046 이후 값의 집이 metric_log 와 measure 둘로 갈려 있다 -- weight_kg 는
# metric_def 에 아직 없어(041 이 body_fat_pct 만 투영하고 나머지를 미룬 자리)
# measure 로 못 옮긴다(measure.metric 이 metric_def(token) 을 FK 로 문다).
# 그래서 이 레지스트리는 저장소 통합을 하지 않고 "이 지표는 어디서 읽는가"를
# SOURCE 필드로 명시한다 -- 지금의 분열을 숨기지 않고 데이터로 드러낸다.
# 나중에 그 지표가 measure 로 투영되면 이 표의 그 한 줄만 바뀐다.
#
#   cadence_class 'weekly-point'  드물게 기록 -> 기록할 때마다 보여준다
#                                 (체중/체성분류)
#   cadence_class 'daily-multi'   자주 기록 -> 집계 시점에만 보여준다
#                                 (칼로리 등). 이번 컷은 primitive 만 만들고
#                                 "집계 시점에만 부른다"는 호출부(브리핑/
#                                 회고)의 몫 -- 여기서는 강제하지 않는다.
#   cadence_class 'weekly-flow'   흐름형(지출/자산). 시드 없음(증거 없음).
#
#   source 'metric_log'   041 투영 전 구식 값의 집(weight_kg 등)
#   source 'measure'      037 판정층 이후의 정본 값의 집(basis='actual',
#                         valid_until 유효한 행만)
#   source 'agg:<table>'  이벤트 테이블에서 파생하는 집계(운동 볼륨, 식단
#                         kcal 등). 이번 컷은 구현하지 않는다 -- 호출되면
#                         지어낸 숫자 대신 not_implemented=True 를 정직하게
#                         반환한다.
#
# 시드는 증거 있는 다섯 지표뿐(확정된 창: 체중·체성분 8~12주 -> 기본
# 12주=84일, kcal_intake 는 최근 7일). 나머지는 아직 증거 없는 행이라
# 넣지 않는다.
TREND_REGISTRY = {
    'weight_kg': {
        'source': 'metric_log', 'cadence_class': 'weekly-point',
        'window_days': 84, 'unit_hint': 'kg', 'label_ko': '체중',
        'decimals': 1,
    },
    'skeletal_muscle_kg': {
        'source': 'metric_log', 'cadence_class': 'weekly-point',
        'window_days': 84, 'unit_hint': 'kg', 'label_ko': '골격근량',
        'decimals': 1,
    },
    'fat_mass_kg': {
        'source': 'metric_log', 'cadence_class': 'weekly-point',
        'window_days': 84, 'unit_hint': 'kg', 'label_ko': '체지방량',
        'decimals': 1,
    },
    'body_fat_pct': {
        'source': 'measure', 'cadence_class': 'weekly-point',
        'window_days': 84, 'unit_hint': '%', 'label_ko': '체지방률',
        'decimals': 1,
    },
    'kcal_intake': {
        'source': 'measure', 'cadence_class': 'daily-multi',
        'window_days': 7, 'unit_hint': 'kcal', 'label_ko': '섭취 칼로리',
        'decimals': 0,
    },
}


def _trend_metric_log_points(conn, metric, date_from, date_to):
    """metric_log 소스의 일별 시계열 [(date, value), ...] (날짜 오름차순).

    UNIQUE(date, metric) 제약이 이미 하루 한 행을 보장하므로(같은 날 중복
    기록 자체가 스키마상 불가능) dedupe가 필요 없다 -- get_series를 그대로
    재사용."""
    series = get_series(metric, date_from=date_from, date_to=date_to, conn=conn)
    return [(row['date'], row['value']) for row in series]


def _trend_measure_points(conn, metric, date_from, date_to):
    """measure 소스의 일별 시계열 [(date, value), ...] (날짜 오름차순).

    037 판정층과 같은 규율: basis='actual' 만(계획은 추세가 아니다) +
    valid_until 이 아직 유효한 행만(승계된 값은 죽은 값이다). 같은 날 여러
    행이면 그 날의 마지막 값을 쓴다 -- observed_at 오름차순으로 훑어 나중에
    덮어쓴 값이 남는 것으로 구현한다(date-only 관측시각은 그 날 00:00으로
    취급되어 항상 먼저 온다: 037/038 grade-floor와 같은 방향)."""
    rows = conn.execute(
        "SELECT substr(observed_at,1,10) AS day, value "
        "FROM measure "
        "WHERE metric=? AND basis='actual' "
        "  AND (valid_until IS NULL OR valid_until > ?) "
        "  AND substr(observed_at,1,10) >= ? "
        "  AND substr(observed_at,1,10) <= ? "
        "ORDER BY observed_at, id;",
        (metric, now_utc(), date_from, date_to)).fetchall()
    by_day = {}
    for day, value in rows:
        by_day[day] = value      # 나중 행이 이긴다 = 그 날의 마지막 값
    return sorted(by_day.items())


def _trend_points(conn, source, metric, date_from, date_to):
    if source == 'metric_log':
        return _trend_metric_log_points(conn, metric, date_from, date_to)
    if source == 'measure':
        return _trend_measure_points(conn, metric, date_from, date_to)
    raise ValueError('trend: unreadable source %r' % source)


def _trend_direction(delta):
    """오르내림만 말하는 화살표 방향 -- 좋다/나쁘다는 말하지 않는다(오너
    규칙: 이 primitive는 목표를 보지 않는다. 체중이 늘어난 게 좋은지 나쁜지는
    목표가 정한다)."""
    if delta > 0:
        return 'up'
    if delta < 0:
        return 'down'
    return 'flat'


def _trend_staleness(conn, metric, last_date):
    """metric_freshness 에 그 지표의 cadence 가 선언돼 있으면 마지막 기록의
    나이로 stale 여부(True/False)를 판정하고, 선언이 없으면 None(침묵) --
    임의 기준을 발명하지 않는다(freshness-report/cli_freshness_touch 와 같은
    fail-closed 규율: 있으면 읽고, 없으면 조용하다)."""
    row = conn.execute(
        "SELECT stale_after_hours FROM metric_freshness WHERE metric=?;",
        (metric,)).fetchone()
    if row is None:
        return None
    last_dt = datetime.datetime.strptime(last_date, '%Y-%m-%d')
    now_dt = datetime.datetime.now(timezone.utc).replace(tzinfo=None)
    age_h = (now_dt - last_dt).total_seconds() / 3600.0
    return age_h > float(row[0])


def compute_trend(conn, metric, window_days=None, as_of=None):
    """추세 primitive의 핵심 계산. metric이 TREND_REGISTRY에 없으면 KeyError.

    반환 dict(--json이 그대로 내보내는 모양): metric/source/cadence_class/
    unit_hint/label_ko/decimals/window_days/point_count/latest_date/
    latest_value/prev_value/prev_delta/window_start_value/window_delta/
    direction/last_recorded_date/stale/not_implemented.

    정직성 규칙(이 컷의 핵심, 지어내지 않는다):
      source가 'agg:<table>' -- not_implemented=True, 숫자 없음.
      점 0개 -- point_count=0, 나머지 값 필드 전부 None.
      점 1개 -- latest만 채워지고 delta 계열은 None("추세는 아직").
      stale -- metric_freshness에 선언이 없으면 None(침묵), 있으면 True/
      False.
    """
    entry = TREND_REGISTRY[metric]
    days = int(window_days) if window_days is not None else entry['window_days']
    as_of = as_of or datetime.date.today().isoformat()
    date_from = (datetime.date.fromisoformat(as_of)
                 - timedelta(days=days)).isoformat()

    result = {
        'metric': metric, 'source': entry['source'],
        'cadence_class': entry['cadence_class'],
        'unit_hint': entry['unit_hint'], 'label_ko': entry['label_ko'],
        'decimals': entry['decimals'], 'window_days': days,
        'point_count': 0,
        'latest_date': None, 'latest_value': None,
        'prev_value': None, 'prev_delta': None,
        'window_start_value': None, 'window_delta': None,
        'direction': None, 'last_recorded_date': None, 'stale': None,
        'not_implemented': entry['source'].startswith('agg:'),
    }
    if result['not_implemented']:
        return result

    points = _trend_points(conn, entry['source'], metric, date_from, as_of)
    result['point_count'] = len(points)
    if not points:
        return result

    last_date, last_value = points[-1]
    result['latest_date'] = last_date
    result['latest_value'] = last_value
    result['last_recorded_date'] = last_date
    result['window_start_value'] = points[0][1]
    result['stale'] = _trend_staleness(conn, metric, last_date)
    if len(points) >= 2:
        prev_date, prev_value = points[-2]
        result['prev_value'] = prev_value
        # round(9): 부동소수 뺄셈 잔여 노이즈(83.3-82.9=0.399999...)를 지우되
        # 지표가 실제로 쓰는 소수 자리(decimals)보다 훨씬 세밀하게 남겨
        # --json 소비자가 어떤 decimals 로도 다시 자를 수 있게 한다.
        result['prev_delta'] = round(last_value - prev_value, 9)
        result['window_delta'] = round(last_value - points[0][1], 9)
        result['direction'] = _trend_direction(result['prev_delta'])
    return result


_TREND_ARROW = {'up': '↑', 'down': '↓', 'flat': '→'}


def _trend_md(date_iso):
    """'YYYY-MM-DD' -> 'M/D' (마지막 기록 날짜를 짧게 대면하는 형)."""
    _, m, d = date_iso.split('-')
    return '%d/%d' % (int(m), int(d))


def _trend_window_label(days):
    """84 -> '12주', 7 -> '7일' -- 7의 배수는 주 단위로 읽는다(오너가 확정한
    창구가 원래 주 단위 -- 8~12주 -- 이기 때문)."""
    if days % 7 == 0:
        return '%d주' % (days // 7)
    return '%d일' % days


def render_trend_text(trend):
    """compute_trend()의 결과를 스펙의 한 줄 형태로 렌더.

    "82.9kg ↓0.4 (직전 기록 대비) · 6주 -1.1kg" 형태 -- 최신값 + 방향 +
    직전 대비 델타 + 창 전체 델타. 값의 의미는 모른다: 오르내림만 말하고
    좋다/나쁘다는 말하지 않는다.

    ** 스펙 원문의 "(지난주 대비)" 대신 "(직전 기록 대비)"를 쓴다 **:
    weekly-point 지표라도 연속된 두 기록 사이 간격이 정확히 7일이라는 보장이
    없고, "지난주"라는 시간 표현은 그 정확도를 지어내는 것이다(이 primitive의
    정직성 규칙과 충돌한다).

    정직성 규칙(이 컷의 핵심):
      점 0개거나 소스가 미구현(agg:*)이면 None을 돌린다 -- 렌더 자체를 하지
      않아 호출부가 '없음'을 알 수 있게 한다.
      점 1개면 델타 없이 "82.9kg (기록 1회 -- 추세는 아직)".
      마지막 기록이 그 지표의 선언된 주기보다 오래됐으면(stale=True) "· 마지막
      기록 M/D"를 덧붙인다. stale이 None(주기 미선언)이면 아무 말도 안 한다."""
    if trend.get('not_implemented') or trend['point_count'] == 0:
        return None

    dec = trend['decimals']
    unit = trend['unit_hint']
    latest_str = '%.*f%s' % (dec, trend['latest_value'], unit)
    stale_note = ''
    if trend.get('stale'):
        stale_note = ' · 마지막 기록 %s' % _trend_md(trend['last_recorded_date'])

    if trend['point_count'] == 1:
        return '%s (기록 1회 -- 추세는 아직)%s' % (latest_str, stale_note)

    arrow = _TREND_ARROW[trend['direction']]
    window_label = _trend_window_label(trend['window_days'])
    return ('%s %s%.*f (직전 기록 대비) · %s %+.*f%s%s'
            % (latest_str, arrow, dec, abs(trend['prev_delta']),
               window_label, dec, trend['window_delta'], unit, stale_note))


def compute_targets(stats, *, exercise_kcal):
    """리컴프/다이어트 목표 칼로리(사용자 모델). card.py와 값 동일해야 함.

    exercise_kcal is KEYWORD-ONLY with NO DEFAULT (ticket 2026-09-02 D3).  A
    default of 0 silently meant "rest day": cli_body_state kept a hardcoded 0
    after DGN-193 fixed the hook's copy, so the same question got two answers
    on a training day.  This function only folds in the burn it is handed;
    WHICH burn a date has is decided once, in targets_for_date().  A caller
    that wants the burn-free baseline says exercise_kcal=0 out loud."""
    if stats.get('diet_bmr_method') == 'mifflin':
        # Mifflin et al. 1990, Am J Clin Nutr 51:241-247.
        bmr = (10 * stats['weight_kg'] + 6.25 * stats['height_cm']
               - 5 * float(stats['age'])
               + (5 if stats['sex'] == 'male' else -161))
    else:
        lean = stats.get('lean_mass_kg') or (stats['weight_kg'] - stats.get('fat_mass_kg', 0))
        bmr = 370 + 21.6 * lean                              # Katch-McArdle
    stride_m = stats['height_cm'] / 100 * 0.415              # 보폭 ≈ 키×0.415
    walk_km = stats['avg_steps'] * stride_m / 1000
    walk_kcal = 0.5 * stats['weight_kg'] * walk_km           # 순 보행소모
    neat = walk_kcal + stats.get('other_neat_kcal', 150)     # 활동소모(운동 제외)
    balance = stats['deficit_kcal'] - stats.get('surplus_kcal', 0)
    base_goal = bmr - balance + neat                       # 운동 0일 때 기준
    eff_goal = base_goal + exercise_kcal
    return {
        'bmr': round(bmr), 'neat': round(neat),
        'deficit': round(balance),
        'base_goal': round(base_goal), 'eff_goal': round(eff_goal),
    }


def day_burn_kcal(iso_date, conn=None):
    """THE one place a date's exercise burn is derived -> (burn, missing).

    burn     float, or None when the date has workout rows and not one of
             them carries a recorded kcal (064: NULL = not entered).  None is
             not 0.0 and must not be coerced to it by a caller.
    missing  how many of the date's workout rows have no recorded kcal.
    No workout at all -> (0.0, 0): a known zero.  Partly entered -> the sum of
    what exists, with missing > 0."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        n_rows, n_valued, total = conn.execute(
            "SELECT COUNT(*), COUNT(kcal), SUM(kcal) FROM workouts "
            "WHERE date=?;", (iso_date,)).fetchone()
        if not n_rows:
            return 0.0, 0
        if not n_valued:
            return None, n_rows - n_valued
        return float(total or 0.0), n_rows - n_valued
    finally:
        if own:
            conn.close()


def targets_for_date(iso_date, stats=None, conn=None, burn_override=None):
    """Targets for a date with that date's burn folded in EXACTLY ONCE -- the
    entry point for "the effective goal" (body-state, targets).  Returns the
    compute_targets dict plus burn_kcal / burn_missing / burn_known.

    burn_known=False (trained, nothing entered) is SURFACED ONLY: the target
    is then the rest-day base.  What the product says on such a day is the
    owner's call (ticket 2026-09-02 비고 (2), undecided) -- this function
    neither invents a burn nor withholds the number."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        if stats is None:
            stats = load_body_stats()
        if burn_override is not None:
            burn, missing, known = float(burn_override), 0, True
        else:
            burn, missing = day_burn_kcal(iso_date, conn=conn)
            known = burn is not None
            if burn is None:
                burn = 0.0
        t = compute_targets(stats, exercise_kcal=burn)
        t['burn_kcal'] = burn
        t['burn_missing'] = missing
        t['burn_known'] = known
        return t
    finally:
        if own:
            conn.close()


def compute_macro_goals(total_kcal, stats):
    protein_g = stats.get('protein_g', 120)
    fat_ratio = stats.get('fat_ratio', 0.25)
    fat_g = round(total_kcal * fat_ratio / 9)
    carb_g = round((total_kcal - protein_g * 4 - total_kcal * fat_ratio) / 4)
    return {'protein': protein_g, 'carb': carb_g, 'fat': fat_g}


# ── 카드용: 그날 식단·운동을 읽어 card.py가 쓰는 dict 조각 만들기 ──
# (옛 card.py load_from_life_db를 kit_life.py로 이전. subprocess 대신 직접 DB.)
def load_card_data(iso_date, conn=None):
    """card.py용: 해당 날짜 식단·운동을 읽어 카드 dict 조각 반환."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        a = agg_day(iso_date, conn=conn)
        # 상단 합계(섭취/매크로)는 옛 card가 agg-day의 %.0f 출력을 받아 float()한 값을
        # 그대로 썼다. 카드 표시·바 길이가 한 픽셀도 안 바뀌게 동일 반올림을 재현한다.
        # 당 합계는 agg_day(v_daily_energy 뷰)에 없으므로 meals에서 직접 합산.
        sugar_total = conn.execute(
            "SELECT COALESCE(SUM(sugar),0) FROM " + MEALS_V32 + " WHERE date=?;",
            (iso_date,)).fetchone()[0] or 0
        res = {
            'intake_kcal': {'current': float(_f0(a['intake_kcal']))},
            'protein': {'current': float(_f0(a['protein_g']))},
            'carbs': {'current': float(_f0(a['carb_g'])),
                      'sugar': float(_f0(sugar_total))},
            'fat': {'current': float(_f0(a['fat_g']))},
        }

        # 운동: 항상 workout_find 실행 → workouts 배열 + burn_kcal detail 공용
        wo_rows = workout_find(iso_date, conn=conn)
        # DGN-382: 카드 운동 라벨을 분류 태그(근력/가슴) 대신 세션 표시명으로.
        # session_type 있으면 헬스([code]), 유산소는 헬스(유산소-[subtype]),
        # 그 외 폴백은 기존 형식. 캘린더 제목/DB 기록명과 통일.
        _code_by_id = {}
        try:
            for _wid, _code in conn.execute(
                "SELECT w.id, st.code FROM workouts w "
                "LEFT JOIN session_type st ON st.id = w.session_type_id "
                "WHERE w.date=?;", (iso_date,)).fetchall():
                _code_by_id[_wid] = _code
        except Exception:
            pass

        def _wo_disp(wid, wtype, wname):
            code = _code_by_id.get(wid)
            if code:
                return f"헬스({code})"
            if wtype == '유산소' and wname:
                return wname
            return f"{wtype} ({wname})" if wtype and wname else (wtype or wname or '운동')

        res['workouts'] = [
            {'id': r[0], 'type': '', 'name': _wo_disp(r[0], r[1], r[2]),
             'minutes': r[3], 'kcal': r[4]}
            for r in wo_rows
        ]

        burn = float(_f0(a['burn_kcal']))
        if burn > 0:
            labels = [_wo_disp(r[0], r[1], r[2]) for r in wo_rows]
            detail = ', '.join(labels) if labels else '운동'
            res['burn_kcal'] = {'current': burn, 'detail': detail}

        # 식사 목록 + 매크로
        meals = []
        rows = conn.execute(
            "SELECT meal, name, protein, carb, fat, sugar, kcal "
            "FROM " + MEALS_V32 + " WHERE date=? ORDER BY id;", (iso_date,)).fetchall()
        for meal, name, protein, carb, fat, sugar, kcal in rows:
            meals.append({
                'type': meal or '', 'name': name,
                'protein': float(protein), 'carbs': float(carb),
                'fat': float(fat), 'sugar': float(sugar or 0),
                'kcal': float(kcal or 0),
            })
        res['meals'] = meals
        return res
    finally:
        if own:
            conn.close()


# ═══════════════════════════════════════════════════════════════════════════
# DGN-179 event SDK core -- unified L1 event model (spec v5 LOCK 2026-07-07).
# Ported verbatim from the verified sandbox event_core.py. Three tables
# (event / sub_event / reschedule_requests). English/ASCII only in this block.
#
# Key invariants enforced here:
#   - canonical UTC 'YYYY-MM-DDThh:mm:ssZ' (20 chars) for every instant; a
#     non-canonical write is refused by the app validator AND by table CHECKs.
#   - occupancy predicate targets slot_exclusive=1 AND settled_at IS NULL
#     AND start_at IS NOT NULL (v5.1: physical liveness bit; status cache NOT
#     consulted). schedule_kind='timed' was dropped from the filter so an
#     exclusive all_day day-block physically repels timed events that day;
#     untimed rows fall out via start_at IS NOT NULL.
#   - every slot-touching mutation (INSERT + all UPDATE variants) passes the
#     SAME atomic half-open overlap predicate in one write txn (FG-1). UPDATEs
#     exclude self. changes()==0 -> re-query to tell CAS-fail from overlap-reject.
#   - recompute derives status but NEVER derives 'abandoned'; a settled event
#     returns its stored settled_outcome verbatim (F-A seal).
#   - cancel = force-settle with outcome 'abandoned'; force_settle = outcome 'done'.
#
# NOTE ON user_version: the event schema is framework migration 003 (DGN-180
# D180-0 renumber -- 002_tasks_archived_at already owns user_version=2, so the
# event schema is 3). The DGN-179 verb-delta adds migration 004 (event_persons
# junction, D2), so the SDK now asserts 4.
# ═══════════════════════════════════════════════════════════════════════════

# MIN-7a (spec v2): ZoneInfo imported at module scope (used by appt_find + the
# facade time parser). datetime/timezone are already imported at file top.
