def cli_spend_upd(argv):
    # spend-upd <id> field=value [field=value ...]
    # fields: date name amount method note is_fixed scope source kind category
    _u = ("사용법: kit_life.sh spend-upd <id> field=value [field=value ...]\n"
          "  field: date name amount method note is_fixed scope source kind "
          "category\n"
          "  지정한 필드만 바뀐다(부분 수정).")
    if len(argv) < 2 or not str(argv[0]).isdigit():
        _err(_u)
    fields = {}
    for tok in argv[1:]:
        if '=' not in tok:
            _err(f"field=value 형식이 아님: {tok}\n{_u}")
        col, val = tok.split('=', 1)
        col = col.strip()
        if col not in _SPEND_UPD_COLS:
            _err(f"수정 불가 컬럼: {col}\n{_u}")
        fields[col] = val
    if not fields:
        _err(_u)
    try:
        row = spend_upd(argv[0], fields)
    except ValueError as e:
        _err(str(e))
    if row is None:
        _err(f"해당 id 지출 없음: {argv[0]}")
    print(f"{row[0]}\t{row[1]}\t{row[2]}\t{row[3]}")


def cli_spend_week(argv):
    # spend-week <monday_date> [--all]
    argv, include_all = _pop_flag(argv, '--all')
    if not argv or not argv[0]:
        _err("사용법: kit_life.sh spend-week <월요일date> [--all]")
    w = spend_week(argv[0], include_all=include_all)
    diff_sign = '+' if w['diff_total'] >= 0 else ''
    print(f"week={w['monday']}~{w['sunday']}")
    print(f"total={w['total']:,}원 ({w['count']}건)")
    print(f"prev_total={w['prev_total']:,}원 ({w['prev_count']}건)")
    print(f"diff_total={diff_sign}{w['diff_total']:,}원")
    print("--- 카테고리별 ---")
    for cat in w['categories']:
        print(f"  {cat['name']}: {cat['amount']:,}원 ({cat['count']}건)")
    # DGN-564: income subtotal + net (income - expense) appended; the
    # expense lines above stay untouched.
    net_sign = '+' if w['net'] >= 0 else ''
    print(f"income={w['income_total']:,}원 ({w['income_count']}건)")
    print(f"net={net_sign}{w['net']:,}원")


def cli_spend_month(argv):
    # spend-month <YYYY-MM> [--all]
    argv, include_all = _pop_flag(argv, '--all')
    if not argv or not argv[0]:
        _err("사용법: kit_life.sh spend-month <YYYY-MM> [--all]")
    ym = argv[0]
    if len(ym) != 7 or ym[4] != '-':
        _err(f"YYYY-MM 형식이어야 함: {ym}")
    m = spend_month(ym, include_all=include_all)
    diff_sign = '+' if m['diff_total'] >= 0 else ''
    print(f"month={m['ym']}")
    print(f"total={m['total']:,}원 ({m['count']}건)")
    print(f"fixed={m['fixed_total']:,}원  variable={m['variable_total']:,}원")
    print(f"prev_month={m['prev_ym']} total={m['prev_total']:,}원")
    print(f"diff_total={diff_sign}{m['diff_total']:,}원")
    # m-6 (grill fix): category breakdown = top 5 by amount (spec 3.5).
    # When more than 5 categories, a remainder line "그 외 N건: X원" is appended.
    cats = m['categories']
    print("--- 카테고리 top5 ---")
    top = cats[:5]
    rest = cats[5:]
    for cat in top:
        print(f"  {cat['name']}: {cat['amount']:,}원 ({cat['count']}건)")
    if rest:
        rest_count = sum(c['count'] for c in rest)
        rest_amount = sum(c['amount'] for c in rest)
        print(f"  그 외 {rest_count}건: {rest_amount:,}원")
    print("--- 결제수단별 ---")
    for mth in m['methods']:
        print(f"  {mth['method']}: {mth['amount']:,}원 ({mth['count']}건)")
    # DGN-564: income subtotal + net (income - expense) appended; the
    # expense lines above stay untouched.
    net_sign = '+' if m['net'] >= 0 else ''
    print(f"income={m['income_total']:,}원 ({m['income_count']}건)")
    print(f"net={net_sign}{m['net']:,}원")


def cli_spend_unknown(argv):
    # spend-unknown: list ALL scope='unknown' entries across all dates.
    # M-2 (grill fix, spec v1.1 amendment): C2 sweep surface.
    # Output per row: id<TAB>date<TAB>name<TAB>amount<TAB>category<TAB>method
    # Footer: count + total, or "미분류(unknown) 지출 없음" when empty.
    rows = spend_unknown()
    if not rows:
        print("미분류(unknown) 지출 없음")
        return
    for eid, date, name, amount, cat, method in rows:
        print(f"{eid}\t{date}\t{name}\t{amount}\t{cat}\t{method}")
    total = sum(r[3] for r in rows)
    print(f"--- unknown {len(rows)}건 합계 {total:,}원 ---")


# ── cut 2 render surface (자원×대상 교차 읽기) ─────────────────────────────
# 039 가 만든 교차(v_entity_flow / v_entity_time_alloc / v_c2_coverage)를
# 처음으로 보이게 하는 READ 전용 verb 네 개: entity-list / entity-flow /
# entity-time / criterion-list.  렌더 규율:
#   * 잔량(balance) 없음.  개시 스냅샷이 한 번도 없었으므로(오너 2026-09-07)
#     잔량은 파생 불가다.  유입/유출은 기간 창 안의 흐름이고, 대상별
#     net(유입-유출)조차 계좌에 대해 잔액처럼 읽히므로 내보내지 않는다.
#   * 기준 동반 (E-5).  모든 흐름 숫자 묶음 옆에 판정층의 활성 기준
#     (v_criterion ∩ domain_metric)이 서거나, 없으면 criterion=none 이
#     명시된다 -- 숫자 단독 금지, 기준 발명 금지.  verb 는 기준 행을
#     그대로 나를 뿐 판정(달성/미달)을 계산하지 않는다: 값과 기준을 잇는
#     판정 문장은 판정층(037)의 것이고, 이 레인의 값은 아직 measure 에
#     살지 않는다.
#   * 무귀속은 무귀속으로 보인다.  entity 없는 델타는 어느 대상에도 담기지
#     않고(catch-all 금지) 별도 '무귀속' 줄로 항상 표시된다(0건이어도 --
#     그 줄의 존재가 "빠뜨린 게 없다"의 증거다).
#   * '관리 중' 은 데이터가 말할 때만.  v_domain_state 의 state 를 함께
#     내보내 스킬이 문구를 데이터로 게이트한다 (ledger 는 현재 unknown --
#     1,603행이 문 없는 일괄 수입으로 도착했다는 참).
#
# money 델타는 spend 레인의 그림자이고 그 레인의 도메인은 ledger 다
# (037 시딩과 같은 근거).  다른 자원은 소유 도메인 선언이 없어 매핑하지
# 않는다 -- 매핑 없는 자원은 domain=- state=- criterion=none 으로 답한다.
_C2_RESOURCE_DOMAIN = {'money': 'ledger'}


def _c2_famt(v, unit):
    """흐름 수치 표시: krw -> 콤마 정수 + 원, min -> 분, 그 외 %g + unit."""
    f = float(v or 0)
    if unit == 'krw':
        return '{:,}원'.format(int(round(f)))
    s = str(int(f)) if f == int(f) else ('%g' % f)
    return s + ('분' if unit == 'min' else (unit or ''))


def _c2_period(arg):
    """'YYYY' 또는 'YYYY-MM' -> 접두 문자열.  그 외 ValueError."""
    s = (arg or '').strip()
    if len(s) == 4 and s.isdigit():
        return s
    if (len(s) == 7 and s[4] == '-' and s[:4].isdigit()
            and s[5:7].isdigit() and 1 <= int(s[5:7]) <= 12):
        return s
    raise ValueError('기간은 YYYY 또는 YYYY-MM 형식: %r' % (arg,))


def _c2_display_map(conn):
    """entity.token -> ko display (label namespace='entity')."""
    return dict(conn.execute(
        "SELECT token, MIN(display) FROM label "
        "WHERE namespace='entity' AND lang='ko' GROUP BY token;").fetchall())


def _c2_entity_matches(conn, ref):
    """대상 ref -> [(id, token)] 후보.  전부 숫자면 id, 아니면 token
    정확일치, 그다음 ko display(label) 정확일치.  0/1/여러 건을 그대로
    반환한다 -- 판정은 CLI 계층(모호하면 후보를 보여 주고 멈춘다, 추측
    금지)."""
    s = (ref or '').strip()
    if not s:
        return []
    if s.isdigit():
        return conn.execute(
            "SELECT id, token FROM entity WHERE id=? AND status='active';",
            (int(s),)).fetchall()
    rows = conn.execute(
        "SELECT id, token FROM entity WHERE token=? AND status='active';",
        (s,)).fetchall()
    if not rows:
        rows = conn.execute(
            "SELECT DISTINCT e.id, e.token FROM entity e "
            "JOIN label l ON l.namespace='entity' AND l.token=e.token "
            "WHERE l.display=? AND e.status='active';", (s,)).fetchall()
    return rows


def _c2_domain_context(conn, domain_token):
    """(state|None, [(source, id, metric, lo, hi)]).  domain_token 이 None
    이면 (None, []) -- 자원의 소유 도메인이 미선언이라는 참을 그대로."""
    if not domain_token:
        return None, []
    row = conn.execute("SELECT state FROM v_domain_state WHERE token=?;",
                       (domain_token,)).fetchone()
    crits = conn.execute(
        "SELECT c.source, c.criterion_id, c.metric, c.lo, c.hi "
        "FROM v_criterion c "
        "JOIN domain_metric dm ON dm.metric = c.metric "
        "JOIN domain d ON d.id = dm.domain_id "
        "WHERE d.token=? ORDER BY c.source, c.criterion_id;",
        (domain_token,)).fetchall()
    return (row[0] if row else None), crits


def _c2_print_context(domain_token, state, crits):
    """E-5 동반 줄: 도메인 상태 + 기준 (없으면 criterion=none 명시)."""
    print('domain=%s state=%s' % (domain_token or '-', state or '-'))
    if not crits:
        print('criterion=none')
        return
    print('criterion=%d건' % len(crits))
    for source, cid, metric, lo, hi in crits:
        print('  %s#%s %s: lo=%s hi=%s'
              % (source, cid, metric,
                 '-' if lo is None else ('%g' % lo),
                 '-' if hi is None else ('%g' % hi)))


def entity_flow(period, entity_id=None, resource='money', conn=None):
    """기간(YYYY|YYYY-MM) × 자원별 대상 흐름 dict.  유입/유출만 -- 잔량·
    net 없음(파생 불가, 오너 2026-09-07).  무귀속은 같은 기간·자원의
    entity NULL 델타로 별도 집계(절대 대상 행에 섞지 않는다)."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        prefix = _c2_period(period)
        sql = ("SELECT entity_token, unit, SUM(inflow), SUM(outflow), "
               "SUM(n_deltas) FROM v_entity_flow "
               "WHERE resource=? AND month LIKE ?")
        params = [resource, prefix + '%']
        if entity_id is not None:
            sql += " AND entity_id=?"
            params.append(entity_id)
        sql += " GROUP BY entity_token, unit ORDER BY SUM(outflow) DESC;"
        rows = conn.execute(sql, params).fetchall()
        una = conn.execute(
            "SELECT COUNT(*), "
            "COALESCE(SUM(CASE WHEN d.amount > 0 THEN d.amount END), 0), "
            "COALESCE(SUM(CASE WHEN d.amount < 0 THEN -d.amount END), 0) "
            "FROM block_delta d JOIN block b ON b.id = d.block_id "
            "WHERE d.resource=? AND d.entity_id IS NULL "
            "AND substr(COALESCE(b.date, b.start_at), 1, ?) = ?;",
            (resource, len(prefix), prefix)).fetchone()
        cov = conn.execute(
            "SELECT n_deltas, n_with_entity FROM v_c2_coverage "
            "WHERE resource=?;", (resource,)).fetchone()
        domain = _C2_RESOURCE_DOMAIN.get(resource)
        state, crits = _c2_domain_context(conn, domain)
        disp = _c2_display_map(conn)
        return {
            'period': prefix, 'resource': resource,
            'rows': [{'token': r[0], 'display': disp.get(r[0], r[0]),
                      'unit': r[1], 'inflow': r[2], 'outflow': r[3],
                      'n': r[4]} for r in rows],
            'unattributed': {'n': una[0], 'inflow': una[1],
                             'outflow': una[2]},
            'coverage': (None if cov is None
                         else {'n_deltas': cov[0], 'n_with_entity': cov[1]}),
            'domain': domain, 'state': state, 'criteria': crits,
        }
    finally:
        if own:
            conn.close()


def entity_time(period, entity_id=None, conn=None):
    """기간(YYYY|YYYY-MM) × 대상별 배분 시간(분) dict.  파생 전용
    (v_entity_time_alloc); K-5/K-6 위반 블록은 뷰가 통째로 거부하므로
    제외 블록 수를 함께 내보낸다(침묵 탈락 금지).  links=0 이면 교차
    미기록 상태 -- '0분 썼다'가 아니라 '귀속 데이터가 없다'."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        prefix = _c2_period(period)
        sql = ("SELECT e.token, SUM(a.alloc_min), COUNT(DISTINCT a.block_id) "
               "FROM v_entity_time_alloc a JOIN entity e ON e.id=a.entity_id "
               "WHERE substr(a.date, 1, ?) = ?")
        params = [len(prefix), prefix]
        if entity_id is not None:
            sql += " AND a.entity_id=?"
            params.append(entity_id)
        sql += " GROUP BY a.entity_id ORDER BY SUM(a.alloc_min) DESC;"
        rows = conn.execute(sql, params).fetchall()
        n_links = conn.execute(
            "SELECT COUNT(*) FROM block_entity;").fetchone()[0]
        excluded = conn.execute(
            "SELECT COUNT(*) FROM (SELECT block_id FROM v_k5_duplicate_target "
            "UNION SELECT block_id FROM v_k6_weight_sum);").fetchone()[0]
        state, crits = _c2_domain_context(conn,
                                          _C2_RESOURCE_DOMAIN.get('time'))
        disp = _c2_display_map(conn)
        return {
            'period': prefix,
            'rows': [{'token': r[0], 'display': disp.get(r[0], r[0]),
                      'alloc_min': r[1], 'n_blocks': r[2]} for r in rows],
            'n_links': n_links, 'excluded_blocks': excluded,
            'domain': _C2_RESOURCE_DOMAIN.get('time'), 'state': state,
            'criteria': crits,
        }
    finally:
        if own:
            conn.close()


def cli_entity_list(argv):
    # entity-list
    # -> id<TAB>token<TAB>display<TAB>status<TAB>n_deltas  (교차 대상 로스터.
    #    스킬이 오너의 호칭을 이 표에 대조해 ref 를 고른다 -- 추측 금지)
    conn = get_conn()
    try:
        rows = conn.execute(
            "SELECT e.id, e.token, e.status, "
            "(SELECT COUNT(*) FROM block_delta d WHERE d.entity_id = e.id) "
            "FROM entity e ORDER BY e.id;").fetchall()
        disp = _c2_display_map(conn)
    finally:
        conn.close()
    if not rows:
        print('등록된 대상 없음')
        return
    for eid, token, status, n in rows:
        print('%d\t%s\t%s\t%s\t%d'
              % (eid, token, disp.get(token, '-'), status, n))


def _c2_entity_ref_resolve(argv_ref):
    """CLI 공용 ref 판정: 정확히 하나면 id, 0건/모호는 각각 명시적 _err."""
    conn = get_conn()
    try:
        matches = _c2_entity_matches(conn, argv_ref)
    finally:
        conn.close()
    if not matches:
        _err('해당 대상 없음: %s (entity-list 로 확인)' % argv_ref)
    if len(matches) > 1:
        _err('대상이 모호함: %s -> %s'
             % (argv_ref, ', '.join('%d:%s' % (m[0], m[1])
                                    for m in matches)))
    return matches[0][0]


def cli_entity_flow(argv):
    # entity-flow <YYYY-MM|YYYY> [대상] [--resource <token>]
    # 기간 × 자원별 대상 흐름 (유입/유출만; 잔량 없음 -- 파생 불가).
    # 무귀속 줄은 항상 출력(0건 포함), coverage 는 전 기간 귀속률,
    # domain/state/criterion 줄은 E-5 동반(기준 없으면 none 명시).
    argv, res = _pop_opt(argv, '--resource')
    resource = res or 'money'
    if not argv or not argv[0]:
        _err('사용법: kit_life.sh entity-flow <YYYY-MM|YYYY> [대상] '
             '[--resource <token>]')
    eid = _c2_entity_ref_resolve(argv[1]) if len(argv) > 1 else None
    try:
        f = entity_flow(argv[0], entity_id=eid, resource=resource)
    except ValueError as e:
        _err(str(e))
    print('period=%s resource=%s' % (f['period'], f['resource']))
    print('--- 대상별 흐름 (유출/유입) ---')
    if not f['rows']:
        print('  귀속된 흐름 없음')
    for r in f['rows']:
        print('  %s: 유출 %s / 유입 %s (%d건)'
              % (r['display'], _c2_famt(r['outflow'], r['unit']),
                 _c2_famt(r['inflow'], r['unit']), r['n']))
    u = f['unattributed']
    print('무귀속: %d건 유출 %s / 유입 %s'
          % (u['n'], _c2_famt(u['outflow'], 'krw' if resource == 'money'
                              else ''),
             _c2_famt(u['inflow'], 'krw' if resource == 'money' else '')))
    if f['coverage'] is not None:
        c = f['coverage']
        print('coverage={} {:,}건 중 {:,}건 귀속 (전 기간)'.format(
            f['resource'], c['n_deltas'], c['n_with_entity']))
    _c2_print_context(f['domain'], f['state'], f['criteria'])


def cli_entity_time(argv):
    # entity-time <YYYY-MM|YYYY> [대상]
    # 기간 × 대상별 배분 시간(분).  links=0 이면 '귀속 데이터 없음'을
    # 명시(0분과 무데이터는 다르다).  K-5/K-6 위반으로 거부된 블록 수를
    # 항상 출력(침묵 탈락 금지).  E-5 동반 줄 포함.
    if not argv or not argv[0]:
        _err('사용법: kit_life.sh entity-time <YYYY-MM|YYYY> [대상]')
    eid = _c2_entity_ref_resolve(argv[1]) if len(argv) > 1 else None
    try:
        t = entity_time(argv[0], entity_id=eid)
    except ValueError as e:
        _err(str(e))
    print('period=%s resource=time' % t['period'])
    if t['n_links'] == 0:
        print('대상 연결 0건 -- 시간 귀속 데이터 없음(교차 미기록)')
    else:
        print('--- 대상별 배분 시간 ---')
        if not t['rows']:
            print('  이 기간 귀속된 시간 없음')
        for r in t['rows']:
            print('  %s: %s (%d블록)'
                  % (r['display'], _c2_famt(r['alloc_min'], 'min'),
                     r['n_blocks']))
    print('excluded=%d블록 (K-5/K-6 위반, 배분 거부)' % t['excluded_blocks'])
    _c2_print_context(t['domain'], t['state'], t['criteria'])


def cli_criterion_list(argv):
    # criterion-list [domain-token]
    # 판정층 기준 읽기: 도메인별 "domain=<t> state=<s>" + 기준 행
    # (criterion=none 명시).  spend-month/week 등 흐름 숫자에 '목표 대비'
    # 답을 달 때 스킬이 반드시 함께 실행하는 E-5 동반 verb.
    conn = get_conn()
    try:
        if argv and argv[0]:
            row = conn.execute(
                "SELECT token FROM domain WHERE token=? AND status='active';",
                (argv[0],)).fetchone()
            if row is None:
                conn.close()
                _err('도메인 없음: %s' % argv[0])
            tokens = [argv[0]]
        else:
            tokens = [r[0] for r in conn.execute(
                "SELECT token FROM domain WHERE status='active' "
                "ORDER BY id;").fetchall()]
        ctx = [(t,) + _c2_domain_context(conn, t) for t in tokens]
    finally:
        conn.close()
    for token, state, crits in ctx:
        _c2_print_context(token, state, crits)


# ── payline v1.1 (결제수단 / 고정비·정기수입 / 가드) ──────────────
# 통합 원장(payline) 축적 계층. 결제수단(pay_method)=find-first/upsert(D3),
# 고정비·정기수입(fixed_cost)=direction 플래그로 통합, ledger_guard=집행 규칙을
# 코드 하드코딩 대신 DB에서 읽어(measure-first, D2/D5) auto/ceiling 게이트에 적용.

# payline HOLD 코드: entry_amount_ceiling(enforcement=hold) 미확정 쓰기의 전용
# 종료코드. EXISTS_CODE(3)/CONFLICT_CODE(4)와 구별되는 별도 계약.
PAYLINE_HOLD_CODE = 5

_PAY_METHOD_KINDS = {'credit_card', 'debit_card', 'account', 'cash', 'easy_pay'}
# i18n: kind is a scalar enum (no display_name column) -> ko display mapped at
# the code layer for human output (method-list). DB stores the english key.
_PAY_METHOD_KIND_DISPLAY = {
    'credit_card': '신용카드', 'debit_card': '체크카드', 'account': '계좌',
    'cash': '현금', 'easy_pay': '간편결제',
}
_FIXED_DIRECTIONS = {'expense', 'income'}
_FIXED_SOURCES = {'interview', 'chat', 'batch'}
_GUARD_ENFORCEMENT = {'block', 'hold', 'inform'}


def _pay_method_by_ref(conn, ref):
    """결제수단 ref 해석: 전부 숫자면 id, 아니면 name. (id, name, kind) 또는 None."""
    if ref is None:
        return None
    s = str(ref).strip()
    if s == '':
        return None
    if s.isdigit():
        row = conn.execute(
            "SELECT id, name, kind FROM pay_method WHERE id=?;",
            (int(s),)).fetchone()
    else:
        row = conn.execute(
            "SELECT id, name, kind FROM pay_method WHERE name=?;",
            (s,)).fetchone()
    return row  # (id, name, kind) or None


def _method_entity_accrue(conn, name):
    """2.34.0, intake port (design A2-2, ledger pack gap G6): the payment instrument's
    entity + label, find-first, in the caller's transaction.  Resolution is
    the 039 rule (_spend_entity_id: label(namespace='entity').display == the
    method name, exactly one active entity), so a card registered here
    resolves for spend-add, intake confirmation and every crossing view.

    Returns (status, entity_id):
      ('found', id)      a label already names exactly one active entity
      ('created', id)    no label named it: entity + ko label inserted
      ('ambiguous', None) several entities carry that label -- nothing written
      ('inactive', None)  the one labelled entity is dormant/gone -- nothing
                          written (reviving a retired instrument is the
                          owner's call, not a side effect of method-add)
    The token/ulid are ASCII and derived from the name (a Korean card name
    has no honest transliteration), so re-adding the same name after its
    label was removed finds the same entity instead of minting a twin."""
    m = (name or '').strip()
    if not m:
        return ('ambiguous', None)
    hits = conn.execute(
        "SELECT DISTINCT e.id, e.status FROM entity e "
        "JOIN label l ON l.namespace='entity' AND l.token=e.token "
        "WHERE l.display=?;", (m,)).fetchall()
    if len(hits) > 1:
        return ('ambiguous', None)
    if len(hits) == 1:
        return ('found', hits[0][0]) if hits[0][1] == 'active' \
            else ('inactive', None)
    digest = hashlib.sha256(m.encode('utf-8')).hexdigest()[:12]
    token = 'pay_method_' + digest
    ulid = 'x-ent-pm-' + digest
    row = conn.execute("SELECT id, status FROM entity WHERE ulid=?;",
                       (ulid,)).fetchone()
    if row is None:
        eid = conn.execute(
            "INSERT INTO entity(ulid, token, fungible, origin, status) "
            "VALUES (?,?,0,'user','active');", (ulid, token)).lastrowid
    elif row[1] != 'active':
        return ('inactive', None)
    else:
        eid = row[0]
    conn.execute(
        "INSERT OR IGNORE INTO label(namespace, token, lang, display) "
        "VALUES ('entity', ?, 'ko', ?);", (token, m))
    return ('created', eid)


def method_add(name, kind, aliases=None, billing_day=None, link=None,
               conn=None, with_entity=False):
    """결제수단 find-first/upsert(D3). name UNIQUE 기준: 있으면 기존 행 반환(중복
    생성 금지), 없으면 신규. 반환: (id, name, kind).

    kind 검증/체크카드-링크 강제(2026-07-27 convention)는 CLI 계층에서 수행하며,
    core 는 이미 검증된 값을 받는다. link=계정 ref -> linked_account_id.

    2.34.0: 같은 트랜잭션에서 entity + label 을 find-first 로 붙인다
    (_method_entity_accrue). 기존 수단(2.34 이전 등록, entity 없음)도 다시
    method-add 하면 붙는다. with_entity=True 면 (id, name, kind, status,
    entity_id) 를 반환한다."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        linked_id = None
        if link is not None:
            lrow = _pay_method_by_ref(conn, link)
            linked_id = lrow[0] if lrow else None
        existing = conn.execute(
            "SELECT id, name, kind FROM pay_method WHERE name=?;",
            (name,)).fetchone()
        if existing:
            row = existing  # find-first: 중복 생성 금지
        else:
            cur = conn.execute(
                "INSERT INTO pay_method (name, kind, aliases, billing_day, "
                "linked_account_id) VALUES (?,?,?,?,?);",
                (name, kind, _txt(aliases), billing_day, linked_id))
            row = conn.execute(
                "SELECT id, name, kind FROM pay_method WHERE id=?;",
                (cur.lastrowid,)).fetchone()
        status, eid = _method_entity_accrue(conn, row[1])
        conn.commit()
        return tuple(row) + (status, eid) if with_entity else row
    finally:
        if own:
            conn.close()


def method_list(conn=None):
    """전 결제수단 목록. 반환: (id, name, kind, billing_day, linked_name) 리스트."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        return conn.execute(
            "SELECT m.id, m.name, m.kind, m.billing_day, a.name "
            "FROM pay_method m "
            "LEFT JOIN pay_method a ON a.id = m.linked_account_id "
            "ORDER BY m.id;").fetchall()
    finally:
        if own:
            conn.close()


_METHOD_UPD_COLS = {'name', 'kind', 'aliases', 'billing_day',
                    'linked_account_id'}


def method_upd(mid, fields, conn=None):
    """결제수단 부분 갱신. 갱신 후 (id, name, kind, billing_day, linked_account_id)
    반환(없으면 None). 수정 불가 컬럼은 ValueError."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        sets, vals = [], []
        for col, raw in fields.items():
            if col not in _METHOD_UPD_COLS:
                raise ValueError(f"수정 불가 컬럼: {col}")
            if col == 'kind' and raw not in _PAY_METHOD_KINDS:
                raise ValueError(
                    f"kind 값 오류: {raw} "
                    f"({'|'.join(sorted(_PAY_METHOD_KINDS))})")
            if col == 'billing_day':
                sets.append(f"{col}=?")
                vals.append(int(raw) if str(raw).strip() != '' else None)
            elif col == 'linked_account_id':
                sets.append(f"{col}=?")
                vals.append(int(raw) if str(raw).strip() != '' else None)
            elif col == 'aliases':
                sets.append(f"{col}=?")
                vals.append(_txt(raw))
            else:
                sets.append(f"{col}=?")
                vals.append(raw)
        if not sets:
            raise ValueError("갱신할 필드 없음")
        vals.append(int(mid))
        conn.execute(
            f"UPDATE pay_method SET {', '.join(sets)} WHERE id=?;", vals)
        conn.commit()
        return conn.execute(
            "SELECT id, name, kind, billing_day, linked_account_id "
            "FROM pay_method WHERE id=?;", (int(mid),)).fetchone()
    finally:
        if own:
            conn.close()


def method_link(card_ref, account_ref, conn=None):
    """카드의 linked_account_id 를 결제계정으로 설정. 반환: (card_id, card_name,
    account_id, account_name) 또는 None(카드/계정 미해석)."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        card = _pay_method_by_ref(conn, card_ref)
        acct = _pay_method_by_ref(conn, account_ref)
        if card is None or acct is None:
            return None
        conn.execute(
            "UPDATE pay_method SET linked_account_id=? WHERE id=?;",
            (acct[0], card[0]))
        conn.commit()
        return (card[0], card[1], acct[0], acct[1])
    finally:
        if own:
            conn.close()


def _guard_row(conn, key, scope='global'):
    """ledger_guard 한 행 조회. 반환: (guard_key, scope, value, unit, enforcement,
    inviolable) 또는 None. 가드 임계값은 코드가 아닌 이 행에서 읽는다(D2/D5)."""
    return conn.execute(
        "SELECT guard_key, scope, value, unit, enforcement, inviolable "
        "FROM ledger_guard WHERE guard_key=? AND scope=?;",
        (key, scope)).fetchone()


class PaylineGuardBlock(Exception):
    """auto_entry_enabled(block) 위반: auto 쓰기가 가드로 차단됨. 행 미생성."""


class PaylineGuardHold(Exception):
    """entry_amount_ceiling(hold) 초과: --confirm 없으면 보류. 행 미생성."""
    def __init__(self, amount, ceiling):
        self.amount = amount
        self.ceiling = ceiling
        super().__init__(
            f"금액 {amount:,}원이 확인 임계 {ceiling:,}원을 초과합니다. "
            f"확인 후 --confirm 으로 진행하세요.")


def fixed_add(name, amount, category=None, next_due=None, cycle='monthly',
              pay_mode=None, method=None, direction='expense', auto_entry=0,
              source='interview', confirm=False, conn=None):
    """고정비/정기수입 한 건 기록(direction 통합). 새 행 id 반환.

    가드 통합(D2/D5, 임계값은 ledger_guard 에서 읽음):
    - auto_entry_enabled(block): auto_entry=1 요청인데 가드 value=0 이면
      PaylineGuardBlock (행 미생성).
    - entry_amount_ceiling(hold): amount > 가드 value 이면 confirm=False 시
      PaylineGuardHold (행 미생성). confirm=True 면 진행.
    검증(direction/source/auto/amount)은 CLI 계층에서 수행, core 는 게이트만."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        amount = int(amount)
        # 가드 읽기 (하드코딩 금지)
        g_auto = _guard_row(conn, 'auto_entry_enabled')
        if int(auto_entry) == 1 and g_auto is not None and \
                (g_auto[2] is None or int(g_auto[2]) == 0):
            raise PaylineGuardBlock(
                "auto_entry_enabled 가드가 꺼져 있어 자동입력을 차단합니다. "
                "guard-set auto_entry_enabled 1 로 활성화 후 다시 시도하세요.")
        g_ceil = _guard_row(conn, 'entry_amount_ceiling')
        if g_ceil is not None and g_ceil[2] is not None and \
                amount > int(g_ceil[2]) and not confirm:
            raise PaylineGuardHold(amount, int(g_ceil[2]))
        cid = spend_category_get_or_create(conn, category) if category else None
        mrow = _pay_method_by_ref(conn, method) if method else None
        method_id = mrow[0] if mrow else None
        cur = conn.execute(
            "INSERT INTO fixed_cost "
            "(name, amount, category_id, next_due, cycle, pay_mode, method_id, "
            "direction, auto_entry, source) VALUES (?,?,?,?,?,?,?,?,?,?);",
            (name, amount, cid, _txt(next_due), cycle, _txt(pay_mode),
             method_id, direction, int(auto_entry), source))
        conn.commit()
        return cur.lastrowid
    finally:
        if own:
            conn.close()


def fixed_list(direction=None, conn=None):
    """고정비/정기수입 목록. direction 지정 시 필터. 반환: (id, name, amount,
    direction, category, next_due, cycle, method_name) 리스트.

    category = ko display (COALESCE(display_name, name)); fixed-list is
    human-facing output (bulleted 원/합계), so it renders the ko label."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        base = (
            "SELECT f.id, f.name, f.amount, f.direction, "
            "COALESCE(c.display_name, c.name, ''), COALESCE(f.next_due,''), "
            "f.cycle, COALESCE(m.name,'') FROM fixed_cost f "
            "LEFT JOIN spend_category c ON c.id = f.category_id "
            "LEFT JOIN pay_method m ON m.id = f.method_id ")
        if direction:
            return conn.execute(
                base + "WHERE f.direction=? ORDER BY f.id;",
                (direction,)).fetchall()
        return conn.execute(base + "ORDER BY f.id;").fetchall()
    finally:
        if own:
            conn.close()


_FIXED_UPD_COLS = {
    'name': _txt, 'category': None, 'next_due': _txt, 'cycle': _txt,
    'pay_mode': _txt, 'amount': _strict_amount,
    'method_id': None, 'direction': None, 'auto_entry': None, 'source': None,
}


def fixed_upd(fid, fields, conn=None):
    """고정비 부분 갱신. 갱신 후 (id, name, amount, direction) 반환(없으면 None).
    strict amount, direction/auto/source 검증. category 는 get_or_create 로 해석."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        sets, vals = [], []
        for col, raw in fields.items():
            if col not in _FIXED_UPD_COLS:
                raise ValueError(f"수정 불가 컬럼: {col}")
            if col == 'category':
                cid = spend_category_get_or_create(conn, raw) if raw else None
                sets.append("category_id=?")
                vals.append(cid)
            elif col == 'amount':
                sets.append("amount=?")
                vals.append(_strict_amount(raw))
            elif col == 'direction':
                if raw not in _FIXED_DIRECTIONS:
                    raise ValueError(
                        f"direction 값 오류: {raw} (expense/income)")
                sets.append("direction=?")
                vals.append(raw)
            elif col == 'auto_entry':
                if str(raw) not in ('0', '1'):
                    raise ValueError(f"auto_entry 값 오류: {raw} (0/1)")
                sets.append("auto_entry=?")
                vals.append(int(raw))
            elif col == 'source':
                if raw not in _FIXED_SOURCES:
                    raise ValueError(
                        f"source 값 오류: {raw} (interview/chat/batch)")
                sets.append("source=?")
                vals.append(raw)
            elif col == 'method_id':
                sets.append("method_id=?")
                vals.append(int(raw) if str(raw).strip() != '' else None)
            else:
                sets.append(f"{col}=?")
                vals.append(_FIXED_UPD_COLS[col](raw))
        if not sets:
            raise ValueError("갱신할 필드 없음")
        vals.append(int(fid))
        conn.execute(
            f"UPDATE fixed_cost SET {', '.join(sets)} WHERE id=?;", vals)
        conn.commit()
        return conn.execute(
            "SELECT id, name, amount, direction FROM fixed_cost WHERE id=?;",
            (int(fid),)).fetchone()
    finally:
        if own:
            conn.close()


def fixed_del(fid, conn=None):
    """고정비/정기수입 한 건 삭제."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        conn.execute("DELETE FROM fixed_cost WHERE id=?;", (int(fid),))
        conn.commit()
    finally:
        if own:
            conn.close()


def method_del(mid, conn=None):
    """결제수단(카드/계좌 공용) 삭제. FK-안전: 고정비(method_id) 또는 다른 결제수단
    (linked_account_id, 예: 체크카드 연결계좌)가 참조 중이면 삭제 거부.
    반환: (status, payload).
      ('notfound', None)                     -- 해당 id 없음
      ('blocked', {'fixed':[(id,name)...],   -- 참조자 목록(먼저 재지정/링크해제 필요)
                   'linked':[(id,name)...]})
      ('deleted', (id, name, kind))          -- 삭제 완료"""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        row = conn.execute(
            "SELECT id, name, kind FROM pay_method WHERE id=?;",
            (int(mid),)).fetchone()
        if row is None:
            return ('notfound', None)
        fixed_refs = conn.execute(
            "SELECT id, name FROM fixed_cost WHERE method_id=? ORDER BY id;",
            (int(mid),)).fetchall()
        linked_refs = conn.execute(
            "SELECT id, name FROM pay_method WHERE linked_account_id=? "
            "ORDER BY id;", (int(mid),)).fetchall()
        if fixed_refs or linked_refs:
            return ('blocked',
                    {'fixed': fixed_refs, 'linked': linked_refs})
        conn.execute("DELETE FROM pay_method WHERE id=?;", (int(mid),))
        conn.commit()
        return ('deleted', row)
    finally:
        if own:
            conn.close()


def guard_get(key, scope='global', conn=None):
    """가드 행 조회. 반환: (guard_key, scope, value, unit, enforcement,
    inviolable) 또는 None."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        return _guard_row(conn, key, scope)
    finally:
        if own:
            conn.close()


def guard_set(key, value, scope='global', enforcement=None, unit=None,
              source=None, conn=None):
    """기존 가드 행 갱신(생성 안 함, v1.1). value 는 정수 또는 None(measure-first).
    updated_at 갱신. enforcement 지정 시 {block,hold,inform} 검증. 갱신 후 행 반환;
    (key,scope) 행 없으면 None."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        if _guard_row(conn, key, scope) is None:
            return None
        if enforcement is not None and enforcement not in _GUARD_ENFORCEMENT:
            raise ValueError(
                f"enforcement 값 오류: {enforcement} (block/hold/inform)")
        sets = ["value=?", "updated_at=datetime('now','localtime')"]
        vals = [None if value is None else int(value)]
        if enforcement is not None:
            sets.append("enforcement=?")
            vals.append(enforcement)
        if unit is not None:
            sets.append("unit=?")
            vals.append(unit)
        if source is not None:
            sets.append("source=?")
            vals.append(source)
        vals.extend([key, scope])
        conn.execute(
            f"UPDATE ledger_guard SET {', '.join(sets)} "
            "WHERE guard_key=? AND scope=?;", vals)
        conn.commit()
        return _guard_row(conn, key, scope)
    finally:
        if own:
            conn.close()


# ── payline CLI (v1.1) ──────────────────────────────────────

def cli_method_add(argv):
    # method-add <name> <kind> [aliases] [--billing-day N] [--link <ref>]
    #            [--new-confirmed]
    # method_add is find-first on the EXACT name; the near gate (2026-09-28)
    # stops "현대카드 M" / "현대 카드M" beside 현대카드M from minting a second
    # instrument (and a second entity). --new-confirmed = owner said different.
    argv, new_confirmed = _pop_flag(argv, '--new-confirmed')
    argv, billing_val = _pop_opt(argv, '--billing-day')
    argv, link_val = _pop_opt(argv, '--link')
    _u = ("사용법: kit_life.sh method-add <name> <kind> [aliases] "
          "[--billing-day N] [--link <account_name_or_id>]\n"
          "  kind: " + '|'.join(sorted(_PAY_METHOD_KINDS)))
    if len(argv) < 2 or not argv[0] or not argv[1]:
        _err(_u)
    name, kind = argv[0], argv[1]
    aliases = argv[2] if len(argv) > 2 else None
    if kind not in _PAY_METHOD_KINDS:
        _err(f"kind 값 오류: {kind} ({'|'.join(sorted(_PAY_METHOD_KINDS))})")
    billing_day = None
    if billing_val is not None:
        if not str(billing_val).isdigit():
            _err(f"--billing-day 는 숫자여야 함: {billing_val}")
        billing_day = int(billing_val)
    conn = get_conn()
    try:
        # 체크카드(debit_card)는 결제계정 링크 필수(2026-07-27 convention). 신용카드는 선택.
        if kind == 'debit_card':
            if link_val is None or _pay_method_by_ref(conn, link_val) is None:
                _err("체크카드는 결제계정 링크가 필요합니다. "
                     "--link <account_name_or_id> 로 결제계정을 지정하세요.")
        if conn.execute("SELECT 1 FROM pay_method WHERE name=?;",
                        (name,)).fetchone() is None:
            _near_gate_new_confirmed(conn, "method", name, new_confirmed)
        row = method_add(name, kind, aliases=aliases, billing_day=billing_day,
                         link=link_val, conn=conn, with_entity=True)
        # 2.34.0: 4th column = the resolved entity id (empty when it could
        # not be resolved without guessing; the reason goes to stderr).
        print(f"{row[0]}\t{row[1]}\t{row[2]}\t{row[4] if row[4] else ''}")
        if row[3] == 'ambiguous':
            print(f"주의: '{row[1]}' 라벨이 여러 entity 를 가리켜 연결하지 않았습니다 "
                  "(이 수단의 지출은 대상 미귀속으로 남고 intake 확정이 거부됩니다).",
                  file=sys.stderr)
        elif row[3] == 'inactive':
            print(f"주의: '{row[1]}' entity 가 휴면/폐기 상태라 되살리지 않았습니다.",
                  file=sys.stderr)
    finally:
        conn.close()


def _method_aliases(raw):
    """pay_method.aliases is free text: a JSON list, or pipe/comma separated
    (the same reading intake.money_data applies)."""
    try:
        vals = json.loads(raw or '[]')
        if not isinstance(vals, list):
            raise ValueError()
    except (ValueError, TypeError):
        vals = re.split(r'[|,]', raw or '')
    out = []
    for v in vals:
        v = str(v).strip()
        if v and v not in out:
            out.append(v)
    return out


def method_list_json(conn):
    """2.34.0 (G3): machine read of every payment method incl. aliases and the
    resolved entity id. Read-only; no write lock."""
    out = []
    for mid, name, kind, aliases, bd, lid in conn.execute(
            "SELECT id, name, kind, aliases, billing_day, linked_account_id "
            "FROM pay_method ORDER BY id;").fetchall():
        out.append({'id': mid, 'name': name, 'kind': kind,
                    'aliases': _method_aliases(aliases), 'billing_day': bd,
                    'linked_account_id': lid,
                    'entity_id': _spend_entity_id(conn, name)})
    return out


def method_alias_add(ref, aliases, conn):
    """2.34.0 (G3): merge aliases into a method (method-upd aliases= replaces).
    Find-first: an alias already present, or equal to the name, is skipped.
    Refuses an alias another method already answers to (name or alias) --
    that would make intake resolution ambiguous. Stores a JSON list.
    Returns (id, name, aliases list, added list) or None (no such method)."""
    row = _pay_method_by_ref(conn, ref)
    if row is None:
        return None
    cur = conn.execute("SELECT aliases FROM pay_method WHERE id=?;",
                       (row[0],)).fetchone()[0]
    have = _method_aliases(cur)
    added = []
    for a in aliases:
        a = str(a).strip()
        if not a or a == row[1] or a in have:
            continue
        for oid, oname, oal in conn.execute(
                "SELECT id, name, aliases FROM pay_method WHERE id<>?;",
                (row[0],)).fetchall():
            if a == oname or a in _method_aliases(oal):
                raise ValueError(f"별칭 '{a}' 는 이미 다른 결제수단({oid}. {oname})이 씁니다")
        have.append(a)
        added.append(a)
    if added:
        conn.execute("UPDATE pay_method SET aliases=? WHERE id=?;",
                     (json.dumps(have, ensure_ascii=False), row[0]))
        conn.commit()
    return (row[0], row[1], have, added)


def cli_method_alias_add(argv):
    # method-alias-add <id|name> <alias> [<alias> ...]
    if len(argv) < 2 or not argv[0]:
        _err("사용법: kit_life.sh method-alias-add <id|name> <alias> [<alias> ...]")
    conn = get_conn()
    try:
        conn.execute('BEGIN IMMEDIATE')
        try:
            res = method_alias_add(argv[0], argv[1:], conn)
        except ValueError as e:
            conn.rollback()
            _err(str(e))
        if res is None:
            conn.rollback()
            _err(f"해당 결제수단 없음: {argv[0]}")
        if conn.in_transaction:
            conn.commit()
        print(json.dumps({'id': res[0], 'name': res[1], 'aliases': res[2],
                          'added': res[3]}, ensure_ascii=True))
    finally:
        conn.close()


