def cli_fixed_add(argv):
    # fixed-add <name> <amount> [category] [--next-due YYYY-MM-DD]
    #           [--cycle monthly] [--pay-mode <text>] [--method <ref>]
    #           [--direction expense|income] [--auto 0|1]
    #           [--source interview|chat|batch] [--confirm]
    argv, confirm = _pop_flag(argv, '--confirm')
    argv, next_due = _pop_opt(argv, '--next-due')
    argv, cycle_val = _pop_opt(argv, '--cycle')
    argv, pay_mode = _pop_opt(argv, '--pay-mode')
    argv, method_val = _pop_opt(argv, '--method')
    argv, direction_val = _pop_opt(argv, '--direction')
    argv, auto_val = _pop_opt(argv, '--auto')
    argv, source_val = _pop_opt(argv, '--source')
    _u = ("사용법: kit_life.sh fixed-add <name> <amount> [category] "
          "[--next-due YYYY-MM-DD] [--cycle monthly] [--pay-mode <text>] "
          "[--method <name_or_id>] [--direction expense|income] "
          "[--auto 0|1] [--source interview|chat|batch] [--confirm]")
    if len(argv) < 2 or not argv[0] or not argv[1]:
        _err(_u)
    name = argv[0]
    try:
        amount = _strict_amount(argv[1])
    except ValueError as e:
        _err(str(e))
    category = argv[2] if len(argv) > 2 else None
    cycle = cycle_val or 'monthly'
    direction = direction_val or 'expense'
    if direction not in _FIXED_DIRECTIONS:
        _err(f"direction 값 오류: {direction} (expense/income)")
    source = source_val or 'interview'
    if source not in _FIXED_SOURCES:
        _err(f"source 값 오류: {source} (interview/chat/batch)")
    auto_entry = 0
    if auto_val is not None:
        if str(auto_val) not in ('0', '1'):
            _err(f"--auto 값은 0 또는 1이어야 함: {auto_val}")
        auto_entry = int(auto_val)
    conn = get_conn()
    try:
        nid = fixed_add(name, amount, category=category, next_due=next_due,
                        cycle=cycle, pay_mode=pay_mode, method=method_val,
                        direction=direction, auto_entry=auto_entry,
                        source=source, confirm=confirm, conn=conn)
    except PaylineGuardBlock as e:
        print(str(e), file=sys.stderr)
        conn.close()
        sys.exit(1)
    except PaylineGuardHold as e:
        print(f"HOLD {e.amount}\t{e.ceiling}", file=sys.stderr)
        print(str(e), file=sys.stderr)
        conn.close()
        sys.exit(PAYLINE_HOLD_CODE)
    row = conn.execute(
        "SELECT id, name, amount, direction FROM fixed_cost WHERE id=?;",
        (nid,)).fetchone()
    conn.close()
    print(f"{row[0]}\t{row[1]}\t{row[2]}\t{row[3]}")


