def _guard_fmt(row):
    """가드 행을 machine 라인으로: key\tscope\tvalue\tunit\tenforcement\tinviolable.
    value/unit NULL 은 빈 필드."""
    key, scope, value, unit, enf, inviol = row
    v = '' if value is None else str(value)
    u = '' if unit is None else unit
    return f"{key}\t{scope}\t{v}\t{u}\t{enf}\t{inviol}"


