def cli_experience_list(argv):
    # experience-list [date_from] [date_to]
    # pending flag = reaction IS NULL (an enrichment blank to fill in review).
    date_from = argv[0] if len(argv) > 0 and argv[0] else None
    date_to = argv[1] if len(argv) > 1 and argv[1] else None
    where = []
    params = []
    if date_from:
        where.append("date(created_at) >= date(?)")
        params.append(date_from)
    if date_to:
        where.append("date(created_at) <= date(?)")
        params.append(date_to)
    where_sql = (" WHERE " + " AND ".join(where)) if where else ""
    conn = get_conn()
    try:
        rows = conn.execute(
            "SELECT id, ulid, title, "
            "CASE WHEN reaction IS NULL THEN 1 ELSE 0 END AS pending, "
            "created_at FROM event" + where_sql + " ORDER BY id;",
            tuple(params)).fetchall()
        for eid, ulid, title, pending, created in rows:
            print(f"{eid}\t{ulid}\t{title}\t{pending}\t{created}")
    finally:
        conn.close()


def cli_experience_attach_record(argv):
    # experience-attach-record <event_id> <source_table> <source_id>
    #                          [role] [weight] [source]
    _u = ("사용법: kit_life.sh experience-attach-record <event_id> "
          "<source_table> <source_id> [role] [weight] [source]")
    if len(argv) < 3 or not argv[0] or not argv[1] or not argv[2]:
        _err(_u)
    event_id, source_table, source_id = argv[0], argv[1], argv[2]
    if not str(event_id).isdigit():
        _err(f"event_id는 숫자여야 함: {event_id}")
    if not str(source_id).isdigit():
        _err(f"source_id는 숫자여야 함: {source_id}")
    # GUARD #2: source_table whitelist (D2 code-gate). Zero mutation on reject.
    if source_table not in RECORD_SOURCE_TABLES:
        _err(f"source_table 미허용: {source_table} "
             f"(허용: {', '.join(sorted(RECORD_SOURCE_TABLES))})")
    g = lambda i: argv[i] if i < len(argv) else None
    role = g(3) or 'incidental'
    if role not in _RECORD_EVENT_ROLES:
        _err(f"role 값 오류: {role} (primary/incidental)")
    weight = _opt_num(g(4))
    source = _txt(g(5))
    conn = get_conn()
    try:
        if _event_row(conn, event_id) is None:
            _err(f"event 없음: {event_id}")
        agent = _facade_agent()
        ts = None
        if source_table == 'block':
            # record.ts = EVENT time, never typing time (owner 2026-09-08
            # 13:29 "추가시간과 식사시간이 실제론 다를수있어"): the block's
            # own stamp at its stored grade -- start_at when timed, else the
            # bare date (diet blocks are date-only 557/557; fabricating an
            # instant from a bare day is the 038 fail-open, so the honest
            # date grade rides as-is). The lookup doubles as the existence
            # check: a missing block refuses instead of minting a dangling
            # pointer (no FK backs the polymorphic record).
            brow = conn.execute("SELECT start_at, date FROM block WHERE id=?;",
                                (int(source_id),)).fetchone()
            if brow is None:
                _err(f"block 없음: {source_id}")
            ts = brow[0] or brow[1]
        # cut 3 exception memory: an owner-excluded pair REFUSES here -- an
        # accepted offer must never silently overturn a remembered '빼'.
        # (Only an existing record row can carry a memory, so the lookup is
        # by source identity; a never-recorded source cannot be excluded.)
        xrow = conn.execute(
            "SELECT r.id FROM record r JOIN event_record_exclusion x "
            "ON x.record_id = r.id AND x.event_id=? "
            "WHERE r.source_table=? AND r.source_id=?;",
            (int(event_id), source_table, int(source_id))).fetchone()
        if xrow:
            _err(f"제외로 기억된 쌍: event {event_id} x record {xrow[0]} "
                 f"(해제: experience-unexclude-record {event_id} {xrow[0]})")
        rid = record_upsert(conn, source_table, source_id, ts=ts,
                            owning_agent=agent)
        # on-utterance accrual: link deduped at PK(record_id, event_id).
        conn.execute(
            "INSERT OR IGNORE INTO record_event (record_id, event_id, role, "
            "weight, source) VALUES (?,?,?,?,?);",
            (rid, int(event_id), role, weight, source))
        conn.commit()
        # machine TSV: record_id \t event_id \t role
        print(f"{rid}\t{event_id}\t{role}")
    finally:
        conn.close()


