def _strand_type_hints(conn, domain, owning_agent=None):
    """The derive move's strand types, each with the measures / checks THIS
    install can track (registered tokens; a family row is offered as its
    pattern plus the concrete tokens the user's own logs expand it to)."""
    offered = {c["metric"]: c["label"]
               for c in _metric_choices(conn, domain, owning_agent)}
    registered = {r[0] for r in conn.execute(
        "SELECT metric_token FROM goal_metric_source WHERE (domain IS ? OR "
        "? IS NULL);", (domain, domain)).fetchall()}

    def expand(tokens):
        out = []
        for t in tokens:
            if t.endswith(_FAMILY_SUFFIX):
                if t not in registered:
                    continue
                prefix = t[:-1]
                out.append({"metric": prefix + "<movement>",
                            "label": _METRIC_LABEL_FAMILY.get(
                                prefix, ("%s", ""))[0] % "<movement>"})
                out += [{"metric": m, "label": lab}
                        for m, lab in offered.items() if m.startswith(prefix)]
            elif t in registered:
                out.append({"metric": t, "label": _metric_label(t)[0]})
        return out

    hints = []
    for ty in _STRAND_TYPES:
        h = {"type": ty["type"], "recognize": ty["words"],
             "kind": ty["kind"], "rule": ty["rule"]}
        if ty["kind"] == "measured":
            h["metrics"] = expand(ty.get("metrics") or ())
            if not h["metrics"]:
                continue              # nothing this install can read for it
            concrete = [m["metric"] for m in h["metrics"]
                        if "<" not in m["metric"]]
            h["axis"] = "=" + ",".join(
                concrete if ty.get("require_all") else concrete[:1])
            h["metrics"] += [dict(m, optional=True)
                             for m in expand(ty.get("also") or ())]
        elif ty["kind"] == "practice":
            h["checks"] = expand(ty.get("checks") or ())
            concrete = [m["metric"] for m in h["checks"]
                        if "<" not in m["metric"]]
            h["axis"] = "=" + ",".join(["@practice"] + concrete)
        else:
            h["axis"] = "=@care"
        hints.append(h)
    return hints


def _strand_type_of(text):
    """The first strand type whose words the text carries, or None."""
    for ty in _STRAND_TYPES:
        if text and re.search(ty["words"], str(text), re.I):
            return ty
    return None


# ── archetype hints: the pack's body-ideal table (owner rehearsal
# 2026-09-30 19:40-19:53; pack_health body_ideal_archetypes.json) ─────────
# A strand the user names after a known body ideal ("클래식 피지크같은 x
# 테이퍼", "필라테스의 연결") takes that ideal's picture features and its
# measure set as the DEFAULT. The table is the pack's data, read through the
# same seam as the pack copy -- never an import of pack code:
#     <root>/service/<ns>/body_ideal_archetypes.json
# beside each installed pack's i18n dir (_pack_i18n_dirs: install receipts,
# or KIT_LIFE_PACK_I18N_DIRS). KIT_LIFE_PACK_ARCHETYPES (os.pathsep list of
# table files) REPLACES that discovery -- tests and dev only; set-but-empty =
# no table. No table (or an unreadable one): exactly the behaviour without
# archetypes.
# What the kit reads from a row (everything else is the pack's own record):
#   key, label_ko, words        trigger words (matched space/hyphen-blind on
#                               the strand's name, then its clause; the
#                               LONGEST matching word wins, table order
#                               breaks a tie)
#   family                      'shape' -> a measured strand
#   picture_short_<lang>        the default --picture (<= 40 chars, a noun
#                               phrase; used only when it passes the picture
#                               rule), picture_<lang> + distinguishing = the
#                               features the agent's picture must keep
#   not                         neighbours it must not read as (the X-taper
#                               is not the V-taper)
#   measures.strand_tokens / kit_tokens / kit_readings / missing_tokens
#                               measure candidates in that order, kept only
#                               when registered on this install (a token
#                               registered later appears then, never before)
#   measures.never, else practice.avoid_as_primary entries of the form
#                               "<token>" / "<token> (<why>)"
#                               tokens the strand may never link (Pilates:
#                               the hold share). "<token> as ..." entries
#                               mean "not alone" and are not refused.
ARCHETYPES_ENV = "KIT_LIFE_PACK_ARCHETYPES"
_ARCHETYPE_FILE = "body_ideal_archetypes.json"
_ARCHETYPE_TOKEN_RE = re.compile(r"^([a-z0-9_]+(?:<[a-z]+>)?)(\s*\(.*\))?$")


def _archetype_rows():
    """The archetype rows of every table found, table order. Never
    raises."""
    env = os.environ.get(ARCHETYPES_ENV)
    if env is not None:
        paths = [p for p in env.split(os.pathsep) if p]
    else:
        paths = [os.path.join(os.path.dirname(d), _ARCHETYPE_FILE)
                 for d in _pack_i18n_dirs()]
    rows, seen = [], set()
    for path in paths:
        arch = _i18n_file(path).get("archetypes")
        for r in arch if isinstance(arch, list) else ():
            if isinstance(r, dict) and r.get("key") and \
                    isinstance(r.get("words"), list) and \
                    r["key"] not in seen:
                seen.add(r["key"])
                rows.append(r)
    return rows


def _archetype_norm(text):
    return re.sub(r"[\s\-_·]+", "", str(text or "")).lower()


def _archetype_match(text, rows=None):
    """The row whose longest trigger word the text carries, or None."""
    n = _archetype_norm(text)
    if not n:
        return None
    best, best_len = None, 0
    for r in _archetype_rows() if rows is None else rows:
        for w in r["words"]:
            wn = _archetype_norm(w)
            if wn and wn in n and len(wn) > best_len:
                best, best_len = r, len(wn)
    return best


def _archetype_of(label, clause=None):
    """The archetype a strand is named after: matched on its own name,
    else on its clause of the direction; None with no table."""
    rows = _archetype_rows()
    if not rows:
        return None
    return _archetype_match(label, rows) or _archetype_match(clause, rows)


def _archetype_never(row):
    """Tokens the archetype's strand may never link."""
    ms = row.get("measures") or {}
    if isinstance(ms.get("never"), list):
        return [str(t) for t in ms["never"]]
    out = []
    for e in (row.get("practice") or {}).get("avoid_as_primary") or ():
        m = _ARCHETYPE_TOKEN_RE.match(str(e).strip())
        if m:
            out.append(m.group(1))
    return out


def _archetype_candidates(row):
    ms = row.get("measures") or {}
    out = []
    for field in ("strand_tokens", "kit_tokens", "kit_readings",
                  "missing_tokens"):
        for t in ms.get(field) or ():
            if isinstance(t, str) and t not in out:
                out.append(t)
    return out


def _archetype_picture(row):
    """(default picture or None, the features it must keep)."""
    lang = agent_conf.conf_str("AGENT_LANG", "en")
    pic = row.get("picture_short_%s" % lang)
    if pic and _strand_picture_problem(pic) is not None:
        pic = None
    keep = [row.get("picture_%s" % lang) or row.get("picture_ko")] + \
        list(row.get("distinguishing") or [])
    return pic, [k for k in keep if k]


def _archetype_hint(conn, row, text, domain, owning_agent=None):
    """The default for a strand named after `row`: {archetype, label, kind,
    axis, metrics / checks, never, picture, keep, not}. The kind comes from
    the kit's own strand type for the words (a body shape is measured,
    connection / function are practice), else the row's family. Measures:
    the type's own set first, then the archetype's candidates registered on
    this install, never-tokens dropped."""
    ty = _strand_type_of(text)
    if ty is not None:
        kind = ty["kind"]
    elif row.get("family") == "shape":
        kind = "measured"
    else:
        kind = "practice" if (row.get("practice") or {}).get("picks") \
            else "measured"
    registered = {r[0] for r in conn.execute(
        "SELECT metric_token FROM goal_metric_source WHERE (domain IS ? OR "
        "? IS NULL);", (domain, domain)).fetchall()}
    never = set(_archetype_never(row))
    own = list((ty or {}).get("metrics" if kind == "measured" else "checks")
               or ())
    out = []
    for t in own + _archetype_candidates(row):
        t = re.sub(r"<[a-z]+>$", "*", t)
        if t in never or t in out or t not in registered:
            continue
        is_check = t.endswith(_FAMILY_SUFFIX) or \
            _metric_is_program(conn, t)
        if kind == "measured" and not is_check:
            out.append(t)
        elif kind == "practice" and is_check:
            out.append(t)
    concrete = []
    for t in out:
        if t.endswith(_FAMILY_SUFFIX):
            if kind == "practice":
                concrete += [c["metric"] for c in
                             _metric_choices(conn, domain, owning_agent)
                             if c["metric"].startswith(t[:-1])
                             and c["metric"] not in concrete]
        else:
            concrete.append(t)
    pic, keep = _archetype_picture(row)
    hint = {"archetype": row["key"], "label": row.get("label_ko"),
            "kind": kind,
            "axis": "=" + ",".join((["@practice"] if kind == "practice"
                                    else []) + concrete),
            "never": sorted(never & registered),
            "picture": pic, "keep_in_picture": keep,
            "not": [n.get("archetype") + ": " + n.get("why", "")
                    for n in row.get("not") or ()
                    if isinstance(n, dict) and n.get("archetype")]}
    hint["checks" if kind == "practice" else "metrics"] = [
        {"metric": t if not t.endswith(_FAMILY_SUFFIX)
         else t[:-1] + "<movement>",
         "label": _metric_label(t)[0] if not t.endswith(_FAMILY_SUFFIX)
         else _METRIC_LABEL_FAMILY.get(t[:-1], ("%s", ""))[0]
         % "<movement>"} for t in out]
    return hint


def _archetype_hints(conn, text, domain, owning_agent=None):
    """derive_axes: per clause of the direction that names a known ideal,
    its default ({clause, ...hint}); [] with no table."""
    rows = _archetype_rows()
    if not rows or not text:
        return []
    out = []
    for seg in re.split(r"[.,!?\n]", str(text)):
        seg = " ".join(seg.split())
        row = _archetype_match(seg, rows) if seg else None
        if row is not None:
            h = _archetype_hint(conn, row, seg, domain, owning_agent)
            out.append(dict({"clause": seg}, **h))
    return out


def _check_family(conn, token):
    """True when `token` is a concrete member of a registered workout_sets
    family (max_reps_pullup of max_reps_*) -- a practice strand's check."""
    for (fam,) in conn.execute(
            "SELECT metric_token FROM goal_metric_source WHERE "
            "source_table='workout_sets';").fetchall():
        if fam.endswith(_FAMILY_SUFFIX):
            prefix = fam[:-1]
            if token.startswith(prefix) and \
                    re.fullmatch(r"[a-z0-9_]+", token[len(prefix):] or "-"):
                return True
    return False


def _strand_checks(conn, st, a):
    """The check numbers of a practice / care strand: the pack-computed
    measures linked to it, then the log-read ones axis-add stored."""
    out = [m for m in a["metrics"] if _metric_is_program(conn, m)]
    s = (st.get("strand") or {}).get(a["axis_key"]) or {}
    out += [m for m in (s.get("checks") or []) if m not in out]
    return out


_STRAND_PRACTICE_EXAMPLES = 2


def _strand_practice_words(conn, st, a, why_text=None):
    """(kind, examples) of a practice strand for its measure line. The pack's
    archetype row the strand is named after carries both when it has them
    (practice.kind_<lang>; practice.examples = movement names in the pack's
    order, the first two with a movement.<name> label -- the kit names no
    movement). Else the kit's word for the strand's practice set, else the
    neutral one, and no examples."""
    info = _strand_info(conn, st, a, why_text)
    row = _archetype_of(a["label"], info["clause"]) or {}
    prac = row.get("practice") if isinstance(row.get("practice"), dict) \
        else {}
    lang = agent_conf.conf_str("AGENT_LANG", "en")
    kind = prac.get("kind_%s" % lang)
    if not isinstance(kind, str) or not kind.strip():
        ps = _practice_set_of(a, _said_phrase(why_text, a["label"]),
                              info["qualifier"], info["clause"])
        kind = _move_text("strands_practice_kind.%s" % ps["key"]) \
            if ps is not None else ""
        kind = kind or _move_text("strands_practice_kind")
    examples = []
    for name in prac.get("examples") or ():
        if len(examples) == _STRAND_PRACTICE_EXAMPLES:
            break
        if not isinstance(name, str) or \
                not re.fullmatch(r"[a-z0-9_]+", name):
            continue
        for label in _copy_candidates("movement." + name):
            if label not in examples:
                examples.append(label)
            break
    return kind.strip(), examples


def _strand_measure_text(conn, st, a, why_text=None):
    """What checks one strand, in words: its measures, or the practice (what
    kind of move, one per workout, with the pack's examples) with its check
    numbers, or the care."""
    kind = _strand_kind(conn, st, a)
    sep = _move_text("strands_measure_sep")
    if kind == "measured":
        mets = [m for m in a["metrics"] if not _metric_is_program(conn, m)]
        return sep.join(_metric_labels_grouped(mets))
    if kind == "practice":
        pkind, examples = _strand_practice_words(conn, st, a, why_text)
        checks = _strand_checks(conn, st, a)
        key = "strands_measure.practice" + ("_ex" if examples else "") + \
            ("_check" if checks else "")
        return _move_text(key, kind=pkind, examples=sep.join(examples),
                          checks=sep.join(_metric_labels_grouped(checks)))
    if kind == "care":
        return _move_text("strands_measure.care")
    return _move_text("strands_measure.direction")


def _strands_readback(conn, wid, why_text=None, axes=None):
    """(rows, sig): per strand {axis_key, label, line, sig} -- the line is
    name (qualified) · what checks it · its picture, the sig what one
    strand's confirmation is stored against (a changed measure, picture or
    strand direction asks that strand again) -- and the signature of the
    whole readback (a confirmation stored before the one-strand-per-turn
    walk, strands_confirmed, still holds against it)."""
    st = _move_state(conn, wid)
    if axes is None:
        axes = _user_axes(conn, None, wid)
    if why_text is None:
        why_text = _why_text(conn, wid)
    sw = st.get("strand_why") or {}
    rows = []
    for a in axes:
        info = _strand_info(conn, st, a, why_text)
        line = _move_text(
            "strands_card", label=info["label"],
            measure=_strand_measure_text(conn, st, a, why_text),
            picture=info["picture"] or _move_text("strands_picture_none"))
        if _strand_kind(conn, st, a) == "practice":
            # the moves are not picked yet: the practice step comes later
            line += "\n" + _move_text("strands_practice_later")
        why_of = sw.get(a["axis_key"])
        rows.append({"axis_key": a["axis_key"], "label": info["label"],
                     "line": line,
                     "sig": json.dumps([line, None if why_of is None
                                        else int(why_of)],
                                       ensure_ascii=False)})
    sig = json.dumps([[r["line"] for r in rows],
                      sorted((k, int(v)) for k, v in sw.items())],
                     ensure_ascii=False)
    return rows, sig


def _strands_list_sig(rows):
    """What the one-line strand list was shown against: the names."""
    return json.dumps([r["label"] for r in rows], ensure_ascii=False)


def _strand_pending(st, rows, sig):
    """The first strand not confirmed as it reads now, or None when every
    strand is (or the whole readback was, before the walk)."""
    if st.get("strands_confirmed") == sig:
        return None
    ok = st.get("strands_ok") or {}
    for r in rows:
        if ok.get(r["axis_key"]) != r["sig"]:
            return r
    return None


def _strands_confirm_move(conn, wid, why, axes):
    """The strands read back and confirmed before the interview moves on
    (owner 2026-09-30 19:27), ONE strand per turn (owner 19:39 "세개니까
    하나씩 짚고가도록하자"), or None once every strand is confirmed as it
    reads now. Several strands: the first step opens with their names on one
    line; each step is one strand (a 지향 / 설명 / 측정 card) and one
    keep / fix question; a fix re-asks that strand only. A strand with no
    picture gets it first (silent strand_picture): the readback never shows
    a strand without its picture."""
    st = _move_state(conn, wid)
    for a in axes:
        info = _strand_info(conn, st, a, why.get("text"))
        if not info["picture"]:
            return _strand_picture_move(conn, wid, a, info)
    rows, sig = _strands_readback(conn, wid, why.get("text"), axes)
    cur = _strand_pending(st, rows, sig)
    if cur is None:
        return None
    key = cur["axis_key"]
    by_key = {a["axis_key"]: a for a in axes}
    named = by_key[key]["label"]        # the strand as axis-add knows it
    fix = ["axis-add", "--why-id", str(wid), "--axis",
           "%s=<its measures / @practice,<checks> / @care, the whole new "
           "list>" % named,
           "--picture", "%s=%s" % (named, _STRAND_PICTURE_HINT),
           "(this strand; a new strand = a new --axis + --picture)"]
    routes = {"measure_or_picture_or_new_strand": fix,
              "what_a_strand_is_for": ["axis-direction", key,
                                       "--text", "<the user's words>",
                                       "--label", "<짧은 말>"],
              "whole_direction": ["goal-move-note", "--why-id", str(wid),
                                  "--confirm-why", "change"]}
    strands = [{"axis_key": r["axis_key"], "label": r["label"],
                "metrics": by_key[r["axis_key"]]["metrics"],
                "checks": _strand_checks(conn, st, by_key[r["axis_key"]])}
               for r in rows]
    ok = st.get("strands_ok") or {}
    walk = {"strand": key, "strand_step": rows.index(cur) + 1,
            "strand_of": len(rows),
            "strands_confirmed": [r["axis_key"] for r in rows
                                  if ok.get(r["axis_key"]) == r["sig"]]}
    fixing = st.get("strand_fixing") or {}
    if fixing.get("key") == key and fixing.get("sig") == sig:
        # "고칠 부분 있어요": one open question about THIS strand; the answer
        # goes through a correction verb, which changes its line -> this
        # strand is read back again (the others stay confirmed).
        return _move("ask_strand_fix", why_id=wid,
                     say=_move_text("strands_fix_ask", label=cur["label"]),
                     strands=strands, source_text=why.get("text"),
                     on_answer=routes, then="next", **walk)
    note = ["goal-move-note", "--why-id", str(wid), "--confirm-strands"]
    i, n = rows.index(cur) + 1, len(rows)
    if n == 1:
        body = cur["line"]
    elif st.get("strands_listed") != _strands_list_sig(rows):
        listed = "\n".join(
            [_move_text("strands_list", n=_N_KO.get(n, str(n)))]
            + [_move_text("strands_list_item", label=r["label"])
               for r in rows])
        body = "%s\n\n%s\n%s" % (
            listed, _move_text("strands_walk_first", i=i, n=n), cur["line"])
    else:
        body = "%s\n%s" % (_move_text("strands_walk_step", i=i, n=n),
                            cur["line"])
    say = _move_text("strand_confirm", body=body)
    return _move("confirm_strands", why_id=wid, say=say, narrowed=True,
                 strands=strands, source_text=why.get("text"),
                 choices=[{"pick": "keep",
                           "label": _move_text("strands_keep"),
                           "cmd": note + ["keep", "--strand", key]},
                          {"pick": "fix",
                           "label": _move_text("strands_fix"),
                           "cmd": note + ["fix", "--strand", key]}],
                 # a correction said in the same reply (a measure to add, a
                 # part of the picture missing) needs no button: run the
                 # route, then --next reads this strand back again
                 on_correction=routes, **walk)


def _practice_rec(conn, st, ps, said, why_text):
    """(pick, line) of a set's first recommendation rule that holds."""
    for rule in ps["rec"]:
        if rule[0] == "onesided":
            recs = _safety_records(conn)
            one_sided = [r["site"] for r in recs
                         if r["key"].endswith(("_r", "_l"))
                         or r["site"].split(" ", 1)[0] in ("우측", "좌측")]
            if not one_sided:
                one_sided = [s for s in _safety_sites(st)
                             if s.split(" ", 1)[0] in
                             _CARD_SIDES[:2] + ("우측", "좌측")]
            if one_sided:
                return rule[1], _move_text(
                    rule[2], sites=_sites_joined(one_sided, True),
                    i=_josa(one_sided[-1], "i"))
        elif rule[0] == "safety":
            sites = [r["site"] for r in _safety_records(conn)] or \
                _safety_sites(st)
            if sites:
                return rule[1], _move_text(
                    rule[2], sites=_sites_joined(sites, True),
                    i=_josa(sites[-1], "i"))
        elif rule[0] == "words":
            hit = None
            for src in (said, why_text):
                hit = re.search(rule[1], str(src or ""), re.I)
                if hit:
                    break
            if hit:
                w = hit.group(0)
                return rule[2], _move_text(rule[3], words=w,
                                           reul=_josa(w, "reul"))
        else:
            return rule[1], _move_text(rule[2])
    return ps["picks"][0], ""


def _practice_note(wid, axis_key, words, pick, card):
    return ["goal-move-note", "--why-id", str(wid), "--practice", axis_key,
            "--words", words, "--pick", pick, "--card", card]


def _practice_pick_note(wid, axis_key, picks):
    """The note for any number of picks of a set, in set order: titles and
    card phrases joined by ' · ' (what a pair button carried before
    2.36.2, so a stored pair reads the same; three join the same way)."""
    return _practice_note(
        wid, axis_key,
        " · ".join(_move_text("prac_t." + p) for p in picks),
        ",".join(picks),
        " · ".join(_move_text("card_prac." + p) for p in picks))


# a bare option number in the answer: not part of a longer number, a range
# or a count ("1~2회", "10분", "2세트")
_PRACTICE_NUM_RX = re.compile(
    r"(?<![\d~.])([1-9])(?![\d~.]|\s*(?:회|분|초|주|세트|개|kg|min|x\b))",
    re.I)
# "all of them" said in words: every option of the menu
_PRACTICE_ALL_RX = re.compile(
    r"셋\s*다|세\s*(?:개|가지)\s*(?:다|모두|전부)|전부|모두|"
    r"\ball\s+(?:three|of\s+them)\b", re.I)
# words of an option's copy that name no option (they ride every answer:
# "세션마다", "운동", "1 and 2")
_PRACTICE_SAID_STOP = frozenset((
    "세션", "세션마다", "시작", "동작", "운동", "매번", "같이", "and", "with",
    "the", "per", "one", "move", "session", "start", "finish", "min", "week",
    "together", "to"))


def _practice_picks_said(ps, said, label=None):
    """The picks of set `ps` the user's answer names, in set
    order -- option numbers ("1이랑 2", "1, 3") and words of an option's
    title or card phrase that no other option of the set shares ("호흡이랑
    가동성"); never a word of the strand's own name (`label`: "연결" is the
    strand, not option 1). "셋 다" / "전부" / "all three" names every
    option. No limit on how many (owner 2026-10-01: extra prep time is
    the owner's call, never a reason to refuse); a number past the menu
    names nothing."""
    text = str(said or "").lower()
    picks = ps["picks"]
    hit = set()
    for m in _PRACTICE_NUM_RX.finditer(text):
        n = int(m.group(1))
        if n <= len(picks):
            hit.add(picks[n - 1])
    if _PRACTICE_ALL_RX.search(text):
        hit.update(picks)
    split = re.compile(r"[\s·,/()\-]+")
    skip = set(_PRACTICE_SAID_STOP) | {
        w for w in split.split(str(label or "").lower()) if w}
    words = {}
    for p in picks:
        src = _move_text("prac_t." + p) + " " + _move_text("card_prac." + p)
        words[p] = {w for w in split.split(src.lower())
                    if len(w) >= 2 and w not in skip
                    and not re.search(r"\d", w)}
    for p in picks:
        own = words[p] - set().union(*(words[q] for q in picks if q != p))
        for w in own:
            # a Latin word starts at a word edge ("breath" in "breathing",
            # never "and" in "band"); a Hangul word takes its particle
            rx = (r"\b" + re.escape(w)) if re.match(r"[a-z]", w) \
                else re.escape(w)
            if re.search(rx, text):
                hit.add(p)
                break
    return tuple(p for p in picks if p in hit)


def _strand_picture_line(info):
    return _move_text("frame_picture", axis=info["label"],
                      eun=_josa(info["label"], "eun"),
                      picture=info["picture"],
                      reul=_josa(info["picture"], "reul"))


def _practice_move(conn, st, wid, a, why_text, readback):
    """propose_practice for one strand: its picture (what the strand looks
    like, stored with it), why these options, the options, one question. No
    picture stored -> the silent strand_picture move asks the agent first."""
    info = _strand_info(conn, st, a, why_text)
    if not info["picture"] or not info["clean"]:
        return _strand_picture_move(conn, wid, a, info)
    ql = info["label"]
    said = _said_phrase(why_text, a["label"]) or \
        _said_phrase(info["clause"], a["label"])
    irago = "이라고" if said and _hangul_final(said) else "라고"
    ps = _practice_sets_by_strand(conn, st, wid, why_text).get(a["axis_key"])
    picture = _strand_picture_line(info)
    if ps is None:
        # no known set (or its set is another strand's): the user's own words
        say = (_move_text("prac_open", words=said, irago=irago,
                          axis=ql, eun=_josa(ql, "eun"),
                          reul=_josa(ql, "reul")) if said else
               _move_text("prac_open_plain", axis=ql,
                          eun=_josa(ql, "eun"),
                          reul=_josa(ql, "reul")))
        return _move("propose_practice", why_id=wid, axis_key=a["axis_key"],
                     readback=readback, practice_set=None,
                     say=picture + " " + say, label=ql,
                     on_answer=["goal-move-note", "--why-id", str(wid),
                                "--practice", a["axis_key"], "--words",
                                "<the user's exact words>", "--card",
                                _CARD_PHRASE_HINT % (
                                    _CARD_WORDS_MAX,
                                    "; what is kept every session")])
    rec, rec_line = _practice_rec(conn, st, ps, said, why_text)
    lines = [picture,
             _move_text("prac_lead_framed") + " " +
             (_move_text(ps["frame"], words=said, irago=irago) if said
              else _move_text(ps["frame"].replace(".", "_plain.", 1))), ""]
    # One button per option, its plain title (owner 2026-10-01 09:21: six
    # buttons -- the three plus every pair -- were too many). The
    # recommended one carries (추천) when it fits (_rec_label). Several
    # at once ("1이랑 2", "셋 다") is said in words: on_answer resolves it
    # (--pick-said) to one note, as a pair button used to carry.
    choices = []
    for n, pick in enumerate(ps["picks"], 1):
        t = _move_text("prac_t." + pick)
        lines += _option_lines(n, t, _move_text("prac_d." + pick),
                               _move_text("prac_p." + pick),
                               _move_text("prac_m." + pick),
                               rec=(pick == rec))
        lines.append("")
        choices.append({"pick": pick,
                        "label": _rec_label(t, n) if pick == rec else t,
                        "cmd": _practice_pick_note(wid, a["axis_key"],
                                                   (pick,))})
    lines += [_move_text(k) for k in ps["lines"]]
    if rec_line:
        lines.append(rec_line)
    lines.append(_move_text(ps["two"]))
    lines.append(_move_text(ps["ask"], axis=ql, eun=_josa(ql, "eun")))
    return _move("propose_practice", why_id=wid, axis_key=a["axis_key"],
                 readback=readback, recommend=rec, practice_set=ps["key"],
                 label=ql,
                 decision_axis="simple<->expressive",
                 say="\n".join(lines), choices=choices,
                 on_answer=["goal-move-note", "--why-id", str(wid),
                            "--practice", a["axis_key"], "--pick-said",
                            "<the user's exact words>"])


# ── C: a correction that carries a direction, on a HELD strand ──────────────

def _correct_held_move(conn, st, wid, a, g, c, readback, domain, stage):
    """Three options for a held strand the user pushed on: 'I want more'
    (higher / a number). Never a question back. 'Too wide' is not a move
    (R3, owner 2026-09-27): goal-move-note states the width in one line."""
    m = a["metric"]
    mlabel, unit = _metric_label(m)
    axes = _user_axes(conn, None, wid)
    first = next((x for x in axes if x["phase_order"] == 1), None)
    first_l = first["label"] if first else a["label"]
    mode = _chosen_mode(st, _tension_pair([x for x in axes if x["metric"]]))
    if mode:
        # the phase is called by the chosen mode, not the strand word
        first_l = _move_text("mode_name." + mode)
    note = ["goal-move-note", "--why-id", str(wid), "--correct-done",
            a["axis_key"], "--pick"]
    lines, choices, opts = [], [], []
    horizon = g.get("horizon_date") or _shift_date(
        datetime.date.today().isoformat(), _PHASE_WEEKS * 7)
    weeks = max(1, int(round((datetime.date.fromisoformat(
        str(horizon)[:10]) - datetime.date.today()).days / 7.0)))
    cur = g.get("target_value")
    val = c.get("value")
    prov = "user"
    if val is None and cur is not None:
        # no number said: a conservative +5%, rounded to 5 for big lifts
        val = float(cur) * 1.05
        val = _round_to(val, 5.0) if val >= 100 else round(val, 1)
        prov = "rate_model"
    pair = _tension_pair([x for x in axes if x["metric"]])
    later = None
    if pair:
        later = pair[1] if pair[0]["phase_order"] == 1 else pair[0]
    lines.append(_move_text("held_lead_up", first=first_l, weeks=weeks,
                            mlabel=mlabel, reul=_josa(mlabel, "reul")))
    vs = _fmeas(cur) if cur is not None else ""
    opts.append(("hold", _move_text("held_t_hold", value=vs, unit=unit),
                 _move_text("held_d_hold"), _move_text("held_p_hold"),
                 _move_text("held_m_hold",
                            horizon=_fmt_date_ko(horizon)),
                 note + ["hold"]))
    if val is not None:
        v = _fmeas(val)
        det = {"axis_key": a["axis_key"], "parent_declined": True,
               "kind_confirmed": True, "target_from": prov}
        add = (_goal_add_cmd(domain, g.get("why_id") or wid, m, stage)
               + ["--dir", "up", "--detail",
                  json.dumps(det, ensure_ascii=False),
                  "--baseline", vs or v, "--baseline-as-of",
                  str(g.get("baseline_as_of")
                      or datetime.date.today().isoformat())[:10],
                  "--target", v, "--horizon", str(horizon)[:10],
                  "--title", "%s: %s %s%s" % (a["label"], mlabel, v,
                                              unit),
                  "--rung-state", "tracking"])
        opts.append(("user", _move_text("held_t_user", value=v,
                                        unit=unit,
                                        ro=_josa(v + unit, "ro")),
                     _move_text("held_d_user", first=first_l,
                                mlabel=mlabel, value=v, unit=unit),
                     _move_text("held_p_user"),
                     _move_text("held_m_user", weeks=weeks),
                     [["goal-retire", str(g["id"]), "--reason",
                       "corrected"], add, note + ["user"]]))
    if later is not None:
        retire = [["goal-retire", str(x["id"]), "--reason", "reordered"]
                  for x in _why_goals(conn, wid).values()]
        opts.append(("flip", _move_text("held_t_flip",
                                        later=later["label"]),
                     _move_text("held_d_flip"), _move_text("held_p_flip"),
                     _move_text("held_m_flip", first=first_l,
                                eun=_josa(first_l, "eun")),
                     retire + [["axis-order", "--why-id", str(wid),
                                "--first", later["axis_key"]],
                               note + ["flip"]]))
    rec_line = _move_text("held_rec_up")
    lines.append("")
    for n, (key, t, d, p, mi, cmd) in enumerate(opts, 1):
        lines += _option_lines(n, t, d, p, mi, rec=(n == 1))
        lines.append("")
        choices.append({"pick": key,
                        "label": _rec_label(t, n) if n == 1 else t,
                        "cmd": cmd})
    lines.append(rec_line)
    lines.append(_move_text("held_ask"))
    return _move("correct_held", why_id=wid, axis_key=a["axis_key"],
                 metric=m, correction=c, readback=readback,
                 recommend=opts[0][0], decision_axis="speed<->safety",
                 say="\n".join(lines), choices=choices)


# ── R: restart ("다시 하자") ─────────────────────────────────────────────────
#
# Decisions reopen, facts are re-confirmed, nothing is deleted, and the user
# is never left with zero goals (JOURNEY 7): an unfinished interview is
# archived (its move state under goal_interview_archive_<id>, its staged
# goals archived, its direction retired, its strand links released); a
# finished one's goals STAY ACTIVE, and the restart window stages every new
# write until the new wrap swaps them in one transaction.

_RESTART_KEY = "goal_restart"
_RESTART_ARCHIVE_KEY = "goal_interview_archive_%d"


def _restart_state(conn):
    raw = _config_stored(conn, _RESTART_KEY)
    try:
        st = json.loads(raw) if raw else None
    except (ValueError, TypeError):
        st = None
    return st if isinstance(st, dict) else None


def _goal_archive_row(conn, g, reason):
    """goal-retire's archive path for one goal row (status, audit, criterion
    stamp) on the caller's transaction."""
    detail = {}
    if g.get("detail"):
        try:
            detail = json.loads(g["detail"]) or {}
        except (ValueError, TypeError):
            detail = {}
    detail["retire_reason"] = reason
    now = _utc_now_str()
    conn.execute(
        "UPDATE ledger_goal SET status='archived', rung_state='retired', "
        "focus_state='dormant', detail=?, updated_at=?, version=version+1 "
        "WHERE id=?;", (json.dumps(detail, ensure_ascii=False), now, g["id"]))
    conn.execute(
        "INSERT INTO ledger_audit (ts, kind, goal_ulid, detail) "
        "VALUES (?,?,?,?);",
        (now, "goal_retire", g["ulid"],
         json.dumps({"from_status": g["status"],
                     "from_rung_state": g["rung_state"],
                     "from_focus_state": g["focus_state"],
                     "commitment_kind": g.get("commitment_kind") or "goal",
                     "reason": reason}, ensure_ascii=False)))
    try:
        grow = conn.execute("SELECT id FROM goal WHERE ulid=?;",
                            (g["ulid"],)).fetchone()
    except sqlite3.OperationalError:
        grow = None
    if grow is not None:
        for tbl in ("goal_target", "commitment"):
            try:
                conn.execute(
                    "UPDATE %s SET valid_until=CASE WHEN valid_from >= ? "
                    "THEN strftime('%%Y-%%m-%%dT%%H:%%M:%%SZ', valid_from, "
                    "'+1 second') ELSE ? END WHERE goal_id=? "
                    "AND valid_until IS NULL;" % tbl, (now, now, grow[0]))
            except sqlite3.OperationalError:
                pass


def goal_interview_restart(conn, domain, owning_agent=None, from_="goal"):
    """goal-interview --restart. Returns {say, archived, kept_goal_ids,
    next} -- `next` is the first move of the new interview with the restart
    line in front of its question."""
    if from_ == "program":
        return {"say": _move_text("restart_program"), "archived": [],
                "kept_goal_ids": [], "next": None}
    strand = _strand_whys(conn)
    mains = [w for w in _active_whys(conn, domain, owning_agent)
             if w["why_id"] not in strand]
    prev = _restart_state(conn) or {}
    facts = dict(prev.get("facts") or {})
    kept = list(prev.get("replacing") or [])
    old_whys = list(prev.get("old_whys") or [])
    since_prev = prev.get("at")
    archived = []
    now = _utc_now_str()
    conn.commit()
    conn.execute("BEGIN IMMEDIATE;")
    try:
        for w in mains:
            wid = w["why_id"]
            st = _move_state(conn, wid)
            for k in ("activity", "training"):
                if st.get(k):
                    facts[k] = st[k]
            if (st.get("card") or {}):
                fc = dict(facts.get("card") or {})
                for k in ("activity", "training", "safety"):
                    if st["card"].get(k):
                        fc[k] = st["card"][k]
                facts["card"] = fc
            goals = list(_why_goals(conn, wid).values())
            active = [g for g in goals if g["status"] == "active"]
            if active and not (since_prev and str(w.get("stated_on") or "")
                               .replace(" ", "T") >= since_prev):
                # a finished interview: its goals stay until the new wrap
                kept += [g["id"] for g in active if g["id"] not in kept]
                if wid not in old_whys:
                    old_whys.append(wid)
                continue
            swids = sorted({int(x) for x in
                            (st.get("strand_why") or {}).values()})
            axes = [r[0] for r in conn.execute(
                "SELECT axis_key FROM metric_axis WHERE origin='user' AND "
                "why_id=? ORDER BY axis_rank;", (wid,)).fetchall()]
            links = {}
            if axes:
                for tok, key in conn.execute(
                        "SELECT metric_token, axis_key FROM "
                        "goal_metric_source WHERE axis_key IN (%s);"
                        % ",".join("?" * len(axes)), tuple(axes)).fetchall():
                    links[tok] = key
            staged = [g for g in goals if g["status"] == "proposed"]
            key = _RESTART_ARCHIVE_KEY % wid
            hist = []
            raw = _config_stored(conn, key)
            try:
                hist = json.loads(raw) if raw else []
            except (ValueError, TypeError):
                hist = []
            if not isinstance(hist, list):
                hist = [hist]
            hist.append({"archived_at": now, "why_ids": [wid] + swids,
                         "axes": axes, "links": links,
                         "goals": [{"id": g["id"], "status": g["status"]}
                                   for g in staged],
                         "move_state": st})
            _config_put(conn, key, json.dumps(hist, ensure_ascii=False))
            # the move state itself is renamed away, never deleted
            conn.execute("UPDATE config SET key=? WHERE key=?;",
                         ("%s_state_%s" % (key, now), "goal_move_%d" % wid))
            for g in staged:
                _goal_archive_row(conn, g, "goal-interview-restart")
            if axes:
                conn.execute("UPDATE goal_metric_source SET axis_key=NULL "
                             "WHERE axis_key IN (%s);"
                             % ",".join("?" * len(axes)), tuple(axes))
            for x in [wid] + swids:
                conn.execute("UPDATE life_why SET status='retired', "
                             "updated_at=? WHERE id=? AND status='active';",
                             (now, x))
            archived.append({"why_id": wid, "axes": axes,
                             "goal_ids": [g["id"] for g in staged],
                             "archive_key": key})
        _config_put(conn, _REBUILD_SINCE_KEY, now)
        _config_put(conn, _RESTART_KEY, json.dumps(
            {"at": now, "domain": domain, "replacing": kept,
             "old_whys": old_whys, "facts": facts}, ensure_ascii=False))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    nxt = goal_next_move(conn, domain, owning_agent)
    line = _move_text("restart_line")
    if nxt.get("say"):
        nxt["say"] = "%s\n%s" % (line, nxt["say"])
    return {"say": line, "archived": archived, "kept_goal_ids": kept,
            "next": nxt}


def _restart_commit(conn, wid):
    """At the new wrap: the new goals go active and the kept old ones are
    archived, in ONE transaction (the user never holds zero goals). No-op
    when no restart is pending. Returns {'activated', 'archived'} or None."""
    rs = _restart_state(conn)
    if rs is None:
        return None
    mine = _why_goals(conn, wid).values()
    new_ids = [g["id"] for g in mine if g["status"] == "proposed"]
    _why_goal_ids = {g["id"] for g in mine}
    now = _utc_now_str()
    conn.commit()
    conn.execute("BEGIN IMMEDIATE;")
    try:
        for nid in new_ids:
            conn.execute("UPDATE ledger_goal SET status='active', "
                         "updated_at=?, version=version+1 WHERE id=? AND "
                         "status='proposed';", (now, nid))
        done = []
        for oid in rs.get("replacing") or []:
            row = _goal_fetch(conn, oid)
            if row is None:
                continue
            g = _goal_row_dict(row)
            if g["status"] != "active" or g["id"] in new_ids or \
                    g["id"] in _why_goal_ids:
                continue
            _goal_archive_row(conn, g, "goal-interview-restart")
            done.append(oid)
        for ow in rs.get("old_whys") or []:
            if int(ow) == int(wid):
                continue
            conn.execute("UPDATE life_why SET status='retired', updated_at=? "
                         "WHERE id=? AND status='active';", (now, int(ow)))
        # the restart is over: its window closes, its record is kept
        conn.execute("UPDATE config SET key=? WHERE key=?;",
                     ("%s_done_%s" % (_RESTART_KEY, now), _RESTART_KEY))
        conn.execute("UPDATE config SET key=? WHERE key=?;",
                     ("%s_done_%s" % (_REBUILD_SINCE_KEY, now),
                      _REBUILD_SINCE_KEY))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return {"activated": new_ids, "archived": done}


def _wrap_gate(conn, st, axes, goals, deferred):
    """The strands with no value yet (K7): a wrap is refused while any is
    listed. Value = a goal (or 'next phase'), a practice pick, the care."""
    missing = []
    for a in axes:
        if a["axis_key"] in goals or a["axis_key"] in deferred:
            continue
        kind = _strand_kind(conn, st, a)
        if kind == "practice" and (st.get("practice") or {}).get(
                a["axis_key"]):
            continue
        if kind == "care" and (st.get("care") or {}).get(a["axis_key"]):
            continue
        if kind is None and a.get("domain") != "health":
            continue       # carried as a direction (non-health)
        missing.append(a["axis_key"])
    return missing


def _consult_clock():
    """Now, epoch seconds (tests pin it)."""
    return int(time.time())


def _ts_epoch(ts):
    """Epoch seconds of a stored timestamp: '...Z' is UTC, a bare
    'YYYY-MM-DD HH:MM:SS' (the life_why column default) is local time.
    None when unreadable."""
    t = str(ts or "").strip()
    if not t:
        return None
    try:
        if t.endswith("Z"):
            d = datetime.datetime.strptime(t[:19], "%Y-%m-%dT%H:%M:%S")
            return int(d.replace(tzinfo=timezone.utc).timestamp())
        d = datetime.datetime.strptime(t[:19].replace("T", " "),
                                       "%Y-%m-%d %H:%M:%S")
        return int(time.mktime(d.timetuple()))
    except ValueError:
        return None


def _epoch_iso(sec):
    return datetime.datetime.fromtimestamp(
        int(sec), timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _why_heard_at(why, st):
    """When the user last said or confirmed this direction (epoch), or None.
    A confirmation counts only for the words it confirmed."""
    wc = st.get("why_confirmed") or {}
    heard = [_ts_epoch(why.get("stated_on"))]
    if wc.get("text") == why.get("text"):
        heard.append(_ts_epoch(wc.get("at")))
    heard = [x for x in heard if x is not None]
    return max(heard) if heard else None


def _consult_round_touch(conn, wid, why, st):
    """Advance this direction's consult round (st["round"] = {start, seen});
    returns True when the direction was neither stated nor confirmed inside
    the current round. Writes the move state (commit is the caller's)."""
    now = _consult_clock()
    rnd = st.get("round") or {}
    heard = _why_heard_at(why, st)
    seen = [x for x in (_ts_epoch(rnd.get("seen")), heard) if x is not None]
    last = max(seen) if seen else None
    start = _ts_epoch(rnd.get("start"))
    if last is None or now - last > _CONSULT_ROUND_GAP_S:
        start = now                     # a new round begins with this call
    elif start is None:
        start = last                    # the round the direction began
    st["round"] = {"start": _epoch_iso(start), "seen": _epoch_iso(now)}
    _move_state_put(conn, wid, st)
    return heard is None or heard < start


def _confirm_direction_move(conn, wid, why, axes):
    """The stored direction read back -- the user's own words and the strands
    they became -- then keep or change (one question)."""
    text = " ".join(str(why.get("text") or "").split())
    st = _move_state(conn, wid)
    names = _move_text("card_strand_sep").join(
        _strand_info(conn, st, a, why.get("text"))["label"] for a in axes)
    if len(axes) > 1:
        say = _move_text("direction_confirm", why=text, strands=names,
                         n=_N_KO.get(len(axes), str(len(axes))))
    else:
        say = _move_text("direction_confirm_one", why=text, strands=names,
                         ro=_josa(names, "ro"))
    note = ["goal-move-note", "--why-id", str(wid), "--confirm-why"]
    return _move("confirm_direction", why_id=wid, say=say, narrowed=True,
                 source_text=why.get("text"),
                 choices=[{"pick": "keep",
                           "label": _move_text("direction_keep"),
                           "cmd": note + ["keep"]},
                          {"pick": "change",
                           "label": _move_text("direction_change"),
                           "cmd": note + ["change"]}])


def _ask_direction_move(domain, dom):
    """The opening ask as a move: question, then examples or the
    free-input line with the candidate answers as buttons."""
    body, labels = _goal_opening_body(domain)
    capture = _direction_capture_argv(dom)
    mv = _move("ask_direction", say=body, on_answer=capture)
    if labels:
        mv["choices"] = _label_choices(labels, capture)
    return mv


def _goal_next_move_inner(conn, domain, owning_agent=None, stage=False):
    if owning_agent is None:
        owning_agent = agent_conf.conf_str("GOAL_OWNING_AGENT", None) or None
    dom = domain or "health"
    whys = _active_whys(conn, domain, owning_agent)
    if not whys:
        return _ask_direction_move(domain, dom)
    strand_whys = _strand_whys(conn)
    mains = [w for w in whys if w["why_id"] not in strand_whys]
    if stage:
        # A REBUILD asks the direction fresh (intent is never mined, owner
        # 2026-08-27): only a direction stated since the rebuild began counts.
        # The window opens on the first staged move (or at --restart) and
        # closes at the new wrap / goal-rebuild-commit.
        since = _config_stored(conn, _REBUILD_SINCE_KEY)
        if since is None:
            since = _utc_now_str()
            conn.execute("INSERT INTO config (key, value) VALUES (?, ?) "
                         "ON CONFLICT(key) DO UPDATE SET value=excluded.value;",
                         (_REBUILD_SINCE_KEY, since))
            conn.commit()
        kept_whys = set((_restart_state(conn) or {}).get("old_whys") or [])
        mains = [w for w in mains
                 if str(w.get("stated_on") or "").replace(" ", "T") >= since
                 and w["why_id"] not in kept_whys]
    if not mains:
        return _ask_direction_move(domain, dom)
    why = mains[-1]
    wid = why["why_id"]
    st = _move_state(conn, wid)
    unconfirmed = _consult_round_touch(conn, wid, why, st)
    conn.commit()
    if st.get("why_changing"):
        # "바꿀래요" on the confirm: the new words go through why-pivot (the
        # one path a whole direction changes by); the strands follow it.
        return _move("ask_direction_adjust", why_id=wid, field="why",
                     say=_move_text("direction_change_ask"),
                     source_text=why.get("text"),
                     on_answer=["why-pivot", str(wid), "--text",
                                "<the user's exact words>", "--label",
                                "<short name from the user's words, "
                                "<= %d chars>" % WHY_LABEL_MAX])
    axes = _user_axes(conn, domain, wid)
    if not axes:
        offer = [{"metric": c["metric"], "label": c["label"]}
                 for c in _metric_choices(conn, domain, owning_agent)]
        mv = _move(
            "derive_axes", why_id=wid, source_text=why["text"],
            why_label=why.get("label"),
            metrics=offer,
            on_answer=["axis-add", "--why-id", str(wid), "--axis",
                       "<strand name in the user's words>[=<metric>,...]",
                       "(one --axis per strand the user's words name; a strand "
                       "takes EVERY measure its type needs, comma-joined -- "
                       "see strand_types; a strand with no matching metric "
                       "gets no =)",
                       "--picture",
                       "<the same strand name>=" + _STRAND_PICTURE_HINT,
                       "(one --picture per strand)"],
            # what happens next, so nothing is spoken here: --next reads
            # every strand back (name · what checks it · picture) and asks
            # keep / fix before anything else (confirm_strands)
            then="next")
        # Which measures fit which strand (owner 2026-09-30 19:27): the
        # types this install can track, each with its full measure set.
        mv["strand_types"] = _strand_type_hints(conn, domain, owning_agent)
        # A clause naming a known body ideal (the pack's archetype table):
        # its default measures and picture features (owner rehearsal
        # 2026-09-30). No table -> no key, the types alone.
        arch = _archetype_hints(conn, why["text"], domain, owning_agent)
        if arch:
            mv["archetypes"] = arch
            mv["archetype_rule"] = (
                "A strand named in an `archetypes` clause takes that "
                "entry's `axis` as its default (its type's measures plus "
                "the ideal's own) and never a `never` token. Its --picture "
                "is the entry's `picture` when given; one you write keeps "
                "every `keep_in_picture` feature and must not read as a "
                "`not` neighbour (an X-taper has developed thighs; a "
                "V-taper does not).")
        mv["measure_rule"] = (
            "Match each strand to a strand_types entry by what the user's "
            "clause means, then give it that entry's `axis` -- every measure "
            "listed, not one of them: several metrics on one strand are the "
            "norm when the strand needs them (a body shape = body fat + "
            "skeletal muscle). A practice strand says how it is checked: "
            "@practice plus the entry's check numbers when one fits. Never "
            "a metric outside `metrics` / the entry's lists.")
        # the picture opens the strand's first move (_strand_frame); the
        # kit keeps the qualifier ("크로스핏터같은 기능성" -> 크로스핏식
        # 기능성) from the clause itself
        mv["picture_rule"] = (
            "Per strand, what it looks like as a long-term picture, read "
            "with what qualifies it in the user's clause (크로스핏터같은 "
            "기능성 = crossfit-type work capacity, not balance). Keep EVERY "
            "element the user named or implied for that strand -- none "
            "dropped to shorten it (필라테스의 연결 = the whole body moving "
            "as one AND the small muscles developed evenly). Plain words, "
            "facts, no hype.")
        if dom == "health":
            # K2 + A5: every health strand is one of three kinds, named in
            # the user's OWN word for it (the label is theirs; the kind is
            # the tool's). axis-add refuses an untyped health strand.
            mv["strand_name_rule"] = (
                "Use a short expression exactly from the user's answer. "
                "The same answer must produce the same names. Do not "
                "paraphrase a name such as '이쁜 몸' into '체지방 줄이기'.")
            mv["kind_map"] = {
                "body shape / physique / x-taper": ("=" + ",".join(
                    m for m in ("body_fat_pct", "skeletal_muscle_kg")
                    if m in {o["metric"] for o in offer})),
                "size / bulk / volume": "=skeletal_muscle_kg",
                "lean / defined / body fat": "=body_fat_pct",
                "strength / performance / the big three": "=lift_capacity_kg",
                "function / movement / athleticism":
                    "=@practice[,<check number>]",
                "health / feeling well": "=@care"}
            mv["kinds_required"] = True
        return mv
    goals = _why_goals(conn, wid)
    # ── G0 a direction on record from before this round: read it back and
    # confirm it before anything is asked or proposed on it. Once the
    # direction carries a number the consult is past that point.
    if unconfirmed and not goals:
        return _confirm_direction_move(conn, wid, why, axes)
    # ── the strands read back (name · what checks it · picture) and
    # confirmed before the interview moves on (owner 2026-09-30 19:27). Past
    # the first number or practice pick the consult is beyond that point.
    if not goals and not st.get("practice"):
        smv = _strands_confirm_move(conn, wid, why, axes)
        if smv is not None:
            return smv
    rs = _restart_state(conn)
    if rs and rs.get("facts") and "facts_from" not in st and \
            not st.get("activity"):
        # a restart re-confirms the facts it already knows (one tap)
        st["facts_from"] = rs["facts"]
        _move_state_put(conn, wid, st)
        conn.commit()
    goals = _why_goals(conn, wid)
    readback = []
    # ── G2 what the user does now: ALWAYS one spoken step ──
    # Records and the calendar are its lead, never its answer.
    act_src = conn.execute(
        "SELECT metric_token FROM goal_metric_source WHERE source_table="
        "'workouts' AND domain IS ? LIMIT 1;", (dom,)).fetchone()
    ask_key = "ask_activity.%s" % dom
    if act_src is not None and _move_has(ask_key) and \
            not st.get("activity"):
        ff = st.get("facts_from") or {}
        if ff.get("activity") and not st.get("facts_changed"):
            fcw = ff.get("card") or {}
            act = _card_words(fcw.get("activity") or ff.get("activity"))
            tr = _card_words(fcw.get("training") or ff.get("training"))
            say = (_move_text("confirm_activity_tr", act=act, tr=tr,
                              ro=_josa(tr, "ro")) if tr else
                   _move_text("confirm_activity", act=act,
                              ro=_josa(act, "ro")))
            note = ["goal-move-note", "--why-id", str(wid), "--facts"]
            return _move("confirm_activity", why_id=wid, say=say,
                         narrowed=True,
                         choices=[{"pick": "same",
                                   "label": _move_text("facts.same"),
                                   "cmd": note + ["keep"]},
                                  {"pick": "changed",
                                   "label": _move_text("facts.changed"),
                                   "cmd": note + ["changed"]}])
        since = _shift_date(datetime.date.today().isoformat(),
                            -(_ACTIVITY_WINDOW_DAYS - 1))
        n = conn.execute("SELECT COUNT(*) FROM workouts WHERE date >= ?;",
                         (since,)).fetchone()[0]
        keeping_only = bool(axes) and all(_keeping_spec(conn, a["metric"]) for a in axes)
        say = _move_text("habit.activity") if keeping_only else _move_text(ask_key)
        per = _fmeas(round(n / (_ACTIVITY_WINDOW_DAYS / 7.0), 1)) if n \
            else None
        cal = _calendar_lead(conn, owning_agent) if dom == "health" else None
        if cal and per:
            lead = _move_text("activity_lead_cal", when=cal[0], title=cal[1],
                              i=_josa(cal[1], "i"), per_week=per)
        elif cal:
            lead = _move_text("activity_lead_cal_only", when=cal[0],
                              title=cal[1], i=_josa(cal[1], "i"))
        elif per:
            lead = _move_text("activity_lead", per_week=per)
        else:
            lead = None
        if lead:
            say = "%s %s" % (lead, say)
        capture = ["goal-move-note", "--why-id", str(wid),
                   "--activity", _TYPED_ANSWER,
                   "--card", _CARD_PHRASE_HINT % (
                       _CARD_WORDS_MAX, "; e.g. 주 3~4회 · 헬스장")]
        extra = {}
        if keeping_only:
            # a keeping-only card: the kit's own habit answers as buttons
            extra["choices"] = [
                {"pick": pick, "label": _move_text("habit.activity." + pick),
                 "cmd": ["goal-move-note", "--why-id", str(wid),
                         "--activity", _move_text("habit.activity." + pick)]}
                for pick in ("regular", "occasional", "rest")]
        else:
            # the pack's candidate answers as buttons (owner 2026-10-05)
            labels = _copy_labels("goal.move.%s.buttons" % ask_key)
            if labels:
                say = "%s\n\n%s" % (_drop_examples(say), _free_input_line())
                extra["choices"] = _label_choices(labels, capture)
        return _move("ask_activity", why_id=wid, say=say,
                     on_answer=capture,
                     # G3 is skipped when the answer already says how long
                     if_years_said=["--training", "<those words>",
                                    "--years-band", "<lt1 | 1to3 | 3plus>",
                                    "--history", "<continuous | returner | "
                                    "beginner>"], **extra)
    # Commitment shape is decided before any body or pace turn.
    keeping = [a for a in axes if _keeping_spec(conn, a["metric"])]
    if st.get("habit_probe_pending") and len(keeping) < len(axes):
        st.pop("habit_probe_pending", None)
        _move_state_put(conn, wid, st)
        conn.commit()
    for a in keeping:
        if a["axis_key"] not in goals:
            mv = _habit_number_move(conn, a, wid, dom, stage)
            if mv is not None:
                return mv
            goals = _why_goals(conn, wid)
    if keeping and len(keeping) == len(axes):
        pending = st.get("habit_probe_pending")
        if pending:
            registered_labels = {a["label"] for a in axes}
            if pending not in registered_labels:
                return _move("derive_axes", why_id=wid, source_text=pending,
                             metrics=_metric_choices(conn, domain, owning_agent),
                             strand_types=_strand_type_hints(conn, dom, owning_agent),
                             direction_vocabulary=_commitment_data()["directions"].get(dom, []),
                             on_answer=["axis-add", "--why-id", str(wid),
                                        "--axis", "<strand from answer>=<metrics>",
                                        "--picture", "<strand>=<picture>"], then="next")
        probe = _habit_probe_move(conn, wid, axes, goals, dom, stage)
        if probe:
            return probe
        mv = _wrap_move(conn, dom, wid, axes, goals, st, [], [],
                        None, readback, stage, owning_agent)
        if st.get("habit_probe") == "only" and not st.get("habit_only_said"):
            mv["say"] = _move_text("habit.only_ack") + "\n\n" + (mv.get("say") or "")
            st["habit_only_said"] = True
            _move_state_put(conn, wid, st)
            conn.commit()
        return mv
    # ── G3 how long they have trained: the follow-up inside the same slot
    # (owner 2026-09-26 17:03). Skipped when the activity answer carried it.
    if dom == "health" and st.get("activity") and not st.get("training") \
            and _config_stored(conn, _EXP_KEY) not in _EXP_BANDS:
        # buttons per years band (owner 2026-10-02); the history kind is
        # read from the activity answer just given, so the agent fills it
        note = ["goal-move-note", "--why-id", str(wid)]
        hist_hint = ("<continuous (training now) | returner (resting now, "
                     "trained before) | beginner (never trained)>")
        return _move("ask_training", why_id=wid,
                     say=_move_text("ask_training"),
                     choices=[{"pick": b,
                               "label": _move_text("training." + b),
                               "cmd": note + [
                                   "--training",
                                   _move_text("training." + b),
                                   "--card", _move_text("training." + b),
                                   "--years-band", b,
                                   "--history", hist_hint]}
                              for b in ("lt1", "1to3", "3plus")],
                     on_answer=["goal-move-note", "--why-id", str(wid),
                                "--training", "<the user's exact words>",
                                "--card", _CARD_PHRASE_HINT % (
                                    _CARD_WORDS_MAX, "; e.g. 9년"),
                                "--years-band", "<lt1 | 1to3 | 3plus>",
                                "--history",
                                "<continuous (training now) | returner "
                                "(resting now, trained before) | beginner "
                                "(never trained)>"])
    # A metric the health pack computes from program.yaml (source_table
    # 'program') has no kit reading to ask for or propose from.
    measured = [a for a in axes if a["metric"]
                and not _metric_is_program(conn, a["metric"])]
    declined = set(st.get("unknown") or [])
    # ── the body, and ONLY the body, when nothing is on record: photo, else
    # height + weight. A performance value is never asked (the first
    # session's records fill it).
    body_axes = [a for a in measured if _metric_is_body(conn, a["metric"])]
    need = [a["metric"] for a in body_axes
            if a["metric"] not in declined and a["axis_key"] not in goals
            and _metric_current_value(conn, a["metric"])[0] is None]
    if dom == "health" and not body_axes and \
            not _has_body_reading(conn) and "body_weight" not in declined:
        need = ["body_weight"]
    if need and (_config_stored(conn, "weight_kg") is not None
                 or _metric_current_value(conn, "body_weight")[0]
                 is not None) and (_config_stored(conn, "height_cm")
                                   is not None or "height_cm" in declined):
        need = []
    if "body_weight" in declined:
        need = []
    if need:
        asked = [a["metric"] for a in body_axes] or need
        today = datetime.date.today().isoformat()
        # First body turn: the latest InBody, and nothing else (owner
        # 2026-09-28). Its date is judged on the next --next (freshness).
        no_inbody = ["goal-move-note", "--why-id", str(wid), "--unknown",
                     "inbody"]
        if dom == "health" and _inbody_latest_date(conn) is None and \
                "inbody" not in declined:
            return _move("ask_baseline", why_id=wid, metrics=asked,
                         field="inbody",
                         say=_move_text("ask_baseline.inbody"),
                         on_photo="health-log skill",
                         on_answer="health-log skill (numbers typed)",
                         choices=[{"pick": "none",
                                   "label": _move_text("inbody.none"),
                                   "cmd": no_inbody}],
                         if_still_unknown=no_inbody)
        if _config_stored(conn, "height_cm") is None and \
                "height_cm" not in declined:
            return _move("ask_baseline", why_id=wid, metrics=asked,
                         field="height",
                         say=_move_text("ask_baseline.height"),
                         on_answer=["config-set", "height_cm=<cm>"],
                         if_still_unknown=["goal-move-note", "--why-id",
                                           str(wid), "--unknown",
                                           "height_cm"])
        return _move("ask_baseline", why_id=wid, metrics=asked,
                     field="weight",
                     say=_move_text("ask_baseline.weight"),
                     on_photo="health-log skill",
                     on_answer=[["config-set", "weight_kg=<kg>"],
                                ["log-metric", today, "weight_kg", "<kg>"]],
                     if_still_unknown=["goal-move-note", "--why-id",
                                       str(wid), "--unknown",
                                       "body_weight"])
    if dom == "health" and not _has_body_reading(conn) and \
            "body_weight" in declined and "body_weight_final" not in declined:
        today = datetime.date.today().isoformat()
        return _move("ask_baseline", why_id=wid, field="approx_weight",
                     say=_move_text("ask_baseline.approx"),
                     on_answer=[["config-set", "weight_kg=<approx kg>"],
                                ["log-metric", today, "weight_kg", "<approx kg>"]],
                     if_still_unknown=["goal-move-note", "--why-id",
                                       str(wid), "--unknown",
                                       "body_weight_final"])
    if dom == "health" and any(a["axis_key"] not in goals for a in measured):
        fresh_mv = _inbody_freshness_move(conn, wid, st)
        if fresh_mv is not None:
            return fresh_mv
    if dom == "health" and _fat_free_mass(conn)[0] is None and \
            all(_metric_current_value(conn, m)[0] is None
                for m in ("body_fat_pct", "skeletal_muscle_kg")):
        missing = [k for k in ("age", "sex") if not _config_stored(conn, k)]
        # one value per message: age, then sex
        if missing and missing[0] == "age":
            return _move("ask_demographics", why_id=wid, field="age",
                         say=_move_text("ask_demographics.age"),
                         on_answer=["config-set", "age=<age>"])
        if missing:
            return _move("ask_demographics", why_id=wid, field="sex",
                         say=_move_text("ask_demographics.sex"),
                         choices=[{"pick": x,
                                   "label": _move_text("sex." + x),
                                   "cmd": ["config-set", "sex=%s" % x]}
                                  for x in ("male", "female")],
                         on_answer=["config-set", "sex=<male|female>"])
    # ── G4 safety before the order and before any number (health). With
    # rows on record: a one-tap re-check of what is written.
    if dom == "health" and "safety" not in st and any(
            a["axis_key"] not in goals for a in measured):
        some = {"pick": "some", "label": _move_text("safety.some"),
                "cmd": ["goal-move-note", "--why-id", str(wid),
                        "--safety", "<the user's exact words>",
                        "--card", _CARD_PHRASE_HINT % (
                            _CARD_SAFETY_MAX, "; the sites and what "
                            "happens, ' · ' between sites; e.g. 우측 "
                            "무릎 가끔 시큰 · 우측 어깨 가끔 불편")]}
        on_site = ["constraint-add", "--class", "safety", "--key",
                   "injury_<site>[_l|_r]", "--value",
                   "<the user's exact words>", "--source", "interview"]
        recs = _safety_records(conn)
        if recs:
            some = dict(some, pick="changed",
                        label=_move_text("safety.changed"))
            sites = _sites_joined([r["site"] for r in recs])
            return _move(
                "ask_safety", why_id=wid, readback=readback, narrowed=True,
                records=[r["key"] for r in recs],
                say=_move_text("ask_safety_records", sites=sites,
                               i=_josa(sites, "i")),
                choices=[{"pick": "same", "label": _move_text("safety.same"),
                          "cmd": ["goal-move-note", "--why-id", str(wid),
                                  "--safety", "records"]}, some],
                on_site=on_site)
        return _move(
            "ask_safety", why_id=wid, readback=readback,
            say=_move_text("ask_safety"),
            choices=[{"pick": "none", "label": _move_text("safety.none"),
                      "cmd": ["goal-move-note", "--why-id", str(wid),
                              "--safety", "none"]}, some],
            on_site=on_site)
    # ── G5 strands that pull apart: ORDER before any number ──
    pair = _tension_pair(measured)
    if pair and pair[0]["phase_order"] is None and \
            pair[1]["phase_order"] is None:
        return _order_move(conn, wid, pair, readback)
    pair, deferred, grow_later, held_keys, together = _phase_split(
        conn, axes, measured)
    # ── the held strands are written by the order answer; a store that
    # got its order some other way is filled here (same writes).
    if held_keys and any(k not in goals for k in held_keys):
        for cmd in _order_fill_cmds(conn, wid, stage):
            _run_verb(cmd)
        goals = _why_goals(conn, wid)
    # ── R1 the performance strand is never a turn: a store that reached
    # here without the order answer writing it is filled the same way.
    if any(_is_progression(conn, a) and a["axis_key"] not in goals
           for a in measured):
        for cmd in _lift_fill_cmds(conn, wid, stage):
            _run_verb(cmd)
        goals = _why_goals(conn, wid)
    # ── C: a correction with a direction re-proposes, never re-asks ──
    for key, c in (st.get("correct") or {}).items():
        a = next((x for x in measured if x["axis_key"] == key), None)
        if a is None:
            continue
        g = goals.get(key)
        if _is_progression_goal(g):
            continue        # R1: answered at note time, never re-proposed
        if g is not None and _detail_get(g.get("detail"), "phase") == \
                "maintain":
            return _correct_held_move(conn, st, wid, a, g, c, readback,
                                      domain, stage)
        mv = _proposal(conn, a, bool(together and pair and a in pair),
                       stage, domain, wid, correction=c, readback=readback)
        mv["why_id"] = wid
        return mv
    # ── G6 the phase's numbers: body strands first, then the others ──
    todo = [a for a in sorted(measured, key=lambda x: (x["phase_order"] or 99,
                                                       x["rank"]))
            if a["axis_key"] not in deferred and a["axis_key"] not in goals]
    todo.sort(key=lambda x: 0 if _metric_is_body(conn, x["metric"]) else 1)
    for a in todo:
        if dom != "health" and not _metric_is_body(conn, a["metric"]):
            fz = _feasibility_move(conn, measured, goals, st, wid, readback)
            if fz is not None:
                return fz
        wish = st.get("direction_wish") if dom == "health" else None
        pace_hint = None
        if wish and not any(_detail_get(g.get("detail"), "pace") is not None
                            for g in goals.values()):
            pace_hint = _wish_pace_hint(wish)
        info = _strand_info(conn, st, a, why.get("text"))
        mv = _proposal(conn, a, bool(together and pair and a in pair),
                       stage, domain, wid, correction=pace_hint,
                       readback=readback, frame=info)
        if mv["kind"] == "propose_pace" and \
                (not info["picture"] or not info["clean"]):
            # the strand's first number never goes out unframed
            return _strand_picture_move(conn, wid, a, info)
        if dom == "health" and st.get("goal_mode") and \
                not any(g.get("target_value") is not None for g in goals.values()
                        if _detail_get(g.get("detail"), "pace") is not None):
            line = _move_text("mode_chosen", name=_move_text(
                "mode_name." + st["goal_mode"]))
            if st["goal_mode"] == "recomp" and \
                    _config_stored(conn, _EXP_KEY) == "3plus":
                line += " " + _move_text("muscle_experienced")
            if mv.get("say"):
                # after the strand's framing: the picture opens the message
                head = "\n".join(mv["frame"]) + "\n\n" \
                    if mv.get("frame") else ""
                mv["say"] = head + line + "\n" + mv["say"][len(head):]
        mv["why_id"] = wid
        if not mv.get("readback"):
            mv["readback"] = readback
        return mv
    if dom == "health":
        st = _sync_diet_target(conn, wid, st, goals)
    if dom != "health":
        fz = _feasibility_move(conn, measured, goals, st, wid, readback)
        if fz is not None:
            return fz
    # ── G7 the strands with no reading of their own (health): a practice
    # every session keeps -- three proposals (A8).
    if dom == "health":
        for a in _card_items_order(conn, st, axes):
            if _strand_kind(conn, st, a) == "practice" and \
                    a["axis_key"] not in goals and \
                    not (st.get("practice") or {}).get(a["axis_key"]):
                mv = _practice_move(conn, st, wid, a, why.get("text"),
                                    readback)
                if st.get("diet_target"):
                    mv["say"] = _diet_say(st["diet_target"], conn) + "\n\n" + mv["say"]
                return mv
        # ── the care outside the lifts is HOW, the agent's (D1): the tool
        # fills it and the wrap states it (K7) -- never a turn.
        filled = False
        for a in axes:
            if _strand_kind(conn, st, a) == "care" and \
                    not (st.get("care") or {}).get(a["axis_key"]):
                care = dict(st.get("care") or {})
                care[a["axis_key"]] = "yes"
                st["care"] = care
                st["care_auto"] = sorted(set(st.get("care_auto") or [])
                                         | {a["axis_key"]})
                filled = True
        if filled:
            _move_state_put(conn, wid, st)
            _config_put(conn, _CARE_CONFIG_KEY, ",".join(_CARE_KEYS))
            conn.commit()
    return _wrap_move(conn, dom, wid, axes, goals, st, deferred, grow_later,
                      pair, readback, stage, owning_agent)


def _fat_basis(conn, wid):
    """What the fat side of the first phase was chosen from, exposed (the
    strand framing says it): {side: deficit|surplus|None, basis:
    body_fat|aim|None, bf, thr, sex, aim}."""
    sex = _config_stored(conn, "sex")
    threshold = _ORDER_DEFICIT_FIRST_BF.get(sex)
    judged = metric_judged(conn, "body_fat_pct")
    if threshold is not None and judged.get("n"):
        return {"side": "deficit" if judged["mean"] >= threshold
                else "surplus", "basis": "body_fat",
                "bf": judged["mean"], "thr": threshold, "sex": sex}
    row = conn.execute("SELECT text FROM life_why WHERE id=?;",
                       (wid,)).fetchone()
    aim = str(row[0] if row else "")
    if re.search("줄이|빼|감량|선명|날씬", aim):
        return {"side": "deficit", "basis": "aim", "aim": aim}
    if re.search("늘리|키우|볼륨|벌크", aim):
        return {"side": "surplus", "basis": "aim", "aim": aim}
    return {"side": None, "basis": None}


def _fat_recommendation(conn, wid):
    """Measured body fat against the declared sex baseline, else stated aim."""
    return _fat_basis(conn, wid)["side"]


def _strand_frame(conn, wid, st, a, info, m, dir_, weeks):
    """The two lines in front of a strand's first number (owner 2026-09-29
    13:00): what the strand looks like (its stored picture), then that the
    picture stays the long-term direction and this phase's first goal is
    this metric's move BECAUSE of what the kit chose it from -- the user's
    body fat against the sex baseline, the aim words, the chosen order, or
    (no data reason) the plain default."""
    T = _move_text
    ml = _card_short(m)
    verb = T("verb." + dir_)
    long_line = T("frame_long", weeks=weeks, mlabel=ml,
                  reul=_josa(ml, "reul"), verb=verb)
    fb = _fat_basis(conn, wid)
    reason, why_key = None, None
    if fb["basis"] == "body_fat" and m in ("body_fat_pct", "body_weight",
                                           "skeletal_muscle_kg"):
        pct = _fmeas(round(fb["bf"], 1)) + "%"
        sx = T("direction_sex." + fb["sex"])
        kw = dict(pct=pct, thr=_fmeas(fb["thr"]), sex=sx,
                  i=_josa(pct, "i"), eun=_josa(pct, "eun"))
        if dir_ == "down" and m != "skeletal_muscle_kg":
            why_key = ("fat_high" if fb["side"] == "deficit"
                       else "fat_low_down")
        elif dir_ == "up" and m == "skeletal_muscle_kg" and \
                fb["side"] == "surplus":
            why_key = "fat_low_up"
        if why_key:
            reason = T("frame_why." + why_key, **kw)
    if reason is None and fb["basis"] == "aim" and \
            (fb["side"] == "deficit") == (dir_ == "down"):
        aim = _aim_clause(fb["aim"])
        why_key = "aim"
        reason = T("frame_why.aim", aim=aim,
                   irago="이라고" if _hangul_final(aim) else "라고")
    if reason is None and st.get("goal_mode"):
        name = T("mode_name." + st["goal_mode"])
        why_key = "order"
        reason = T("frame_why.order", name=name, ro=_josa(name, "ro"),
                   mlabel=ml, eun=_josa(ml, "eun"))
    if reason is None:
        why_key = "default"
        reason = T("frame_why.default", axis=info["label"], mlabel=ml,
                   i=_josa(ml, "i"))
    basis = {"why": why_key, "picture": info["picture"],
             "label": info["label"]}
    if why_key in ("fat_high", "fat_low_down", "fat_low_up"):
        basis.update(body_fat=round(fb["bf"], 1), threshold=fb["thr"],
                     sex=fb["sex"])
    return [_strand_picture_line(info), long_line + " " + reason], basis


def _recommended_mode(conn, fat_recommendation):
    return "cut" if fat_recommendation == "deficit" else "lean_bulk"


# The words of a stated aim that pick the fat action (_direction_mode); the
# no-body proposal quotes the clause that matched.
_AIM_LESS = "촬영|사진|감량|빼|줄이|선명|날씬"
_AIM_MORE = "벌크|많이 키우|크게 키우"
_AIM_SOME = "키우|늘리|근육|볼륨"
_DOWN_MODES = ("cut", "recomp")


def _direction_mode(conn, wid, wish=None):
    """The internal 2x2 rule: fat action x muscle action."""
    recommendation = _fat_recommendation(conn, wid)
    band = _config_stored(conn, _EXP_KEY)
    aim = str(wish or conn.execute(
        "SELECT text FROM life_why WHERE id=?", (wid,)).fetchone()[0])
    if not wish and recommendation:
        fat = "less" if recommendation == "deficit" else "some"
    elif re.search(_AIM_LESS, aim):
        fat = "less"
    elif re.search(_AIM_MORE, aim):
        fat = "more"
    elif re.search(_AIM_SOME, aim):
        fat = "some"
    else:
        fat = "less" if recommendation == "deficit" else "some"
    if wish and re.search("지키|유지", wish):
        muscle = "hold"
    elif fat == "less" and (not re.search("근육|키우|늘리", aim) or
                            (band == "3plus" and not wish)):
        muscle = "hold"
    else:
        muscle = "grow"
    if fat == "less":
        return "cut" if muscle == "hold" else "recomp"
    return "bulk" if fat == "more" else "lean_bulk"


def _wish_pace_hint(wish):
    """The pace correction a short-term wish carries, else None."""
    if re.search("두 달|2개월|8주", wish or ""):
        return {"toward": "shorter"}
    if re.search("천천히|여유", wish or ""):
        return {"toward": "slower"}
    if re.search("빠르게|빨리", wish or ""):
        return {"toward": "faster"}
    return None


# The fixed marks of the direction proposal's four section heads (owner
# 2026-09-27 18:25). Rendered by the code in front of the head copy, never
# part of a copy table (the consult copy stays emoji-free, _MOVE_EMOJI_RE).
_DIRECTION_MARKS = {"what": "\U0001f3af", "amount": "\U0001f35a",
                    "why": "\U0001f4a1", "next": "\u27a1\ufe0f"}


# The food a daily kcal change is pictured as (direction proposal): one bowl
# of cooked white rice ~= 300 kcal (210 g; the common packaged bowl reads
# 300-310 kcal), counted in half bowls. Under _FOOD_SNACK_BELOW_KCAL a half
# bowl would overstate it, so the softer snack picture is used; past
# _RICE_BOWL_HALVES_MAX the picture is dropped.
_RICE_BOWL_KCAL = 300.0
_RICE_BOWL_HALVES_MAX = 6
_FOOD_SNACK_BELOW_KCAL = 100


def _food_picture(lo, hi):
    """The rice-bowl picture of a daily kcal span ('' when misleading)."""
    def halves(kcal):
        return int(float(kcal) / (_RICE_BOWL_KCAL / 2.0) + 0.5)
    if hi < _FOOD_SNACK_BELOW_KCAL:
        return _move_text("direction_food_snack") if hi > 0 else ""
    top = halves(hi)
    if top > _RICE_BOWL_HALVES_MAX:
        return ""
    if lo < _FOOD_SNACK_BELOW_KCAL:
        return _move_text("direction_food_snack_range",
                          hi=_move_text("direction_bowl.%d" % top))
    low = max(1, halves(lo))
    if low == top:
        return _move_text("direction_food_one",
                          n=_move_text("direction_bowl.%d" % top))
    return _move_text("direction_food_range",
                      lo=_move_text("direction_bowl.%d" % low),
                      hi=_move_text("direction_bowl.%d" % top))


def _direction_kcal(conn, wid, pair, mode):
    """The daily kcal change the direction proposal previews: the slowest ..
    fastest option the NEXT pace move builds for this mode (same strand, same
    wish correction, same cap/floor -- _pace_options), so the two messages
    never disagree. None when that strand has no reading yet.
    bound = the kcal limit (standing cap / muscle floor) that removed an
    option, else None."""
    down = mode in _DOWN_MODES
    axis = pair[0] if down else pair[1]
    if _metric_current_value(conn, axis["metric"])[0] is None:
        return None
    hint = _wish_pace_hint(_move_state(conn, wid).get("direction_wish"))
    po = _pace_options(conn, axis, mode == "recomp", wid, correction=hint)
    if down:
        kcal = [o["kcal"] for o in po["opts"] if o.get("kcal") is not None]
    else:
        kcal = [_surplus_kcal(mode, o["pace"]) for o in po["opts"]
                if o.get("pace")]
    if not kcal:
        return None
    limits = []
    if po["dropped"] and po["cap"] is not None:
        limits.append(po["cap"])
    if po["floored"] and po["floor"]:
        limits.append(po["floor"]["max_deficit"])
    return {"lo": min(kcal), "hi": max(kcal),
            "dir": "down" if down else "up",
            "bound": int(round(min(limits))) if limits else None}


def _aim_clause(text):
    """The clause of a stated aim that picked the direction (quoted when
    there is no body reading), else its first clause."""
    parts = [x.strip() for x in re.split(r"[.!?,\n]", str(text or ""))
             if x.strip()]
    for rx in (_AIM_LESS, _AIM_MORE, _AIM_SOME):
        hit = next((x for x in parts if re.search(rx, x)), None)
        if hit:
            return hit
    return parts[0] if parts else str(text or "").strip()


def _order_move(conn, wid, pair, readback):
    """One proposed direction in four sections -- what it is, how much the
    daily intake moves (the next pace move's own numbers), why (each fact
    with what it changed), what comes after -- then the question."""
    T = _move_text
    st = _move_state(conn, wid)
    note = ["goal-move-note", "--why-id", str(wid)]
    if st.get("direction_adjusting"):
        return _move("ask_direction_adjust", why_id=wid, readback=readback,
                     say=T("direction_adjust_ask"),
                     on_answer=note + ["--direction-wish",
                                       "<the user's exact words>"])
    wish = st.get("direction_wish")
    mode = _direction_mode(conn, wid, wish)
    name = T("mode_name." + mode)
    changed = bool(wish) and mode != _direction_mode(conn, wid)
    jf = metric_judged(conn, "body_fat_pct")
    body = bool(jf.get("n"))
    sex = _config_stored(conn, "sex")
    threshold = _ORDER_DEFICIT_FIRST_BF.get(sex)
    band = _config_stored(conn, _EXP_KEY)
    dir_ = "down" if mode in _DOWN_MODES else "up"

    def bullet(line):
        return T("direction_bullet", line=line)
    # what this phase is
    def head(mark, line):
        return "%s %s" % (_DIRECTION_MARKS[mark], line)
    sections = [[head("what", T("direction_head_changed" if changed
                                else "direction_head", name=name,
                                reul=_josa(name, "reul"),
                                ro=_josa(name, "ro"))),
                 T("direction_desc." + mode)]]
    # how much the daily intake moves
    amount = [head("amount", T("direction_amount_head." + dir_))]
    kc = _direction_kcal(conn, wid, pair, mode) if body else None
    if kc is None:
        amount.append(T("direction_amount_none." + dir_))
    else:
        span = str(kc["lo"]) if kc["lo"] == kc["hi"] else \
            "%d~%d" % (kc["lo"], kc["hi"])
        if kc["hi"] <= 0:
            line = T("direction_amount_zero")
        elif mode == "recomp":
            line = T("direction_amount_near", span=span, unit="kcal")
        else:
            line = T("direction_amount." + dir_, span=span, unit="kcal")
            food = _food_picture(kc["lo"], kc["hi"])
            if food:
                line += " " + food
        amount.append(bullet(line))
        if kc["bound"] is not None:
            cap = "%dkcal" % kc["bound"]
            amount.append(bullet(T("direction_cap." + dir_, cap=cap,
                                   i=_josa(cap, "i"))))
        amount.append(bullet(T("direction_amount_then")))
    sections.append(amount)
    # why: each fact with what it changed
    why = [head("why", T("direction_why_head_changed" if changed
                         else "direction_why_head", name=name,
                         ro=_josa(name, "ro")))]
    if not body:
        aim = wish or conn.execute("SELECT text FROM life_why WHERE id=?",
                                   (wid,)).fetchone()[0]
        why += [bullet(T("direction_why_nobody", aim=_aim_clause(aim))),
                bullet(T("direction_why_nobody_then"))]
    else:
        if threshold is None:
            why.append(bullet(T("direction_no_baseline")))
        else:
            side = "high" if jf["mean"] >= threshold else "low"
            one = jf["n_mean"] == 1
            sx = T("direction_sex." + sex)
            why.append(bullet(T("direction_why_fat%s.%s"
                                % ("_1" if one else "", side),
                                bf=_fmeas(jf["mean"]), thr=_fmeas(threshold),
                                as_of=_fmt_date_ko(jf["as_of"]), sex=sx,
                                eun=_josa(sx, "eun"))))
        years = (_card_words((st.get("card") or {}).get("training")) or
                 _card_words(st.get("training")) or
                 T("exp_band." + str(band or "")))
        if years and band in _EXP_BANDS:
            exp = band == "3plus"
            if mode == "cut":
                how = "hold" if exp else "hold_new"
            elif not exp:
                how = "grow_new"
            else:
                how = "recomp_exp" if mode == "recomp" else "grow_exp"
            why.append(bullet(T("direction_why_years." + how, years=years)))
    if wish:
        hint = (_wish_pace_hint(wish) or {}).get("toward")
        if changed:
            line = T("direction_why_wish.mode", wish=wish, name=name,
                     ro=_josa(name, "ro"))
            if hint:
                line += " " + T("direction_why_wish_also." + hint)
        elif hint:
            line = T("direction_why_wish." + hint, wish=wish)
        else:
            line = T("direction_why_wish.same", wish=wish, name=name,
                     i=_josa(name, "i"))
        why.append(bullet(line))
    sections.append(why)
    # what comes after (only once a reading grounds the phase)
    if body:
        sections.append([head("next", T("direction_next_head")),
                         T("direction_next." + mode)])
    say = "\n\n".join("\n".join(x for x in sec if x) for sec in sections) + \
        "\n\n" + T("direction_ask")
    return _move("order_choice", why_id=wid, readback=readback,
                 recommend=mode, say=say,
                 choices=[{"pick": "yes", "label": T("direction_yes"),
                           "cmd": ["axis-order", "--why-id", str(wid),
                                   "--mode", mode]},
                          {"pick": "adjust", "label": T("direction_adjust"),
                           "cmd": note + ["--direction-adjust"]}],
                 on_answer=note + ["--direction-wish",
                                   "<the user's exact words>"])

def _wrap_move(conn, dom, wid, axes, goals, st, deferred, grow_later, pair,
               readback, stage, owning_agent):
    """G8 wrap: ONE message (A2) -- the full card, one wrap line, and (with
    the program consult installed) the transition line (A3). The program's
    first question is the pack's: it appends it to `say` in the same
    message, reading `handoff` (contract below)."""
    missing = _wrap_gate(conn, st, axes, goals, deferred)
    if missing:
        # K7 by construction the moves above fill every strand; a strand the
        # tool cannot fill is named, never wrapped over.
        return _move("measure_first", why_id=wid, axis_key=missing[0],
                     say=None, then="next", wrap_gate=missing,
                     on_proceed=None)
    committed = _restart_commit(conn, wid) if stage else None
    if committed:
        goals = _why_goals(conn, wid)
    # A --scope rebuild (no restart) closes with goal-rebuild-commit.  Its
    # two id lists are the kit's to fill, not the agent's to look up (live
    # 2026-09-30: a command with a slot the agent must research stalls the
    # consult): the proposed rows this direction wrote, and the active rows
    # in scope they replace.  The verb still refuses an unfinished walk.
    rebuild_commit = None
    if stage and not committed:
        mine = {g["id"] for g in goals.values()}
        new_ids = [g["id"] for g in goals.values()
                   if g.get("status") == "proposed"]
        old_ids = [g["id"] for g in _active_goals(conn, dom, owning_agent)
                   if g["id"] not in mine]
        if new_ids and old_ids:
            rebuild_commit = ["goal-rebuild-commit", "--replacing",
                              ",".join(str(i) for i in old_ids), "--with",
                              ",".join(str(i) for i in new_ids)]
    parts = [_move_text("wrap_done")]
    if st.get("diet_target") and not any(
            _strand_kind(conn, st, a) == "practice" for a in axes):
        parts.insert(0, _diet_say(st["diet_target"], conn))
    if not any(_detail_get(g.get("detail"), "pace") is not None
               for g in goals.values()):
        # R1: no pace message spoke the progression line -> the wrap does
        lift = _lift_statement(conn, wid)
        if lift:
            parts.append(lift)
    care_axes = [a for a in axes if _strand_kind(conn, st, a) == "care"
                 and (st.get("care") or {}).get(a["axis_key"]) == "yes"]
    if care_axes:
        recs = _safety_records(conn)
        sites = [r["site"] for r in recs] or _safety_sites(st)
        saf = (st.get("safety") or {}).get("text")
        if saf == "none":
            sites = []
        ca = care_axes[0]["label"]
        parts.append(_move_text(
            "wrap_care", axis=ca, eun=_josa(ca, "eun"),
            sites=(_move_text("care_sites", sites=_sites_joined(sites, True))
                   if sites else "")))
    horizons = sorted(
        str(g["horizon_date"])[:10] for k, g in goals.items()
        if g.get("horizon_date") and g.get("target_value") is not None
        and _detail_get(g.get("detail"), "phase") != "maintain")
    later = [a["label"] for a in axes
             if a["axis_key"] in deferred or a["axis_key"] in grow_later]
    if horizons:
        hd = datetime.date.fromisoformat(horizons[0])
        date = _move_text("wrap_date", m=hd.month, d=hd.day)
        parts.append(_move_text("wrap_next_phase", date=date,
                                label=" · ".join(later)) if later
                     else _move_text("wrap_next_review", date=date))
    else:
        parts.append(_move_text("wrap_next_open"))
    say = " ".join(parts)
    to_program = dom == "health" and _health_pack_installed()
    if to_program:
        say = "%s\n\n%s" % (say, _move_text("wrap_transition"))
    order_line, first = (_order_mode_line(st, pair, False) if pair
                         else (None, None))
    cw = st.get("card") or {}
    recs = _safety_records(conn)
    handoff = {
        # the pack appends its first program question (A4) to `say`,
        # separated by a blank line -- ONE message; the program card opens
        # from the NEXT message.
        "append": "program_first_question" if to_program else None,
        "calendar_line": calendar_line(conn, owning_agent),
        "calendar": calendar_windows(conn, owning_agent),
        "order_line": order_line,
        "goal_mode": st.get("goal_mode"),
        "diet": st.get("diet_target"),
        "first_axis": first["axis_key"] if first else None,
        "horizon": horizons[0] if horizons else None,
        "safety_card": (_card_sites_uniq(cw.get("safety"), conn)
                        or (" · ".join(_uniq(r["site"] for r in recs))
                            if recs else None)),
        "practice": dict(st.get("practice_pick") or {}),
        # R1: the performance strands the pack progresses every session
        # (key -> rule, baseline for reference, deficit flag, stretch).
        "progression": _progression_handoff(conn, wid, goals),
        "activity": {"words": st.get("activity"),
                     "card": cw.get("activity")},
        "training_band": _config_stored(conn, _EXP_KEY),
        "measure": sorted({g["metric"] for g in goals.values()
                           if g.get("metric")
                           and _metric_is_body(conn, g["metric"])}),
    }
    # a next consult follows -> the wrap never ends on a bare statement:
    # `go` = the pack's next move (its first program question).
    # The pack's own fold (program-plan) speaks its first question instead
    # and drops this.
    choices = ([{"pick": "go", "label": _move_text("wrap_go"),
                 "then": "pack_next"}] if to_program else [])
    return _move("wrap", why_id=wid, readback=readback, say=say,
                 choices=choices,
                 goal_ids=[g["id"] for g in goals.values()],
                 care_filled=list(st.get("care_auto") or []),
                 restart_commit=committed, rebuild_commit=rebuild_commit,
                 handoff=handoff)


# ── axis-add / axis-order / goal-move-note: the write half of the moves ──────

_AXIS_LABEL_MAX = 12


def axis_add(conn, why_id, specs, owning_agent=None, pictures=None):
    """Create the user's strands for one direction. specs: [(label, [metric])].
    pictures: {label: phrase} -- what each strand looks like as a long-term
    picture (agent-given, noun form); stored with the strand together with
    its clause of the direction and the qualifier cut from it.

    Idempotent per (why, label): re-running re-links metrics, never duplicates.
    Returns {'axes': [...], 'say': <direction + strands readback>} or
    {'error': ...}."""
    picture_of = dict(pictures or {})
    labels_asked = [x[0] for x in specs]
    pictures = [picture_of.get(str(x[0]).strip()) for x in specs]
    w = conn.execute("SELECT id, domain, label, status FROM life_why "
                     "WHERE id=?;", (int(why_id),)).fetchone()
    if w is None or w[3] != "active":
        return {"error": "why %s is not an active direction" % why_id}
    wid, domain, wlabel = w[0], w[1], w[2]
    # A repeated answer reuses its first names in rank order. Prior strands
    # remain in metric_axis after a restart, so model phrasing cannot rename
    # the same user's answer on the second consultation.
    words = conn.execute("SELECT text FROM life_why WHERE id=?;",
                         (wid,)).fetchone()[0]
    previous = conn.execute(
        "SELECT a.label FROM metric_axis a WHERE a.origin='user' AND "
        "a.why_id=(SELECT w.id FROM life_why w WHERE w.domain IS ? AND "
        "w.text=? AND w.id<>? ORDER BY w.id LIMIT 1) ORDER BY a.axis_rank;",
        (domain, words, wid)).fetchall()
    if previous and len(previous) == len(specs):
        labels = [r[0] for r in previous]
        if len(set(labels)) == len(labels):
            specs = [(labels[i], mets) for i, (_label, mets)
                     in enumerate(specs)]
    if not _why_slot({"label": wlabel}):
        return {"error": "direction %d has no short name yet -- run "
                         "why-label-set %d \"<짧은 이름>\" first" % (wid, wid)}
    known = {r[0] for r in conn.execute(
        "SELECT metric_token FROM goal_metric_source;").fetchall()}
    kinds = {}
    split = []
    for label, mets in specs:
        k = [m[1:] for m in mets if m.startswith("@")]
        if any(x not in _STRAND_KINDS for x in k) or len(k) > 1:
            return {"error": "strand %r: '@' marks one kind, one of %s"
                             % (label, ", ".join("@" + x
                                                 for x in _STRAND_KINDS))}
        if k:
            kinds[str(label or "").strip()] = k[0]
        split.append((label, [m for m in mets if not m.startswith("@")]))
    specs = split
    # A practice / care strand's check numbers read from the user's own logs
    # (max_reps_pullup of the max_reps_* family) are stored with the strand,
    # not linked: a family has no per-movement registry row.
    checks = {}
    for label, mets in specs:
        lab = str(label or "").strip()
        if lab in kinds:
            checks[lab] = [m for m in mets if m not in known
                           and _check_family(conn, m)]
            body = [m for m in mets if m in known
                    and not _metric_is_program(conn, m)]
            if body:
                return {"error": "strand %r: %s is read as a number of its "
                                 "own -- a @%s strand takes only check "
                                 "numbers (%s); drop the '@' to measure it"
                                 % (label, ",".join(body), kinds[lab],
                                    "pack-computed shares or a rep max "
                                    "max_reps_<movement>")}
    specs = [(label, [m for m in mets
                      if m not in checks.get(str(label or "").strip(), [])])
             for label, mets in specs]
    for label, mets in specs:
        lab = str(label or "").strip()
        if not lab or len(lab) > _AXIS_LABEL_MAX or \
                any(p in lab for p in _WHY_LABEL_PUNCT) or \
                lab.endswith(_WHY_LABEL_ENDINGS):
            return {"error": "strand name %r: a short word from the user's "
                             "answer, <= %d chars, no sentence ending"
                             % (label, _AXIS_LABEL_MAX)}
        bad = [m for m in mets if m not in known]
        if bad:
            return {"error": "unregistered metric(s) %s -- a strand with no "
                             "matching metric is added without '='"
                             % ",".join(bad)}
        if domain == "health" and not mets and \
                str(label or "").strip() not in kinds:
            # K2: a health strand is a measure, a practice or a care --
            # an untyped one became "방향으로 가져가기" on the card.
            return {"error": "health strand %r needs a kind: =<metric>, "
                             "=@practice or =@care" % label}
        if domain == "health" and mets and \
                str(label or "").strip() not in kinds:
            # A body-shape strand is fat AND muscle (owner 2026-09-30 19:27:
            # x테이퍼 by body fat alone is not enough). The type is read from
            # the strand's name, else from its clause of the direction.
            ty = _strand_type_of(label) or \
                _strand_type_of(_strand_clause(words, label))
            if ty is not None and ty.get("require_all"):
                need = [m for m in ty["metrics"] if m in known]
                miss = [m for m in need if m not in mets]
                if miss:
                    return {"error": "strand %r reads as a body shape: it "
                                     "carries every shape measure the kit "
                                     "tracks -- use =%s"
                                     % (label, ",".join(
                                         need + [m for m in mets
                                                 if m not in need]))}
    # A strand named after a known ideal never links what misrepresents it
    # (the pack's archetype table: Pilates is controlled movement, so the
    # hold share never checks it).
    for label, mets in specs:
        lab = str(label or "").strip()
        arch = _archetype_of(lab, _strand_clause(words, lab))
        if arch is None:
            continue
        never = set(_archetype_never(arch))
        bad = [m for m in list(mets) + checks.get(lab, []) if m in never]
        if bad:
            h = _archetype_hint(conn, arch,
                                lab + " " + (_strand_clause(words, lab)
                                             or ""), domain, owning_agent)
            return {"error": "strand %r reads as %s: %s misrepresents it -- "
                             "use %s" % (label, arch.get("label_ko")
                                         or arch["key"], ",".join(bad),
                                         h["axis"])}
    for plab, phrase in picture_of.items():
        if str(plab).strip() not in [str(x).strip() for x in labels_asked]:
            return {"error": "--picture %r names no --axis strand" % plab}
        bad = _strand_picture_problem(phrase)
        if bad:
            return {"error": "--picture for %r: %s (%s)"
                             % (plab, bad, _STRAND_PICTURE_HINT)}
    agent = owning_agent or _why_steward() or _facade_agent()
    existing = {r[1]: r[0] for r in conn.execute(
        "SELECT axis_key, label FROM metric_axis WHERE origin='user' "
        "AND why_id=?;", (wid,)).fetchall()}
    rank = conn.execute("SELECT COUNT(*) FROM metric_axis WHERE origin='user' "
                        "AND why_id=?;", (wid,)).fetchone()[0]
    for label, mets in specs:
        lab = str(label).strip()
        key = existing.get(lab)
        if key is None:
            rank += 1
            key = "u%d_%d" % (wid, rank)
            conn.execute(
                "INSERT INTO metric_axis (axis_key, axis_rank, label, domain, "
                "owning_agent, note, created_at, origin, role, why_id) "
                "VALUES (?,?,?,?,?,?,?,'user','picture',?);",
                (key, rank, lab, domain, agent,
                 "Derived from the user's own answer (life_why %d)." % wid,
                 _utc_now_str(), wid))
            existing[lab] = key
        # The spec is the truth for this strand: its links become exactly
        # `mets` (a correction that changes what to measure re-runs axis-add
        # with the new metric).
        conn.execute("UPDATE goal_metric_source SET axis_key=NULL "
                     "WHERE axis_key=?;", (key,))
        for m in mets:
            conn.execute("UPDATE goal_metric_source SET axis_key=? "
                         "WHERE metric_token=?;", (key, m))
    st = _move_state(conn, wid)
    if kinds:
        sk = dict(st.get("strand_kind") or {})
        for lab, kind in kinds.items():
            sk[existing[lab]] = kind
        st["strand_kind"] = sk
    # each strand's clause of the direction + its qualifier (+ picture)
    sf = dict(st.get("strand") or {})
    for (label, _mets), pic in zip(specs, pictures):
        lab = str(label).strip()
        cur = dict(sf.get(existing[lab]) or {})
        clause = _strand_clause(words, lab)
        q, clean = _strand_qualifier(clause, lab)
        cur.update({"clause": clause, "qualifier": q, "clean": clean})
        if lab in kinds:
            cur["checks"] = checks.get(lab) or []
        else:
            cur.pop("checks", None)
        if pic:
            cur["picture"] = " ".join(str(pic).split())
        elif not cur.get("picture"):
            # no picture given: a strand named after a known ideal takes
            # the ideal's short picture as its default (keep / fix reads
            # it back like any other)
            arch = _archetype_of(lab, clause)
            if arch is not None:
                dpic = _archetype_picture(arch)[0]
                if dpic:
                    cur["picture"] = dpic
        sf[existing[lab]] = cur
    st["strand"] = sf
    _move_state_put(conn, wid, st)
    conn.commit()
    axes = _user_axes(conn, domain, wid)
    # ONE line, built from the strands alone. 2.28.0 spoke the direction's
    # short name (a model-chosen label, e.g. '건강, 볼륨, 기능성') and then the
    # strand list ('볼륨 · 기능성 · 이쁜 몸 · 건강, 네 갈래') side by side --
    # a three-item "list" next to a four-item one (live 2026-09-26 16:5x).
    # Nothing is queued: the next move's card shows the strands on its
    # direction line, and that line is the confirmation.
    names = " · ".join(a["label"] for a in axes)
    if len(axes) > 1:
        line = _move_text("axes_readback", axes=names,
                          n=_N_KO.get(len(axes), str(len(axes))))
    else:
        line = _move_text("axis_one_readback", axes=names,
                          ro=_josa(names, "ro"))
    return {"why_id": wid, "axes": axes, "say": None, "carried": line}


def _state_carry(st, line):
    """_move_carry on a move state the caller is about to write back."""
    carry = list(st.get("carry") or [])
    carry.append({"id": max([c["id"] for c in carry] or [0]) + 1,
                  "line": line})
    st["carry"] = carry[-8:]


def _move_carry(conn, why_id, line):
    """Queue a confirmation line for the next spoken move of this direction
    (_fold_readback) -- a write verb never speaks a message of its own."""
    st = _move_state(conn, why_id)
    carry = list(st.get("carry") or [])
    carry.append({"id": max([c["id"] for c in carry] or [0]) + 1,
                  "line": line})
    st["carry"] = carry[-8:]
    _move_state_put(conn, why_id, st)
    conn.commit()


def axis_direction(conn, axis_key, text, label):
    """A correction that states what ONE strand is for ("풀업만 말고, 몸이
    연결되게"). Stored the way the owner ruled (2026-09-26 B): a direction
    row in the user's words + a link -- the strand's goal is written against
    it. Returns the one readback line; the proposal is rebuilt by the next
    move, not patched."""
    row = conn.execute("SELECT why_id, domain, label FROM metric_axis WHERE "
                       "axis_key=? AND origin='user';", (axis_key,)).fetchone()
    if row is None:
        return {"error": "unknown strand %r" % axis_key}
    main_wid, domain, alabel = row
    if not str(text or "").strip():
        return {"error": "--text is the user's own words, verbatim"}
    bad = _why_label_error(label)
    if bad:
        return {"error": bad}
    now = _utc_now_str()
    cur = conn.execute(
        "INSERT INTO life_why (ulid, text, scope, domain, spectrum, "
        "managing_agent, created_at, updated_at, label) "
        "VALUES (?, ?, 'module', ?, 'aspiration', ?, ?, ?, ?);",
        (new_ulid(), str(text), domain, _why_steward(), now, now,
         str(label).strip()))
    st = _move_state(conn, main_wid)
    sw = st.get("strand_why") or {}
    sw[axis_key] = cur.lastrowid
    st["strand_why"] = sw
    _move_state_put(conn, main_wid, st)
    # a goal already written for the strand now serves the new direction
    for key, g in _why_goals(conn, main_wid).items():
        if key == axis_key:
            conn.execute("UPDATE ledger_goal SET why_id=? WHERE id=?;",
                         (cur.lastrowid, g["id"]))
    conn.commit()
    lab = str(label).strip()
    line = _move_text("direction_readback", label=lab, ro=_josa(lab, "ro"))
    _move_carry(conn, main_wid, line)
    return {"why_id": cur.lastrowid, "axis_key": axis_key, "say": None,
            "carried": line}


def cli_axis_direction(argv):
    # axis-direction <axis_key> --text "<the user's words>" --label "<짧은 말>"
    argv, as_json = _pop_flag(argv, '--json')
    argv, text = _pop_opt(argv, '--text')
    argv, label = _pop_opt(argv, '--label')
    if len(argv) != 1 or text is None or label is None:
        _err("사용법: kit_life.sh axis-direction <axis_key> --text "
             "\"<그대로>\" --label \"<짧은 말>\" [--json]")
    conn = get_conn()
    try:
        res = axis_direction(conn, argv[0], text, label)
    finally:
        conn.close()
    if res.get("error"):
        _err("axis-direction: " + res["error"])
    if as_json:
        print(json.dumps(res, ensure_ascii=False))
        return
    print("WHY\t%d\t%s" % (res["why_id"], res["axis_key"]))
    print("CARRIED\t%s" % res["carried"])


def axis_order(conn, why_id, first=None, together=False):
    axes = _user_axes(conn, None, why_id)
    keys = [a["axis_key"] for a in axes]
    if not axes:
        return {"error": "direction %s has no strands" % why_id}
    if together:
        pair = _tension_pair(axes)
        tied = {a["axis_key"] for a in pair} if pair else set(keys)
        for k in keys:
            conn.execute("UPDATE metric_axis SET phase_order=? WHERE "
                         "axis_key=?;", (1 if k in tied else 2, k))
    else:
        if first not in keys:
            return {"error": "unknown strand %r (have: %s)"
                             % (first, ",".join(keys))}
        n = 2
        for k in keys:
            conn.execute("UPDATE metric_axis SET phase_order=? WHERE "
                         "axis_key=?;", (1 if k == first else n, k))
            if k != first:
                n += 1
    conn.commit()
    # G5 (fill-and-state, A1): the order answer writes what follows from it
    # at once -- the held strands of the phase and the body cadence -- so
    # the next message states them instead of asking.
    wrote = []
    stage = _rebuild_open(conn)       # a rebuild / restart window stages
    for cmd in _order_fill_cmds(conn, int(why_id), stage):
        _run_verb(cmd)
        wrote.append(cmd[0])
    return {"why_id": int(why_id), "axes": _user_axes(conn, None, why_id),
            "filled": wrote}


def cli_axis_add(argv):
    # axis-add --why-id N --axis "<label>[=m1,m2]" [--axis ...]
    #          [--picture "<label>=<phrase>" ...] [--json]
    argv, as_json = _pop_flag(argv, '--json')
    argv, wid = _pop_opt(argv, '--why-id')
    pictures = {}
    while True:
        argv, raw = _pop_opt(argv, '--picture')
        if raw is None:
            break
        plab, _sep, phrase = raw.partition("=")
        pictures[plab.strip()] = phrase.strip()
    specs = []
    while True:
        argv, raw = _pop_opt(argv, '--axis')
        if raw is None:
            break
        lab, _sep, mets = raw.partition("=")
        specs.append((lab.strip(), [m.strip() for m in mets.split(",")
                                    if m.strip()]))
    # "=@practice" / "=@care": what a strand with no reading of its own is
    # carried as (a practice every session keeps / the care outside the
    # lifts). A kind, not a metric.
    if argv or not wid or not str(wid).isdigit() or not specs:
        _err("사용법: kit_life.sh axis-add --why-id N --axis "
             "\"<갈래 이름>[=metric,...]\" [--axis ...] "
             "[--picture \"<갈래 이름>=<그림>\" ...] [--json]")
    conn = get_conn()
    try:
        res = axis_add(conn, int(wid), specs, pictures=pictures or None)
    finally:
        conn.close()
    if res.get("error"):
        _err("axis-add: " + res["error"])
    if as_json:
        print(json.dumps(res, ensure_ascii=False))
        return
    for a in res["axes"]:
        print("AXIS\t%s\t%s\t%s" % (a["axis_key"], a["label"],
                                     ",".join(a["metrics"])))
    print("CARRIED\t%s" % res["carried"])


def cli_axis_order(argv):
    # axis-order --why-id N (--first <axis_key> | --together) [--json]
    argv, as_json = _pop_flag(argv, '--json')
    argv, together = _pop_flag(argv, '--together')
    argv, wid = _pop_opt(argv, '--why-id')
    argv, first = _pop_opt(argv, '--first')
    argv, mode = _pop_opt(argv, '--mode')
    if argv or not wid or not str(wid).isdigit() or \
            (not together and not first and not mode) or \
            sum(bool(x) for x in (together, first, mode)) != 1 or \
            (mode is not None and mode not in
             ("cut", "recomp", "lean_bulk", "bulk")):
        _err("사용법: kit_life.sh axis-order --why-id N "
             "(--first <axis_key> | --together) [--json]")
    conn = get_conn()
    try:
        if mode:
            pair = _tension_pair(_user_axes(conn, None, int(wid)))
            if not pair:
                _err("axis-order: no body pair")
            st = _move_state(conn, int(wid))
            first = pair[1]["axis_key"] if mode in ("lean_bulk", "bulk") \
                else pair[0]["axis_key"]
            together = mode == "recomp"
            st["goal_mode"] = mode
            st["fat_recommendation"] = _fat_recommendation(conn, int(wid))
            _move_state_put(conn, int(wid), st)
            conn.commit()
        res = axis_order(conn, int(wid), first, together)
    finally:
        conn.close()
    if res.get("error"):
        _err("axis-order: " + res["error"])
    if as_json:
        print(json.dumps(res, ensure_ascii=False))
        return
    for a in res["axes"]:
        print("AXIS\t%s\t%s\t%s" % (a["axis_key"], a["label"],
                                     a["phase_order"]))


_EXP_HISTORY = ("continuous", "returner", "beginner")


def _correct_primary(conn, wid, axis_key, towards):
    """(primary, not_moved, error): the ONE variable a correction moves.
    A held strand moves its range (narrower) or its number (higher); any
    other strand moves its pace or its horizon. Two directions -> the first
    the strand can take; the other is named in one line, never asked."""
    g = _why_goals(conn, wid).get(axis_key)
    held = g is not None and \
        _detail_get(g.get("detail"), "phase") == "maintain"
    allowed = ("higher",) if held else \
        ("faster", "slower", "longer", "shorter")
    prim = next((t for t in towards if t in allowed), None)
    rest = [t for t in towards if t != prim]
    if prim is None and not held and any(t in ("higher", "lower")
                                         for t in towards):
        # 'more' on a pace strand = faster in its own direction
        prim = "faster"
    return prim, rest, allowed


def _practice_dup_other(conn, st, wid, axis_key, cardw, pick):
    """The label of another strand of this direction whose practice answer
    this one repeats (same card phrase, whitespace folded, or a shared pick
    key), else None. Never a refusal (owner 2026-10-01: never refuse a user
    choice; say what it costs and let them pick): the answer is written and
    the next move says in one line that the same move counts for both
    strands. A complaint about a repeated menu is not an answer at all --
    that re-ask is the agent's (moves.md), not this check's."""
    cards = ((st.get("card") or {}).get("practice") or {})
    picks = st.get("practice_pick") or {}
    phrase = " ".join(cardw.split()) if cardw is not None else None
    mine = sorted(pick.split(",")) if pick else None
    labels = {a["axis_key"]: a["label"] for a in _user_axes(conn, None, wid)}
    for other in sorted(set(cards) | set(picks)):
        if other == axis_key:
            continue
        op = picks.get(other)
        op = sorted(op if isinstance(op, list) else [op]) if op else None
        if (phrase and cards.get(other) and
                " ".join(str(cards[other]).split()) == phrase) or \
                (mine and op and set(mine) & set(op)):
            return labels.get(other, other)
    return None


def cli_goal_move_note(argv):
    # goal-move-note --why-id N (--activity "<words>" [--card C]
    #                              [--training "<words>" --years-band B
    #                               --history H]
    #                            | --unknown <metric>
    #                            | --cadence-declined <metric>
    #                            | --safety "none|records|<words>"
    #                            | --training "<words>" [--years-band B]
    #                              [--history H]
    #                            | --facts keep|changed
    #                            | --practice <axis_key> --words "<words>"
    #                              [--pick <pick>[,<more, same set>...]]
    #                              [--card C] [--allow-same-practice]
    #                            | --practice <axis_key> --pick-said
    #                              "<the user's words>" [--allow-same-practice]
    #                            | --confirm-why keep|change
    #                            | --confirm-strands keep|fix
    #                              [--strand <axis_key>]
    #                            | --picture <axis_key> --words "<phrase>"
    #                              [--qualified "<qualified name>"]
    #                            | --care <axis_key> --words "yes|<words>"
    #                            | --correct <axis_key> --toward T
    #                              [--toward T2] [--value N]
    #                            | --correct-done <axis_key> [--pick P]
    #                            | --inbody-basis weigh|stale|new
    #                            | --carry-weight <kg>)
    argv, wid = _pop_opt(argv, '--why-id')
    argv, ibasis = _pop_opt(argv, '--inbody-basis')
    argv, cweight = _pop_opt(argv, '--carry-weight')
    argv, act = _pop_opt(argv, '--activity')
    argv, unk = _pop_opt(argv, '--unknown')
    argv, cdec = _pop_opt(argv, '--cadence-declined')
    argv, saf = _pop_opt(argv, '--safety')
    argv, trn = _pop_opt(argv, '--training')
    argv, band = _pop_opt(argv, '--years-band')
    argv, hist = _pop_opt(argv, '--history')
    argv, prac = _pop_opt(argv, '--practice')
    argv, pic = _pop_opt(argv, '--picture')
    argv, qual = _pop_opt(argv, '--qualified')
    argv, care = _pop_opt(argv, '--care')
    argv, words = _pop_opt(argv, '--words')
    argv, cardw = _pop_opt(argv, '--card')
    argv, facts = _pop_opt(argv, '--facts')
    argv, direction_adjust = _pop_flag(argv, '--direction-adjust')
    argv, direction_wish = _pop_opt(argv, '--direction-wish')
    argv, confirm_why = _pop_opt(argv, '--confirm-why')
    argv, confirm_strands = _pop_opt(argv, '--confirm-strands')
    argv, strand_key = _pop_opt(argv, '--strand')
    # accepted for older callers; a repeated practice is no longer refused
    # (_practice_dup_other), so the flag changes nothing
    argv, same_prac = _pop_flag(argv, '--allow-same-practice')
    argv, pick_said = _pop_opt(argv, '--pick-said')
    argv, pick = _pop_opt(argv, '--pick')
    argv, corr = _pop_opt(argv, '--correct')
    argv, cdone = _pop_opt(argv, '--correct-done')
    argv, cval = _pop_opt(argv, '--value')
    towards = []
    while True:
        argv, tw = _pop_opt(argv, '--toward')
        if tw is None:
            break
        towards.append(tw)
    usage = ("사용법: kit_life.sh goal-move-note --why-id N (--activity "
             "\"<그대로>\" [--training \"<그대로>\" --years-band B --history H] "
             "| --unknown <metric> | --cadence-declined <metric> "
             "| --safety \"none|records|<그대로>\" | --training \"<그대로>\" "
             "[--card \"<카드용 짧은 말>\"] "
             "[--years-band lt1|1to3|3plus] [--history continuous|returner|"
             "beginner] | --facts keep|changed | --confirm-why keep|change "
             "| --confirm-strands keep|fix [--strand <axis_key>] "
             "| --practice <axis_key> "
             "--words \"<그대로>\" [--pick <선택>[,<같은 묶음의 다른 선택>...]] "
             "[--allow-same-practice] | --practice <axis_key> --pick-said "
             "\"<그대로>\" | --picture <axis_key> --words "
             "\"<갈래의 그림>\" [--qualified \"<꾸밈말 붙은 갈래 이름>\"] | "
             "--care <axis_key> --words \"yes|<그대로>\" "
             "| --direction-adjust | --direction-wish \"<바라는 변화와 시기>\" "
             "| --correct <axis_key> --toward %s [--value N] | --correct-done "
             "<axis_key> [--pick P] | --inbody-basis weigh|stale|new "
             "| --carry-weight <kg>)" % "|".join(_CORRECT_TOWARD))
    if pick_said is not None:
        # the menu answered in words ("1이랑 2", "호흡이랑 가동성", "셋 다"):
        # one note for every option named, however many
        if prac is None or words is not None or pick is not None or \
                cardw is not None or not pick_said.strip() or \
                not wid or not str(wid).isdigit():
            _err(usage)
        conn = get_conn()
        try:
            st0, why0 = _move_state(conn, int(wid)), _why_text(conn, int(wid))
            ps = _practice_sets_by_strand(conn, st0, int(wid), why0).get(prac)
            names = " ".join(
                "%s %s" % (x["label"], _strand_info(conn, st0, x, why0)["label"])
                for x in _user_axes(conn, None, int(wid))
                if x["axis_key"] == prac)
        finally:
            conn.close()
        if ps is None:
            _err("goal-move-note: --pick-said: strand %r has no menu here "
                 "(an open ask): note the user's words with --words and "
                 "--card" % prac)
        picks = _practice_picks_said(ps, pick_said, names)
        if not picks:
            _err("goal-move-note: --pick-said: %r names no option of this "
                 "menu. Their own way to keep the strand -> --words "
                 "\"<그대로>\" --card \"<카드용 짧은 말>\"; unclear -> ask "
                 "again." % pick_said)
        note = _practice_pick_note(wid, prac, picks)
        words = note[note.index("--words") + 1]
        pick = note[note.index("--pick") + 1]
        cardw = note[note.index("--card") + 1]
    primary = [x for x in (act, unk, cdec, saf, prac, pic, care, facts,
                           confirm_why, confirm_strands, direction_wish, corr,
                           cdone, ibasis, cweight) if x is not None]
    if direction_adjust:
        primary.append(True)
    trn_alone = trn is not None and act is None
    if argv or not wid or not str(wid).isdigit() or \
            len(primary) + (1 if trn_alone else 0) != 1 or \
            (saf is not None and not saf.strip()) or \
            ((band is not None or hist is not None) and trn is None) or \
            (band is not None and band not in _EXP_BANDS) or \
            (hist is not None and hist not in _EXP_HISTORY) or \
            ((prac is not None or care is not None or pic is not None)
             != (words is not None and bool(words.strip()))) or \
            (qual is not None and pic is None) or \
            (facts is not None and facts not in ("keep", "changed")) or \
            (confirm_why is not None and
             confirm_why not in ("keep", "change")) or \
            (confirm_strands is not None and
             confirm_strands not in ("keep", "fix")) or \
            (strand_key is not None and confirm_strands is None) or \
            (same_prac and prac is None) or \
            (direction_wish is not None and not direction_wish.strip()) or \
            (pick is not None and prac is None and cdone is None) or \
            (prac is not None and pick is not None
             and (len(set(pick.split(','))) != len(pick.split(',')) or
                  any(p not in _PRACTICE_ALL_PICKS for p in pick.split(',')) or
                  not any(set(pick.split(',')) <= set(grp) for grp in
                          [ps["picks"] for ps in _PRACTICE_SETS]
                          + list(_PRACTICE_LEGACY_PICKS)))) or \
            ((corr is not None) != bool(towards or cval is not None)) or \
            any(t not in _CORRECT_TOWARD for t in towards) or \
            (cval is not None and _num(cval, None) is None) or \
            (ibasis is not None and ibasis not in _INBODY_BASIS_PICKS) or \
            (cweight is not None and (_num(cweight, None) is None or
                                      float(_num(cweight, None)) <= 0)) or \
            (cardw is not None and (not cardw.strip() or
                                    (cardw.strip().startswith("<") and
                                     cardw.strip().endswith(">")) or
                                    (act is None and trn is None and
                                     prac is None and
                                     (saf is None or saf.strip() in
                                      ("none", "records"))))):
        _err(usage)
    conn = get_conn()
    try:
        wid = int(wid)
        st = _move_state(conn, wid)
        if cardw is not None:
            card = dict(st.get("card") or {})
            phrase = " ".join(cardw.split())
            if prac is not None:
                cp = dict(card.get("practice") or {})
                cp[prac] = phrase
                card["practice"] = cp
            else:
                card["activity" if act is not None else
                     "training" if trn is not None else "safety"] = phrase
            st["card"] = card
        if act is not None:
            st["activity"] = act
            st.pop("facts_changed", None)
        if trn is not None:
            # the training-age answer: the words for the card, the band for
            # the rate model, the history kind for the program's structure
            # -- the keys the pack reads, so it never asks again. Rides the
            # activity note when that answer already said how long.
            st["training"] = trn.strip()
            today = datetime.date.today().isoformat()
            if band is not None:
                _config_put(conn, _EXP_KEY, band)
                _config_put(conn, _EXP_ASOF_KEY, today)
            if hist is not None:
                _config_put(conn, _PACK_EXP_KEY, hist)
        if act is not None or trn is not None:
            pass
        elif saf is not None:
            if saf.strip() == "records":
                recs = _safety_records(conn)
                if not recs:
                    _err("goal-move-note: --safety records: no active "
                         "safety rows to confirm")
                st["safety"] = {"answered": datetime.date.today().isoformat(),
                                "text": "; ".join(r["value"] for r in recs),
                                "from": "records",
                                "keys": [r["key"] for r in recs]}
                card = dict(st.get("card") or {})
                card["safety"] = " · ".join(_uniq(r["site"] for r in recs))
                st["card"] = card
            else:
                st["safety"] = {"answered":
                                datetime.date.today().isoformat(),
                                "text": saf.strip()}
                if saf.strip() == "none":
                    (st.get("card") or {}).pop("safety", None)
        elif facts is not None:
            ff = st.get("facts_from") or {}
            if facts == "keep":
                if not ff.get("activity"):
                    _err("goal-move-note: --facts keep: nothing to keep")
                st["activity"] = ff["activity"]
                if ff.get("training"):
                    st["training"] = ff["training"]
                fcw = ff.get("card") or {}
                card = dict(st.get("card") or {})
                for k in ("activity", "training"):
                    if fcw.get(k):
                        card[k] = fcw[k]
                st["card"] = card
            else:
                st["facts_changed"] = True
        elif confirm_why is not None:
            row = conn.execute("SELECT text FROM life_why WHERE id=?;",
                               (wid,)).fetchone()
            if row is None:
                _err("goal-move-note: --confirm-why: no direction %s" % wid)
            if confirm_why == "keep":
                st["why_confirmed"] = {"at": _epoch_iso(_consult_clock()),
                                       "text": row[0]}
                st.pop("why_changing", None)
            else:
                st["why_changing"] = True
        elif confirm_strands is not None:
            # stored against the readback the user saw: a later change to a
            # measure, a picture or a strand's direction asks again
            if not _user_axes(conn, None, wid):
                _err("goal-move-note: --confirm-strands: direction %s has "
                     "no strands" % wid)
            rows, sig = _strands_readback(conn, wid)
            if strand_key is None:
                cur = _strand_pending(st, rows, sig)
            else:
                cur = next((r for r in rows if r["axis_key"] == strand_key),
                           None)
                if cur is None:
                    _err("goal-move-note: --strand %s is not a strand of "
                         "direction %s" % (strand_key, wid))
            if cur is not None:
                # one strand at a time (owner 19:39): stored against the line
                # the user saw for it
                st["strands_listed"] = _strands_list_sig(rows)
                if confirm_strands == "keep":
                    ok = st.get("strands_ok") or {}
                    ok[cur["axis_key"]] = cur["sig"]
                    st["strands_ok"] = ok
                    st.pop("strand_fixing", None)
                else:
                    st["strand_fixing"] = {"key": cur["axis_key"],
                                           "sig": sig}
        elif direction_adjust:
            st["direction_adjusting"] = True
        elif direction_wish is not None:
            st["direction_wish"] = " ".join(direction_wish.split())
            st.pop("direction_adjusting", None)
        elif pic is not None:
            ax = next((a for a in _user_axes(conn, None, wid)
                       if a["axis_key"] == pic), None)
            if ax is None:
                _err("goal-move-note: unknown strand %r for direction %s"
                     % (pic, wid))
            bad = _strand_picture_problem(words)
            if bad:
                _err("goal-move-note: --picture: %s (%s)"
                     % (bad, _STRAND_PICTURE_HINT))
            sf = dict(st.get("strand") or {})
            cur = dict(sf.get(pic) or {})
            cur["picture"] = " ".join(words.split())
            if qual is not None:
                q = " ".join(qual.split())
                rx = _label_rx(ax["label"])
                if not q or len(q) > _STRAND_QUALIFIED_MAX or \
                        (q.startswith("<") and q.endswith(">")) or \
                        not rx.search(q):
                    _err("goal-move-note: --qualified: the strand's own name "
                         "(%s) with what qualifies it, <= %d chars (%s)"
                         % (ax["label"], _STRAND_QUALIFIED_MAX,
                            _STRAND_QUALIFIED_HINT))
                cur["qlabel"] = q
            sf[pic] = cur
            st["strand"] = sf
        elif prac is not None or care is not None:
            key = prac if prac is not None else care
            if not conn.execute("SELECT 1 FROM metric_axis WHERE axis_key=? "
                                "AND origin='user' AND why_id=?;",
                                (key, wid)).fetchone():
                _err("goal-move-note: unknown strand %r for direction %s"
                     % (key, wid))
            if prac is not None:
                other = _practice_dup_other(conn, st, wid, prac, cardw, pick)
                if other is not None:
                    lab = next((a["label"] for a in _user_axes(conn, None,
                                                               wid)
                                if a["axis_key"] == prac), prac)
                    _state_carry(st, _move_text(
                        "prac_same", label=lab, eun=_josa(lab, "eun"),
                        other=other, wa=_josa(other, "wa")))
            slot = "practice" if prac is not None else "care"
            got = dict(st.get(slot) or {})
            got[key] = words.strip()
            st[slot] = got
            if prac is not None and pick is not None:
                pp = dict(st.get("practice_pick") or {})
                pp[key] = pick.split(',') if ',' in pick else pick
                st["practice_pick"] = pp
            if care is not None and words.strip() == "yes":
                _config_put(conn, _CARE_CONFIG_KEY, ",".join(_CARE_KEYS))
        elif corr is not None:
            if not conn.execute("SELECT 1 FROM metric_axis WHERE axis_key=? "
                                "AND origin='user' AND why_id=?;",
                                (corr, wid)).fetchone():
                _err("goal-move-note: unknown strand %r for direction %s"
                     % (corr, wid))
            g0 = _why_goals(conn, wid).get(corr)
            handled = False
            if _is_progression_goal(g0):
                # R1: the user's number is a stretch note on the strand;
                # the per-session way stays; one line, no menu.
                if cval is None:
                    _err("goal-move-note: strand %r progresses every "
                         "session; a number the user wants is --value N"
                         % corr)
                v = float(_num(cval, None))
                det = json.loads(g0.get("detail") or "{}")
                det.update({"stretch_value": v, "stretch_from": "user",
                            "stretch_at": datetime.date.today().isoformat()})
                conn.execute("UPDATE ledger_goal SET detail=?, updated_at=?, "
                             "version=version+1 WHERE id=?;",
                             (json.dumps(det, ensure_ascii=False),
                              _utc_now_str(), g0["id"]))
                lab = next((a["label"] for a in _user_axes(conn, None, wid)
                            if a["axis_key"] == corr), "")
                unit = _metric_label(g0.get("metric") or "")[1]
                vs = _fmeas(v) + unit
                _state_carry(st, _move_text(
                    "lift_stretch", value=_fmeas(v), unit=unit,
                    eun=_josa(vs, "eun"), label=lab))
                handled = True
            elif g0 is not None and \
                    _detail_get(g0.get("detail"), "phase") == "maintain" \
                    and "narrower" in towards and cval is None:
                # R3: a held range is the width of the reading's own
                # wobble -- said in one line; nothing narrows, no menu.
                lo = _num(_detail_get(g0.get("detail"), "range_lo"), None)
                hi = _num(_detail_get(g0.get("detail"), "range_hi"), None)
                if lo is None or hi is None:
                    _err("goal-move-note: strand %r holds one number, not "
                         "a range" % corr)
                ml, unit = _metric_label(g0.get("metric") or "")
                hs = _frange(hi) + unit
                _state_carry(st, _move_text(
                    "held_width", lo=_frange(lo), hi=_frange(hi), unit=unit,
                    eun=_josa(hs, "eun"), mlabel=ml, i=_josa(ml, "i")))
                handled = True
            if not handled:
                prim, rest, allowed = _correct_primary(conn, wid, corr,
                                                       towards)
                if prim is None and cval is None:
                    _err("goal-move-note: --toward %s does not move this "
                         "strand (it takes: %s, or --value N)"
                         % (",".join(towards), ", ".join(allowed)))
                c = {"toward": prim, "not_moved": [t for t in rest
                                                   if t != prim]}
                if cval is not None:
                    c["value"] = float(_num(cval, None))
                    if prim is None:
                        c["toward"] = "higher" if "higher" in allowed \
                            else None
                cs = dict(st.get("correct") or {})
                cs[corr] = c
                st["correct"] = cs
        elif cdone is not None:
            cs = dict(st.get("correct") or {})
            cs.pop(cdone, None)
            st["correct"] = cs
            if pick is not None:
                hp = dict(st.get("held_pick") or {})
                hp[cdone] = pick
                st["held_pick"] = hp
        elif ibasis is not None:
            day = _inbody_latest_date(conn)
            if day is None:
                _err("goal-move-note: --inbody-basis: no InBody on record")
            st["inbody_basis"] = {"pick": ibasis, "inbody_date": day,
                                  "at": datetime.date.today().isoformat()}
            if ibasis != "weigh":
                _state_carry(st, _move_text("inbody_stale_kept",
                                            date=_fmt_date_ko(day)))
        elif cweight is not None:
            res = inbody_carry_forward(conn, float(_num(cweight, None)))
            if res.get("error"):
                conn.rollback()
                _err("goal-move-note: --carry-weight: %s" % res["error"])
            st["inbody_basis"] = {"pick": "weigh",
                                  "inbody_date": res["from"],
                                  "at": res["date"], "carried": res}
            _state_carry(st, _move_text(
                "inbody_carried", date=_fmt_date_ko(res["from"]),
                weight=_fmeas(res["weight_kg"]),
                fat=_fmeas(res["fat_mass_kg"]),
                pct=_fmeas(res["body_fat_pct"])))
        elif unk is not None:
            st["unknown"] = sorted(set(st.get("unknown") or []) | {unk})
        else:
            cd = st.get("cadence_declined") or {}
            cd[cdec] = True
            st["cadence_declined"] = cd
        _move_state_put(conn, wid, st)
        conn.commit()
        # a carried body reading re-derives the diet target like log-metric
        notice = _refresh_diet_from_body(conn) if cweight is not None \
            else None
        st = _move_state(conn, wid)
    finally:
        conn.close()
    print("NOTED\t%s" % json.dumps(st, ensure_ascii=False))
    if notice:
        print(notice)


# ── standing constraints / resources / strand + segment readouts ─────────────
# Writer verbs for two ledger tables that had readers but no writer (047 left
# ledger_constraint without one on purpose: a standing safety row reshapes
# every future program). Both writers are called only with the user's own
# answer -- the safety move (ask_safety) and the place answer -- never from a
# pattern over events; pain-candidates stays read-only.

_CONSTRAINT_CLASSES = ("nutrition", "safety", "time")
_ENV_VENUES = ("gym", "home", "other")


def constraint_add(conn, cls, key, value, source="chat", inviolable=False):
    """One standing constraint. An active row with the same (class, key) is
    UPDATED (its value is the user's latest words), never duplicated."""
    if cls not in _CONSTRAINT_CLASSES:
        return {"error": "unknown class %r (have: %s)"
                         % (cls, ",".join(_CONSTRAINT_CLASSES))}
    k = _pain_site_token(key)
    if not k:
        return {"error": "empty key"}
    if cls == "safety" and not k.startswith("injury_"):
        return {"error": "a safety key is injury_<site>[_l|_r], got %r" % k}
    v = str(value or "").strip()
    if not v:
        return {"error": "empty value"}
    now = _utc_now_str()
    row = conn.execute("SELECT id FROM ledger_constraint WHERE class=? AND "
                       "key=? AND status='active' ORDER BY id DESC LIMIT 1;",
                       (cls, k)).fetchone()
    if row:
        conn.execute("UPDATE ledger_constraint SET value=?, source=?, "
                     "inviolable=?, recorded_at=? WHERE id=?;",
                     (v, source, 1 if inviolable else 0, now, row[0]))
        cid, action = row[0], "updated"
    else:
        cid = conn.execute(
            "INSERT INTO ledger_constraint (ulid, class, key, value, "
            "inviolable, status, source, recorded_at) "
            "VALUES (?,?,?,?,?,'active',?,?);",
            (new_ulid(), cls, k, v, 1 if inviolable else 0, source,
             now)).lastrowid
        action = "added"
    conn.commit()
    return {"id": cid, "action": action, "class": cls, "key": k, "value": v}


def constraint_list(conn, cls=None, include_retired=False):
    conds, args = [], []
    if cls:
        conds.append("class=?")
        args.append(cls)
    if not include_retired:
        conds.append("status='active'")
    where = (" WHERE " + " AND ".join(conds)) if conds else ""
    cur = conn.execute("SELECT id, class, key, value, inviolable, status, "
                       "source, recorded_at FROM ledger_constraint%s "
                       "ORDER BY class, key, id;" % where, tuple(args))
    names = [d[0] for d in cur.description]
    return [dict(zip(names, r)) for r in cur.fetchall()]


def constraint_retire(conn, cid):
    n = conn.execute("UPDATE ledger_constraint SET status='retired' WHERE "
                     "id=? AND status='active';", (int(cid),)).rowcount
    conn.commit()
    return n


def resource_add(conn, kind, name, detail=None, source="chat"):
    """One resource row. kind='env' is the training place: detail must be a
    JSON object whose venue is gym|home|other and whose equipment, when
    present, is a list of equipment keys. An active row with the same
    (kind, name) is updated, never duplicated."""
    kd = _pain_site_token(kind)
    nm = str(name or "").strip()
    if not kd or not nm:
        return {"error": "kind and name are required"}
    d = None
    if detail is not None:
        try:
            d = json.loads(detail) if isinstance(detail, str) else detail
        except ValueError:
            return {"error": "detail is not JSON"}
        if not isinstance(d, dict):
            return {"error": "detail must be a JSON object"}
    if kd == "env":
        if not d or d.get("venue") not in _ENV_VENUES:
            return {"error": "env detail.venue must be one of %s"
                             % "|".join(_ENV_VENUES)}
        eq = d.get("equipment")
        if eq is not None and (not isinstance(eq, list) or not all(
                isinstance(x, str) and x.strip() for x in eq)):
            return {"error": "env detail.equipment must be a list of "
                             "equipment keys"}
    dj = json.dumps(d, ensure_ascii=False) if d is not None else None
    now = _utc_now_str()
    row = conn.execute("SELECT id FROM ledger_resource WHERE kind=? AND "
                       "name=? AND status='active' ORDER BY id DESC LIMIT 1;",
                       (kd, nm)).fetchone()
    if row:
        conn.execute("UPDATE ledger_resource SET detail=?, as_of=?, "
                     "source=?, recorded_at=? WHERE id=?;",
                     (dj, now[:10], source, now, row[0]))
        rid, action = row[0], "updated"
    else:
        rid = conn.execute(
            "INSERT INTO ledger_resource (ulid, kind, name, detail, as_of, "
            "status, source, recorded_at) VALUES (?,?,?,?,?,'active',?,?);",
            (new_ulid(), kd, nm, dj, now[:10], source, now)).lastrowid
        action = "added"
    conn.commit()
    return {"id": rid, "action": action, "kind": kd, "name": nm, "detail": d}


def resource_list(conn, kind=None, include_retired=False):
    conds, args = [], []
    if kind:
        conds.append("kind=?")
        args.append(kind)
    if not include_retired:
        conds.append("status='active'")
    where = (" WHERE " + " AND ".join(conds)) if conds else ""
    out = []
    for rid, kd, nm, dj, as_of, stt, src in conn.execute(
            "SELECT id, kind, name, detail, as_of, status, source FROM "
            "ledger_resource%s ORDER BY kind, id;" % where, tuple(args)):
        try:
            d = json.loads(dj) if dj else None
        except ValueError:
            d = dj
        out.append({"id": rid, "kind": kd, "name": nm, "detail": d,
                    "as_of": as_of, "status": stt, "source": src})
    return out


def axis_list(conn, why_id):
    """The user's strands for one direction, as a consumer reads them."""
    return [{"axis_key": a["axis_key"], "label": a["label"],
             "phase_order": a["phase_order"], "metrics": a["metrics"],
             "balance": a["balance"]}
            for a in _user_axes(conn, None, why_id)]


# InBody segmental lean mass (health-log keys). standard_pct is the
# sheet's own "% of standard" for that segment, read only when captured under
# lean_<segment>_pct on the same day; the kit never derives a standard.
_BODY_SEGMENTS = _SEGMENT_KEYS


def body_segment(conn):
    out = []
    for seg in _BODY_SEGMENTS:
        row = conn.execute("SELECT value, date FROM metric_log WHERE metric=? "
                           "ORDER BY date DESC, id DESC LIMIT 1;",
                           ("lean_%s_kg" % seg,)).fetchone()
        if not row or row[0] is None:
            continue
        std = conn.execute("SELECT value FROM metric_log WHERE metric=? AND "
                           "date=? ORDER BY id DESC LIMIT 1;",
                           ("lean_%s_pct" % seg, row[1])).fetchone()
        out.append({"segment": seg, "value": float(row[0]),
                    "standard_pct": (float(std[0]) if std and std[0]
                                     is not None else None),
                    "as_of": str(row[1])[:10]})
    return out


def _cli_result(res, as_json, text_fn):
    if isinstance(res, dict) and res.get("error"):
        _err(res["error"])
    if as_json:
        print(json.dumps(res, ensure_ascii=False))
    else:
        text_fn(res)


def cli_constraint_add(argv):
    # constraint-add --class C --key K --value "<words>" [--source S]
    #                [--inviolable] [--json]
    argv, as_json = _pop_flag(argv, '--json')
    argv, inv = _pop_flag(argv, '--inviolable')
    argv, cls = _pop_opt(argv, '--class')
    argv, key = _pop_opt(argv, '--key')
    argv, val = _pop_opt(argv, '--value')
    argv, src = _pop_opt(argv, '--source')
    if argv or not cls or not key or val is None:
        _err("사용법: kit_life.sh constraint-add --class nutrition|safety|time "
             "--key <key> --value \"<그대로>\" [--source S] [--inviolable] "
             "[--json]")
    conn = get_conn()
    try:
        res = constraint_add(conn, cls, key, val, src or "chat", inv)
    finally:
        conn.close()
    _cli_result(res, as_json, lambda r: print(
        "%s\t#%d\t%s\t%s\t%s" % (r["action"].upper(), r["id"], r["class"],
                                 r["key"], r["value"])))


def cli_constraint_list(argv):
    # constraint-list [--class C] [--all] [--json]
    argv, as_json = _pop_flag(argv, '--json')
    argv, allr = _pop_flag(argv, '--all')
    argv, cls = _pop_opt(argv, '--class')
    if argv:
        _err("사용법: kit_life.sh constraint-list [--class C] [--all] [--json]")
    conn = get_conn()
    try:
        rows = constraint_list(conn, cls, allr)
    finally:
        conn.close()

    def _txt(rs):
        if not rs:
            print("NO_CONSTRAINTS")
        for r in rs:
            print("#%d\t%s\t%s\t%s\t[%s]" % (r["id"], r["class"], r["key"],
                                             r["value"], r["status"]))
    _cli_result(rows, as_json, _txt)


def cli_constraint_retire(argv):
    # constraint-retire <id>
    if len(argv) != 1 or not str(argv[0]).isdigit():
        _err("사용법: kit_life.sh constraint-retire <id>")
    conn = get_conn()
    try:
        n = constraint_retire(conn, int(argv[0]))
    finally:
        conn.close()
    if not n:
        _err("constraint-retire: no active constraint #%s" % argv[0])
    print("RETIRED\t#%s" % argv[0])


def cli_resource_add(argv):
    # resource-add --kind K --name "<label>" [--detail '<json>'] [--source S]
    #              [--json]
    argv, as_json = _pop_flag(argv, '--json')
    argv, kind = _pop_opt(argv, '--kind')
