def cli_body_segment(argv):
    # body-segment [--json]
    argv, as_json = _pop_flag(argv, '--json')
    if argv:
        _err("사용법: kit_life.sh body-segment [--json]")
    conn = get_conn()
    try:
        rows = body_segment(conn)
    finally:
        conn.close()

    def _txt(rs):
        if not rs:
            print("NO_SEGMENTS")
        for r in rs:
            print("SEGMENT\t%s\t%s\t%s\t%s" % (
                r["segment"], _fmeas(r["value"]),
                "-" if r["standard_pct"] is None else _fmeas(r["standard_pct"]),
                r["as_of"]))
    _cli_result(rows, as_json, _txt)


def _print_move(res):
    """Text mode: SAY lines are the only user-facing output."""
    print("MOVE\t%s\tdone\t%s" % (res["kind"], res["done"]))
    for line in res.get("readback") or []:     # the card is the first
        print("SAY\t%s" % line.replace("\n", "\n\t"))
    if res.get("say"):
        print("SAY\t%s" % res["say"].replace("\n", "\n\t"))
    for k in ("on_yes", "on_answer", "on_proceed", "on_no",
              "if_still_unknown", "on_site", "rebuild_commit"):
        if res.get(k):
            print("CMD\t%s\t%s" % (k, json.dumps(res[k], ensure_ascii=False)))
    for c in res.get("choices") or []:
        print("CHOICE\t%s" % json.dumps(c, ensure_ascii=False))


def cli_goal_interview(argv):
    # goal-interview <goal_id> [--revise <field>] [--json]
    # goal-interview --start [--domain D] [--scope rebuild|adjust|add] [--json]
    # goal-interview --next [--domain D] [--stage] [--json]   (055: the move)
    argv, as_json = _pop_flag(argv, '--json')
    argv, is_start = _pop_flag(argv, '--start')
    argv, is_next = _pop_flag(argv, '--next')
    argv, is_restart = _pop_flag(argv, '--restart')
    usage = ("사용법: kit_life.sh goal-interview <goal_id> [--revise <field>] "
             "[--json]  |  kit_life.sh goal-interview --start [--domain D] "
             "[--scope rebuild|adjust|add] [--json]  |  kit_life.sh "
             "goal-interview --next [--domain D] [--stage] [--json]  |  "
             "kit_life.sh goal-interview --restart --domain D "
             "[--from goal|program] [--json]")
    if is_restart:
        # "다시 하자": the ONE path (JOURNEY 7). Archives the unfinished
        # interview, keeps finished goals until the new wrap, returns the
        # first move of the new interview with the restart line.
        argv, domain = _pop_opt(argv, '--domain')
        argv, from_ = _pop_opt(argv, '--from')
        argv, agent = _pop_opt(argv, '--owning-agent')
        if argv or not domain or (from_ or "goal") not in ("goal",
                                                            "program"):
            _err(usage)
        conn = get_conn()
        try:
            res = goal_interview_restart(conn, domain, agent, from_ or "goal")
        finally:
            conn.close()
        if as_json:
            print(json.dumps(res, ensure_ascii=False))
            return
        for a in res["archived"]:
            print("ARCHIVED\twhy\t%d\tstrands\t%s\tgoals\t%s\tkey\t%s"
                  % (a["why_id"], ",".join(a["axes"]) or "-",
                     ",".join(str(x) for x in a["goal_ids"]) or "-",
                     a["archive_key"]))
        print("KEPT\t%s" % (",".join(str(x) for x in res["kept_goal_ids"])
                            or "-"))
        if res.get("next"):
            _print_move(res["next"])
        else:
            print("SAY\t%s" % res["say"])
        return
    if is_next:
        argv, stage = _pop_flag(argv, '--stage')
        argv, domain = _pop_opt(argv, '--domain')
        argv, agent = _pop_opt(argv, '--owning-agent')
        if argv:
            _err(usage)
        conn = get_conn()
        try:
            res = goal_next_move(conn, domain, agent, stage)
        finally:
            conn.close()
        if as_json:
            print(json.dumps(res, ensure_ascii=False))
        else:
            _print_move(res)
        return
    if is_start:
        opt = {}
        i = 0
        while i < len(argv):
            if argv[i] in ("--domain", "--scope", "--owning-agent") and i + 1 < len(argv):
                opt[argv[i][2:]] = argv[i + 1]; i += 2
            else:
                _err(usage)
        if opt.get("scope") and opt["scope"] not in _INTERVIEW_SCOPES:
            _err("goal-interview: --scope must be one of %s"
                 % "|".join(_INTERVIEW_SCOPES))
        conn = get_conn()
        try:
            res = goal_interview_start(
                conn, domain=opt.get("domain"), scope=opt.get("scope"),
                owning_agent=opt.get("owning-agent"))
        finally:
            conn.close()
        if as_json:
            print(json.dumps(res, ensure_ascii=False))
            return
        print("STAGE\t%s\tfield\t%s\task\t%s\tgoals\t%s"
              % (res["stage"], res.get("field") or "", res.get("ask_kind", ""),
                 res["goal_count"]))
        if res.get("uncovered_axes"):
            print("UNCOVERED\t%s" % ", ".join(res["uncovered_axes"]))
        # The non-JSON path is a real surface (the shell caller reads these
        # lines), so a metric-level gap has to appear here too -- otherwise
        # the fix exists only for --json callers and the TSV reader keeps
        # seeing a fully covered picture.
        if res.get("uncovered_metrics"):
            print("UNCOVERED-METRIC\t%s"
                  % ", ".join("%s/%s" % (m["axis"], m["label"])
                              for m in res["uncovered_metrics"]))
        if res.get("destructive"):
            print("DESTRUCTIVE\tretire\t%s"
                  % ",".join(str(i) for i in res.get("retire_goal_ids") or []))
        if res.get("question"):
            print("Q\t%s" % res["question"].replace("\n", "\n\t"))
        for c in res.get("choices") or []:
            print("  CHOICE\t%s" % json.dumps(c, ensure_ascii=False))
        if res.get("on_answer"):
            print("CMD\ton_answer\t%s"
                  % json.dumps(res["on_answer"], ensure_ascii=False))
        if res.get("next_cmd"):
            print("NEXT\t%s" % json.dumps(res["next_cmd"], ensure_ascii=False))
        for ln in _why_label_ask_lines(res.get("whys") or []):
            print(ln)
        return
    argv, reopen = _pop_opt(argv, '--revise')
    if not argv or not str(argv[0]).isdigit():
        _err(usage)
    if reopen is not None and reopen not in _INTERVIEW_FIELDS:
        _err("goal-interview: --revise must be one of %s"
             % "|".join(_INTERVIEW_FIELDS))
    conn = get_conn()
    try:
        res = goal_interview_next(conn, int(argv[0]), reopen=reopen)
    finally:
        conn.close()
    if res is None:
        _err("goal 없음: %s" % argv[0])
    if as_json:
        print(json.dumps(res, ensure_ascii=False))
        return
    if res["done"]:
        print("DONE\t%s\t%s\trung\t%s"
              % (res.get("commitment_kind") or "goal", res["goal_id"],
                 res["rung_state"]))
        return
    print("STEP\t%s/%s\tfield\t%s\task\t%s"
          % (res["step_no"], res["total_steps"], res["field"],
             res.get("ask_kind", "")))
    if res.get("question"):
        print("Q\t%s" % res["question"])
    else:
        # agent-decided field: no question exists; name the write commands.
        print("DECIDE\t%s" % res.get("note", ""))
        for c in res.get("choices") or []:
            print("  CHOICE\t%s" % json.dumps(c, ensure_ascii=False))
    ki = res.get("kind_inference")
    if ki:
        print("KIND-INFER\t%s\t%s\t%s" % (ki["suggest"], ki["why"],
                                             ki["write_cmd"]))
    if res.get("inferred"):
        print("INFERRED\t%s" % json.dumps(res["inferred"], ensure_ascii=False))


