def cli_goal_progress(argv):
    # goal-progress <goal_id> [--json]   -- GOAL readout (distance + time)
    argv, as_json = _pop_flag(argv, '--json')
    if not argv or not str(argv[0]).isdigit():
        _err("사용법: kit_life.sh goal-progress <goal_id> [--json]")
    conn = get_conn()
    try:
        res = goal_progress(conn, int(argv[0]))
    finally:
        conn.close()
    if res is None:
        _err("goal 없음: %s" % argv[0])
    if as_json:
        print(json.dumps(res, ensure_ascii=False)); return
    if res.get("refused"):
        print("REFUSED\t%s" % res["refused"]); sys.exit(EXISTS_CODE)
    print("GOAL\t%s\t%s" % (res["goal_id"], res["title"]))
    print("metric\t%s\tsource\t%s\trung\t%s"
          % (res["metric"] or "", res["source_table"] or "",
             res["rung_state"] or ""))
    print("baseline\t%s (%s)\ttarget\t%s\tdir\t%s"
          % (res["baseline_value"], res["baseline_as_of"] or "-",
             res["target_value"], res["target_dir"] or ""))
    print("current\t%s (%s)\tdistance_to_target\t%s\treached\t%s"
          % (_fmeas(res["current_value"]), res["current_as_of"] or "-",
             _fmeas(res["distance_to_target"]), int(bool(res["reached"]))))
    # the ABSENCE is printed, never papered over.
    print("horizon\t%s\tdays_left\t%s\tfrac_elapsed\t%s\texpected_now\t%s\ton_pace\t%s"
          % (res["horizon_date"] or "미설정",
             "-" if res["days_left"] is None else res["days_left"],
             "-" if res["frac_elapsed"] is None else "%.0f%%" % (res["frac_elapsed"] * 100),
             "-" if res["expected_now"] is None else _fmeas(res["expected_now"]),
             "미정" if res["on_pace"] is None else int(bool(res["on_pace"]))))
    if res["blocked_on"]:
        print("BLOCKED_ON\t%s" % ",".join(res["blocked_on"]))


