_DISPATCH.update((v, _training_axis_verb(v)) for v in _TRAINING_AXIS_VERBS)


# Verbs that change what today's schedule LOOKS LIKE. Cadence leg 2 of 3 for
# the pinned day card: the moment the day actually changes is the moment the
# pin is wrong, and a pin that is wrong is worse than no pin because it still
# looks live. Reads, settles of past rows and non-schedule domains (meals,
# spend, goals) are deliberately absent -- they move no row on the card.
DAY_CARD_REFRESH_VERBS = frozenset((
    'appt-add', 'appt-upd', 'appt-cancel', 'appt-del', 'appt-person',
    'appt-person-rm', 'block-person', 'block-person-rm', 'appt-travel-attach',
    'presence-add', 'presence-move', 'presence-cancel', 'presence-revive',
    'task-add', 'task-done', 'task-undone', 'task-reschedule', 'task-undate',
    'task-retitle', 'task-archive',
    'routine-travel-attach', 'travel-move', 'travel-skip', 'travel-unpin',
    'travel-refresh', 'travel-sweep', 'travel-rule-add', 'travel-rule-upd',
    'travel-rule-retire', 'travel-place-add', 'travel-place-upd',
    'travel-edge-add', 'travel-dedupe', 'event-notify',
))


def _day_card_refresh():
    """Fire-and-forget refresh of the pinned day card after a schedule write.

    STRICTLY BEST-EFFORT and strictly silent. Every failure mode -- no
    routine on this install, no dashboard, no python, a busy lock -- is a
    no-op, because a write verb must never fail, slow down or print because a
    display surface could not be updated. Detached (start_new_session) so the
    verb's own exit is not held by the pin write.

    Knob LIFEKIT_DAY_CARD_PIN=off disables the leg entirely; a checkout with
    no routines/bundle/day-card.sh (this pack's own test tree, any non-agent
    consumer) is already a no-op with the knob untouched."""
    try:
        import subprocess           # lazy: every other verb pays nothing
        if agent_conf.conf_str("LIFEKIT_DAY_CARD_PIN", "on") != "on":
            return
        script = os.path.join(os.path.dirname(SCRIPT_DIR), "routines",
                              "bundle", "day-card.sh")
        if not os.path.isfile(script):
            return
        with open(os.devnull, "wb") as null:
            subprocess.Popen(["/bin/bash", script], stdout=null, stderr=null,
                             stdin=null, start_new_session=True)
    except Exception:
        pass


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if not argv:
        _err(USAGE)
    cmd, rest = argv[0], argv[1:]
    if cmd in ('source-set', 'source-list', 'intake-add', 'intake-list',
               'intake-resolve', 'match-rule-set', 'match-rule-list',
               'import-csv', 'ledger-archive-reset', 'intake-forget',
               'intake-count', 'spend-block'):
        import intake               # 059 kit intake layer (INTAKE.md)
        return intake.cli(sys.modules[__name__], cmd, rest)
    if cmd in ('snapshot', 'snapshot-restore'):
        import db_snapshot          # WAL-safe binary snapshot/restore
        sys.exit(db_snapshot.cli(DB_PATH, cmd, rest))
    if cmd == 'retro-sections':
        import retro_sections       # 2.28.0 retro extension point; no DB
        return retro_sections.cli(SCRIPT_DIR, rest)
    if cmd == 'skill-alias':
        import skill_alias          # 2.38.0 slot rename: old id -> new id
        sys.exit(skill_alias.cli(SCRIPT_DIR, rest))
    if cmd == 'vocab':
        # DGN-1694 voice vocabulary (manifest vocab_verb). Dispatched before
        # anything can reach get_conn(): read-only, never migrates.
        import vocab
        return vocab.cli(DB_PATH, rest)
    fn = _DISPATCH.get(cmd)
    if fn is None:
        print(f"알 수 없는 명령: {cmd}", file=sys.stderr)
        print("(meal-add|meal-find|meal-day|meal-del|meal-upd|workout-add|"
              "workout-find|workout-del|agg-day|agg-week|rotation-current|"
              "spend-add|spend-find|spend-day|spend-del|spend-upd|"
              "spend-week|spend-month|spend-unknown|"
              "entity-list|entity-flow|entity-time|criterion-list|"
              "method-add|method-list|method-alias-add|method-upd|method-link|method-del|"
              "fixed-add|fixed-list|fixed-upd|fixed-del|"
              "guard-get|guard-set|"
              "travel-sweep|travel-refresh|appt-travel-attach|"
              "travel-place-add|travel-edge-add|"
              "pain-add|pain-list|pain-recent|pain-resolve|pain-show|"
              "pain-link|pain-audit|pain-candidates|"
              "muscle-state|muscle-week|body-signal-add|body-signal-list|"
              "body-signal-resolve|body-signal-del|exercise-add|"
              "exercise-drafts|exercise-confirm|exercise-tag-del|"
              "workout-unclassify|"
              "ingest-consent|ingest-check|ingest-put|ingest-get|"
              "ingest-status|metric-register|"
              "drill-load-last|machine-register|machine-list|"
              "machine-last|machine-grid|machine-snap|machine-upd|"
              "muscle-focus|muscle-vocab|"
              "carry-add|carry-list|carry-upd|carry-pack|"
              "routine-prep-add|routine-prep-rm|routine-prep-list|"
              "prep-add|prep-rm|prep-list|prep-set|"
              "near-match-check|near-match-accept|near-match-refuse|"
              "food-merge|foodcache-alias-del|"
              "trend|retro-sections|skill-alias|inspect|snapshot|snapshot-restore|vocab)", file=sys.stderr)
        sys.exit(1)
    fn(rest)
    # Only a verb that RETURNED gets here: _err()/sys.exit() refusals and the
    # EXISTS(3) reconcile path skip the refresh, which is right -- nothing
    # changed, so nothing on the card moved.
    if cmd in DAY_CARD_REFRESH_VERBS:
        _day_card_refresh()


if __name__ == '__main__':
    main()
